/// Stable error code returned when a generic task lifecycle surface targets
/// the server-owned app-workflow namespace. App runs are terminally settled
/// by their typed workflow protocol, which owns resource/effect closure and
/// cannot be replaced by an untyped task status write or task deletion.
pub const APP_WORKFLOW_GENERIC_LIFECYCLE_DENIED: &str = "app_workflow_generic_lifecycle_denied";

fn app_run_task_status_is_terminal(status: &str) -> bool {
    matches!(
        status,
        "completed" | "failed" | "cancelled" | "archived" | "uncertain"
    )
}

#[derive(Debug, Error)]
pub enum ArtifactV2Error {
    #[error("io error: {0}")]
    Io(#[from] std::io::Error),

    #[error("serialization error: {0}")]
    Serde(#[from] serde_json::Error),

    #[error("task not found: {0}")]
    TaskNotFound(String),

    #[error("task plan not found: {0}")]
    TaskPlanNotFound(String),

    #[error("execution not found: {0}")]
    ExecutionNotFound(String),

    #[error("invalid request: {0}")]
    InvalidRequest(String),

    #[error("runtime error: {0}")]
    Runtime(String),

    /// The event bytes and their new commit marker are visible, but the
    /// marker's parent-directory durability could not be confirmed. Callers
    /// must not retry this as an ordinary failed append because readers may
    /// already expose the event and a retry would duplicate it.
    #[error(
        "canonical event commit is uncertain at {commit_path} ({committed_len} bytes): {reason}"
    )]
    CommitUncertain {
        commit_path: String,
        committed_len: u64,
        reason: String,
    },

    /// The clarification/HITL question this request targets was already
    /// answered/resolved (double-submit, resolved-elsewhere, post-restart
    /// replay). Distinct from `InvalidRequest` (a genuine bad request) and
    /// `Runtime` (an internal 500): callers/`map_result` should render this
    /// as a dismissable soft-success (HTTP 409 + `reason: "already_resolved"`)
    /// so an already-answered clarification card is dismissed instead of
    /// sticking with a hard error. Constructed from the ask-loop's
    /// `TriggerError::AlreadyResolved` on the clarification-submit path.
    #[error("already resolved: {0}")]
    AlreadyResolved(String),
}

