/// App-facing projection of the sealed callable-agent carrier. No task,
/// execution, launch or artifact identifier is present. Completed values are
/// paired with the ordinary current-authority workflow-continuation record;
/// cancellation and uncertainty remain control-only outcomes.
pub(crate) enum AppAgentToolAppResult {
    Completed {
        value: Value,
        labeled_record: crate::magician_v2::apps::tool_disclosure::AppLabeledToolResultRecord,
    },
    Cancelled {
        value: Value,
        labeled_record: crate::magician_v2::apps::tool_disclosure::AppLabeledToolResultRecord,
    },
    OutcomeUncertain {
        value: Value,
        failure_code: String,
        labeled_record: crate::magician_v2::apps::tool_disclosure::AppLabeledToolResultRecord,
    },
}

fn app_agent_tool_terminal_uses_effect_proof(status: &str) -> bool {
    status == "completed"
}

/// An Attached callable-agent shell is restart-adoptable only before its V3
/// execution has started. Every other nonterminal status means the process may
/// have crossed the physical model-I/O boundary; replay is forbidden and
/// startup must conservatively fail/settle the exact governed leaf.
fn app_agent_tool_restart_requires_uncertain_failure(status: &str) -> bool {
    !matches!(
        status,
        "pending" | "ready" | "queued" | "completed" | "failed" | "cancelled" | "canceled"
    )
}

fn app_agent_tool_startup_should_fail_attached_child(
    status: &str,
    adopted_by_this_sweep: bool,
) -> bool {
    !adopted_by_this_sweep && app_agent_tool_restart_requires_uncertain_failure(status)
}

