const DELEGATED_CHILD_RECOVERY_PAYLOAD_MAX_BYTES: usize = 1024 * 1024;
// JSON field names, schema and the fixed-size HMAC wrap the authoritative
// payload. Keep a distinct read ceiling so a valid near-limit payload cannot
// be written successfully and then rejected by its own sealed envelope.
const DELEGATED_CHILD_RECOVERY_ENVELOPE_MAX_BYTES: usize =
    DELEGATED_CHILD_RECOVERY_PAYLOAD_MAX_BYTES + 4 * 1024;
