#[derive(Debug)]
struct DeadlineRecoveryQueue<T> {
    candidates: HashMap<String, (i64, T)>,
    deadlines: BinaryHeap<Reverse<(i64, u64, String)>>,
    next_sequence: u64,
}

impl<T> Default for DeadlineRecoveryQueue<T> {
    fn default() -> Self {
        Self {
            candidates: HashMap::new(),
            deadlines: BinaryHeap::new(),
            next_sequence: 0,
        }
    }
}

impl<T> DeadlineRecoveryQueue<T> {
    fn insert(&mut self, key: String, deadline_ms: i64, candidate: T) {
        self.next_sequence = self.next_sequence.saturating_add(1);
        self.deadlines
            .push(Reverse((deadline_ms, self.next_sequence, key.clone())));
        self.candidates.insert(key, (deadline_ms, candidate));
    }

    fn pop_due(&mut self, now_ms: i64) -> Option<(String, T)> {
        loop {
            let Reverse((deadline_ms, _, key)) = self.deadlines.peek()?.clone();
            if deadline_ms > now_ms {
                return None;
            }
            self.deadlines.pop();
            let Some((current_deadline_ms, _)) = self.candidates.get(&key) else {
                continue;
            };
            if *current_deadline_ms != deadline_ms {
                continue;
            }
            let (_, candidate) = self
                .candidates
                .remove(&key)
                .expect("deadline candidate remained present");
            return Some((key, candidate));
        }
    }

    fn next_deadline_ms(&mut self) -> Option<i64> {
        loop {
            let Reverse((deadline_ms, _, key)) = self.deadlines.peek()?.clone();
            match self.candidates.get(&key) {
                Some((current_deadline_ms, _)) if *current_deadline_ms == deadline_ms => {
                    return Some(deadline_ms)
                },
                _ => {
                    self.deadlines.pop();
                },
            }
        }
    }
}

