impl Drop for TaskPlanningRecoveryMonitorGuard {
    fn drop(&mut self) {
        self.active
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .remove(&self.key);
    }
}

/// Mutable outer-pipeline checkpoint, stored under the restricted scope tree.
/// `roster_hmac_sha256` binds every revision to the immutable roster seal;
/// `revision` is the cross-process compare-and-swap generation.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub(crate) struct ExecutionPipelineProgress {
    schema_version: u8,
    pub(crate) revision: u64,
    roster_hmac_sha256: String,
    stage_count: usize,
    pub(crate) next_stage_index: usize,
    pub(crate) active_stage_index: Option<usize>,
    pub(crate) active_stage_paused: bool,
    pub(crate) active_stage_resume_segment: Option<String>,
    pub(crate) active_stage_deadline_at_ms: Option<i64>,
    pub(crate) active_stage_baseline: Option<ExecutionPipelineDeliverableCursor>,
    pub(crate) deliverables: Vec<crate::magician_v2::execution::ChildDeliverableSummary>,
    /// Exact, bounded disclosure of payload removed only to keep this mutable
    /// checkpoint within its cumulative text/media ceilings. Keeping this
    /// separate from the retained payload means a late stage remains visibly
    /// lossy even when earlier stages consumed every available text byte.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub(crate) deliverable_omissions: Vec<ExecutionPipelineDeliverableOmission>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub(crate) struct ExecutionPipelineDeliverableOmission {
    pub(crate) stage_index: usize,
    #[serde(default, skip_serializing_if = "is_zero_usize")]
    pub(crate) primary_text_bytes: usize,
    #[serde(default, skip_serializing_if = "is_zero_usize")]
    pub(crate) media_refs: usize,
}

fn is_zero_usize(value: &usize) -> bool {
    *value == 0
}

impl ExecutionPipelineProgress {
    /// Rehydrate bounded omission disclosures for stage-to-stage context and
    /// the final aggregate. The authoritative checkpoint keeps the exact
    /// counts separately so the marker remains available even when retained
    /// text has exhausted the 64-KiB payload budget.
    pub(crate) fn disclosed_deliverables(
        &self,
    ) -> Vec<crate::magician_v2::execution::ChildDeliverableSummary> {
        let mut disclosed = self.deliverables.clone();
        for omission in &self.deliverable_omissions {
            let Some(deliverable) = disclosed.get_mut(omission.stage_index) else {
                continue;
            };
            let marker = format!(
                "[pipeline deliverable bounded: {} UTF-8 byte(s) and {} media reference(s) omitted]",
                omission.primary_text_bytes, omission.media_refs,
            );
            match deliverable.primary_text.as_mut() {
                Some(text) if !text.is_empty() => {
                    text.push_str("\n\n");
                    text.push_str(&marker);
                },
                _ => deliverable.primary_text = Some(marker),
            }
        }
        disclosed
    }
}

/// Constant-size proof of the cumulative Artifact output observed immediately
/// before a stage started. A length without a digest would silently accept a
/// rewritten prefix after restart; retaining the full prefix would make the
/// mutable checkpoint unbounded. Both text and media therefore use a
/// length-plus-BLAKE3 cursor and are verified before any suffix is attributed
/// to the active stage.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub(crate) struct ExecutionPipelineDeliverableCursor {
    pub(crate) text_byte_len: usize,
    pub(crate) text_blake3: String,
    pub(crate) media_len: usize,
    pub(crate) media_blake3: String,
}

#[derive(Debug, Clone)]
pub(crate) struct ExecutionPipelineContinuationBinding {
    pub(crate) scope: ScopeRef,
    pub(crate) task_id: String,
    pub(crate) stages: Vec<crate::magician_v2::execution::PipelineStage>,
    pub(crate) progress: ExecutionPipelineProgress,
}

/// Crash-stable bridge between the Artifact parent reducer and the loop-store
/// handoff receipt. The pending-pause projection is terminal cleanup data and
/// may be removed by parent settlement before the wake receipt is consumed;
/// this execution-owned copy preserves the exact address through that window.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
struct ExecutionStatelessChildrenHandoff {
    schema_version: u8,
    principal: String,
    workspace: String,
    task_id: String,
    parent_execution_id: String,
    source: crate::magician_v2::execution::agentic::run_loop::store::ExecutionKey,
    resumes_as: String,
    expected_child_execution_ids: Vec<String>,
    wake_token: Option<String>,
    resolution_id: Option<String>,
}

/// Integrity envelope for an execution-local descriptor that can retire one
/// exact loop segment and authorize its successor. The path is diagnostic
/// placement, not authority: scope/task/parent identity is repeated in the
/// payload and in the scoped HMAC so copying a valid descriptor to another
/// execution directory cannot redirect that execution's recovery.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
struct ExecutionStatelessChildrenHandoffSeal {
    schema_version: u8,
    hmac_sha256: String,
    descriptor: ExecutionStatelessChildrenHandoff,
}

#[derive(Debug)]
pub(crate) struct CrossProcessTaskGuard {
    file: File,
}

/// Shared Artifact/runtime transaction fence for one task. Pipeline progress
/// commits and runtime cancellation both use this exact flock so the durable
/// ordering is unambiguous across processes: either the stage CAS observes an
/// active runtime and commits first, or cancellation publishes `Cancelled`
/// first and every later stage CAS refuses.
pub(crate) async fn acquire_pipeline_task_transaction_guard(
    workspace: &ArtifactV2Workspace,
    principal: &str,
    workspace_id: &str,
    task_id: &str,
) -> Result<CrossProcessTaskGuard, ArtifactV2Error> {
    ArtifactV2Workspace::validate_task_id(task_id)?;
    let lock_path = workspace.task_lock_path(principal, workspace_id, task_id);
    let parent = lock_path.parent().ok_or_else(|| {
        ArtifactV2Error::InvalidRequest("task_transaction_lock_parent_missing".to_owned())
    })?;
    let scope_root = workspace.scope_root(principal, workspace_id);
    crate::magician_v2::agents::AgentStorage::new(&scope_root)
        .ensure_private_directory(parent)
        .await
        .map_err(|error| {
            ArtifactV2Error::Runtime(format!(
                "task_transaction_lock_directory_security_failed:{error}"
            ))
        })?;
    let file = magician_core::blocking_admission::spawn_blocking_admitted(
        move || -> Result<File, std::io::Error> {
            retry_transient_io_blocking(|| {
                let mut options = OpenOptions::new();
                options.create(true).read(true).write(true).truncate(false);
                #[cfg(unix)]
                {
                    use std::os::unix::fs::OpenOptionsExt;
                    options
                        .mode(0o600)
                        .custom_flags(libc::O_NOFOLLOW | libc::O_CLOEXEC);
                }
                let file = options.open(&lock_path)?;
                #[cfg(unix)]
                {
                    use std::os::unix::fs::{MetadataExt, PermissionsExt};
                    let metadata = file.metadata()?;
                    if !metadata.is_file()
                        || metadata.uid() != unsafe { libc::geteuid() }
                        || metadata.nlink() != 1
                    {
                        return Err(std::io::Error::new(
                            std::io::ErrorKind::PermissionDenied,
                            "task transaction lock failed owner/type/link validation",
                        ));
                    }
                    file.set_permissions(std::fs::Permissions::from_mode(0o600))?;
                }
                file.lock_exclusive()?;
                crate::magician_v2::agents::storage::validate_locked_file_path_identity(
                    &file,
                    &lock_path,
                    "task transaction lock",
                )?;
                #[cfg(unix)]
                {
                    use std::os::unix::fs::MetadataExt;
                    let metadata = file.metadata()?;
                    if !metadata.is_file()
                        || metadata.uid() != unsafe { libc::geteuid() }
                        || metadata.mode() & 0o777 != 0o600
                        || metadata.nlink() != 1
                    {
                        return Err(std::io::Error::new(
                            std::io::ErrorKind::PermissionDenied,
                            "task transaction lock failed post-lock security validation",
                        ));
                    }
                }
                Ok(file)
            })
        },
    )
    .await
    .map_err(|err| ArtifactV2Error::Runtime(format!("task lock task panicked: {err}")))??;
    Ok(CrossProcessTaskGuard { file })
}

