    pub fn with_voice_downstream_fanout(self, registry: Arc<VoiceDownstreamFanout>) -> Self {
        self.set_voice_downstream_fanout(registry);
        self
    }

    /// The same wiring for a service that is already behind an `Arc` — the
    /// registry lives in a `OnceLock` shared by every clone, so this needs no
    /// ownership. `bin/magician.rs` uses the builder; recovery paths and tests
    /// that hold an `Arc<ArtifactV2Service>` cannot.
    pub fn set_voice_downstream_fanout(&self, registry: Arc<VoiceDownstreamFanout>) {
        let _ = self.voice_downstream_fanout.set(registry);
    }

