    pub async fn record_delegation_launch_dispatched(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        parent_execution_id: &str,
        step_id: &str,
        sub_goal: &str,
        target_agent_id: &str,
        child_execution_id: &str,
    ) -> Result<(), ArtifactV2Error> {
        let now = now_rfc3339();
        self.reducer
            .reduce_delegated_child_link(
                scope,
                task_id,
                parent_execution_id,
                child_execution_id,
                target_agent_id,
                sub_goal,
                &now,
            )
            .await?;

        // Operator-facing: emit a `DelegationIssued` update. The originating
        // parent agent's id is not exposed at this call site — the
        // dispatcher only carries parent_execution_id. Use a readable
        // placeholder in `from_agent` so the feed card reads sensibly. A
        // follow-up can thread the parent agent id through.
        if let Some(broadcaster) = self.runtime_event_broadcaster.get() {
            let update = crate::magician_v2::agents::agent_update::AgentUpdate::new(
                scope.workspace().to_string(),
                target_agent_id.to_string(),
                crate::magician_v2::agents::agent_update::AgentUpdateKind::DelegationIssued {
                    from_agent: format!("parent:{}", parent_execution_id),
                    to_agent: target_agent_id.to_string(),
                    task_id: task_id.to_string(),
                },
            );
            crate::magician_v2::agents::agent_update_emitter::publish_agent_update(
                broadcaster,
                Some(scope.principal()),
                Some(scope.workspace()),
                update,
            );
        }
        self.event_writer
            .append(
                &ExecutionContext {
                    principal: scope.principal().to_string(),
                    workspace: scope.workspace().to_string(),
                    task_id: task_id.to_string(),
                    execution_id: parent_execution_id.to_string(),
                },
                ArtifactV2EventType::DelegationLaunchDispatched,
                json!({
                    "step_id": step_id,
                    "sub_goal": sub_goal,
                    "target_agent_id": target_agent_id,
                    "child_execution_id": child_execution_id,
                }),
            )
            .await?;
        if let Err(err) = self
            .attach_delegated_child_execution_once(
                scope,
                task_id,
                parent_execution_id,
                child_execution_id,
                target_agent_id,
                sub_goal,
            )
            .await
        {
            warn!(
                error = %err,
                task_id = %task_id,
                parent_execution_id = %parent_execution_id,
                child_execution_id = %child_execution_id,
                "[ARTIFACT-V2] Immediate delegated child attachment failed; scheduling retry"
            );
            self.schedule_delegated_child_attachment(
                scope,
                task_id,
                parent_execution_id,
                child_execution_id,
                target_agent_id,
                sub_goal,
            )
            .await;
        }
        self.spawn_task_progress_projection(
            scope.clone(),
            task_id.to_string(),
            "delegation_launch_dispatched",
        );
        Ok(())
    }

    pub async fn record_unmatched_child_launch_dispatched(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        parent_execution_id: &str,
        child_execution_id: &str,
        child_agent_id: &str,
    ) -> Result<(), ArtifactV2Error> {
        self.event_writer
            .append(
                &ExecutionContext {
                    principal: scope.principal().to_string(),
                    workspace: scope.workspace().to_string(),
                    task_id: task_id.to_string(),
                    execution_id: parent_execution_id.to_string(),
                },
                ArtifactV2EventType::DelegationUnmatchedChildDispatched,
                json!({
                    "child_execution_id": child_execution_id,
                    "child_agent_id": child_agent_id,
                }),
            )
            .await?;
        // The launch event is the first crash-recovery authority. Also project
        // the same immutable child identity into the parent record before the
        // best-effort attachment: future startup passes can recover without
        // depending on the bounded event tail after this point.
        self.reducer
            .reduce_delegated_child_link(
                scope,
                task_id,
                parent_execution_id,
                child_execution_id,
                child_agent_id,
                "",
                &now_rfc3339(),
            )
            .await?;
        if let Err(err) = self
            .attach_delegated_child_execution_once(
                scope,
                task_id,
                parent_execution_id,
                child_execution_id,
                child_agent_id,
                "",
            )
            .await
        {
            warn!(
                error = %err,
                task_id = %task_id,
                parent_execution_id = %parent_execution_id,
                child_execution_id = %child_execution_id,
                "[ARTIFACT-V2] Immediate unmatched child attachment failed; scheduling retry"
            );
            self.schedule_delegated_child_attachment(
                scope,
                task_id,
                parent_execution_id,
                child_execution_id,
                child_agent_id,
                "",
            )
            .await;
        }
        self.spawn_task_progress_projection(
            scope.clone(),
            task_id.to_string(),
            "unmatched_child_launch_dispatched",
        );
        Ok(())
    }

    pub async fn list_attention_items(
        &self,
        scope: &ScopeRef,
        ui_thread_id: Option<&str>,
    ) -> Result<Vec<FeedItem>, ArtifactV2Error> {
        // Include BOTH user-visible tasks under `tasks/` AND ephemeral
        // chat-delegated tasks under `internal_tasks/`. The latter
        // never appear in `list_tasks` (intentional — keeps the
        // user-facing task list focused on persistent work), but they
        // CAN emit HITL requests when the delegate worker asks for
        // input or external action. Without this merge those HITL
        // prompts never reach the attention bar, leaving the chat
        // waiting silently until the user notices the prompt inside
        // the chat bubble's pause card.
        //
        // We still defer to each task's own `attention_kind` allow-list
        // below, so internal tasks contribute attention items only for
        // the same event types the user-facing tasks do.
        // ONE walk of each approval store for the ENTIRE poll.
        //
        // Five things in this function ask the same two directories the same
        // question — both listings' cards, this loop's own gate, the projection
        // taken on a snapshot miss, and the voice announcement — and every one
        // of them used to walk the store itself, per task. On a scope with M
        // tasks and F stored proposals that is O(M×F) file reads of records
        // that are mostly unified diff, twice over, on a 15s poll. Taking the
        // snapshots here and threading them down makes it O(F).
        //
        // A snapshot rather than a cache: it lives for this request only, so
        // the staleness window is the one the per-task calls already had
        // between the first task and the last.
        let pending_proposals = self.pending_diff_approvals(scope);
        let pending_transactions = self.pending_file_edit_transactions(scope);

        let user_tasks = self
            .list_tasks_with_pending(scope, &pending_proposals)
            .await?;
        let internal_tasks = self
            .list_internal_tasks_with_pending(scope, &pending_proposals)
            .await?;
        let mut items = Vec::new();

        // The same poll, one surface further out: a hands-free caller cannot
        // see this feed, so a diff waiting on them is silence until they
        // happen to look. Deliberately here rather than at the moment a
        // proposal is staged — an announcement fired from that event would be
        // lost by the restart the criterion is about, whereas this re-derives
        // the state and dedupes against a durable log. Scope-wide, ignoring
        // `ui_thread_id`, because the announcement is about the *call*, not
        // about which slice of the feed this particular request asked for.
        self.announce_pending_diff_approvals_to_voice_with(scope, &pending_proposals)
            .await;

        // ----- Authoritative still-pending state for HITL attention cards -----
        // The serve path reads a CACHED `attention_projection.json` snapshot
        // first and only falls back to the live projection when there is no
        // snapshot. The build-path state gate (`build_attention_summaries`) runs
        // ONLY on that live-projection branch, so a finished task whose snapshot
        // is cached keeps showing a resolved "owner briefing" / "code apply"
        // card. Re-apply the SAME authoritative store gate HERE, per poll, on
        // whichever summary the serve path picked — snapshot or projection — so
        // the feed reflects current store state every time.
        //
        // user_request: computed ONCE for the whole scope (the pending map is
        // scope-, not task-, keyed). `None` = the service isn't wired (some
        // harness contexts) → user_request cards are NOT gated (kept). An empty
        // `Some(set)` from a wired service would drop every user_request card,
        // so we must never substitute an empty set for "not consulted".
        let pending_user_request_ids: Option<std::collections::HashSet<String>> =
            match self.orchestrator.user_request_service() {
                Some(service) => Some(
                    service
                        .list_pending_for_scope(&scope.principal(), &scope.workspace())
                        .await
                        .into_iter()
                        .map(|request| request.id)
                        .collect(),
                ),
                None => None,
            };

        for task in user_tasks.into_iter().chain(internal_tasks.into_iter()) {
            if ui_thread_id
                .map(|expected| task.ui_thread_id == expected)
                .unwrap_or(true)
            {
                let (attention_task, attention_items) =
                    match self.load_task_attention_snapshot(scope, &task.id).await? {
                        Some(snapshot) => (snapshot.task, snapshot.attention),
                        None => {
                            let projection = self
                                .task_progress_projection_with_pending(
                                    scope,
                                    &task.id,
                                    &pending_proposals,
                                    &pending_transactions,
                                )
                                .await?;
                            (projection.task, projection.attention)
                        },
                    };

                // diff_approval: per-task set of proposal ids ("ccp-<uuid>")
                // still in `Pending`. The snapshot is EMPTY for a task with
                // nothing staged, which is the correct authoritative "no
                // pending proposals → drop diff_approval cards for this task" —
                // so proposals ARE gated on an empty `Some(set)` (unlike
                // user_requests, whose empty set could mean "service missing").
                // Wrapped in `Some(..)` because both stores are always
                // consulted, once, at the top of this poll.
                let pending_proposal_ids: Option<HashSet<String>> = {
                    let mut pending: HashSet<String> = pending_proposals
                        .proposal_ids_for_task(&task.id)
                        .iter()
                        .cloned()
                        .collect();
                    // A transaction stamped with no task id belongs to every
                    // task's gate, exactly as the per-task `map_or(true, ..)`
                    // filter had it.
                    pending_transactions.extend_ids_for_task(&task.id, &mut pending);
                    Some(pending)
                };

                // A terminal task's Pending code-change proposal is orphaned —
                // used to drop its "approve coding changes" card below.
                let owning_task_is_terminal = task_status_is_terminal(&task.status);
                for attention in &attention_items {
                    let pause_is_pending = match attention.pause_state_id.as_deref() {
                        Some(pause_id) => {
                            self.orchestrator
                                .resumable_pause_is_pending_scoped(
                                    &attention.execution_id,
                                    pause_id,
                                    scope.principal(),
                                    scope.workspace(),
                                )
                                .await
                        },
                        None => None,
                    };
                    if !agentic_attention_is_still_actionable(
                        attention,
                        owning_task_is_terminal,
                        pause_is_pending,
                    ) {
                        continue;
                    }
                    // Serve-path state gate: drop a resolved owner-briefing /
                    // code-apply card even when it came from a cached snapshot
                    // that the build-path gate never re-ran. Fail-open: any
                    // "store not consulted" case keeps the card.
                    if !attention_is_still_actionable(
                        attention,
                        pending_user_request_ids.as_ref(),
                        pending_proposal_ids.as_ref(),
                        owning_task_is_terminal,
                    ) {
                        continue;
                    }
                    if matches!(
                        attention.attention_kind.as_str(),
                        "input.requested"
                            | "waiting_for_confirmation"
                            | "max_iterations_reached"
                            | "user_request.pending"
                            | "hitl.requested"
                            | "agent.circuit.opened"
                            | "agent.cycle.failed"
                            | "agent.goal.failed"
                    ) {
                        items.push(build_attention_feed_item(&attention_task, attention));
                    }
                }
            }
        }
        items.sort_by(|left, right| {
            right
                .updated_at
                .cmp(&left.updated_at)
                .then_with(|| left.id.cmp(&right.id))
        });
        Ok(items)
    }

    /// Read a run's newest `coding.*` event window from the durable per-execution
    /// `coding_events.jsonl` logs (written by `run_coding_task`), merged across
    /// the task's executions and sorted ascending by `timestamp_ms`. This is the
    /// retention-immune source the cockpit hydrates a finished run from: the
    /// scope transport log keeps only the newest ~2000 events, so a long coding
    /// run (≈10k events) loses almost all of its detail once it ages past the
    /// window. Ascending order so coalesced deltas + `coding.turn.started` fold
    /// into the same per-turn cards the live stream produces. Returns at most
    /// `limit` events within the aggregate encoded-response byte ceiling.
    pub async fn read_run_coding_events(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        limit: usize,
    ) -> Result<Vec<serde_json::Value>, ArtifactV2Error> {
        let executions_root =
            self.workspace
                .executions_root(&scope.principal(), &scope.workspace(), task_id);
        let entries = self
            .workspace
            .read_dir_path_or_empty(&executions_root)
            .await?;
        if limit == 0 {
            return Ok(Vec::new());
        }
        let paths = entries
            .into_iter()
            .enumerate()
            .filter(|(_, entry)| entry.is_dir)
            .map(|(directory_order, entry)| {
                (
                    directory_order,
                    executions_root
                        .join(&entry.file_name)
                        .join("coding_events.jsonl"),
                )
            })
            .collect();
        Self::read_recent_coding_event_logs(paths, limit).await
    }

    /// Two-pass bounded merge. The first pass reads only the first admitted
    /// event in each execution to recover the old group ordering. The second
    /// streams those files in that order through one global `limit`-sized
    /// deque. This preserves file-causal order across wall-clock steps without
    /// retaining a lifetime log or one `limit`-sized group per execution.
    async fn read_recent_coding_event_logs(
        paths: Vec<(usize, PathBuf)>,
        limit: usize,
    ) -> Result<Vec<Value>, ArtifactV2Error> {
        Self::read_recent_coding_event_logs_with_budget(
            paths,
            limit,
            MAX_CODING_EVENT_RESPONSE_BYTES,
        )
        .await
    }

    async fn read_recent_coding_event_logs_with_budget(
        paths: Vec<(usize, PathBuf)>,
        limit: usize,
        retained_bytes_limit: usize,
    ) -> Result<Vec<Value>, ArtifactV2Error> {
        if limit == 0 {
            return Ok(Vec::new());
        }
        let mut ordered = Vec::<(i64, usize, PathBuf)>::with_capacity(paths.len());
        for (directory_order, path) in paths {
            let mut first_ts = None;
            let result = Self::visit_coding_event_records(&path, |value, _record_bytes| {
                first_ts = Some(
                    value
                        .get("timestamp_ms")
                        .and_then(Value::as_i64)
                        .unwrap_or(0),
                );
                // The ordering pass retains only the scalar timestamp. Drain
                // the admitted record with heap frames instead of recursively
                // dropping its potentially deep payload on this async worker.
                discard_json_iteratively(value);
                false
            })
            .await;
            match result {
                Ok(()) if first_ts.is_some() => {
                    ordered.push((first_ts.unwrap_or_default(), directory_order, path));
                },
                Ok(()) => {},
                Err(error) => debug!(
                    path = %path.display(),
                    error = %error,
                    "[ARTIFACT-V2] Skipping unreadable coding event log"
                ),
            }
        }
        ordered.sort_by(|left, right| left.0.cmp(&right.0).then_with(|| left.1.cmp(&right.1)));

        let mut newest = VecDeque::<(Value, usize)>::with_capacity(limit.min(4_096));
        // For a non-empty JSON array, exact compact wire size is one byte for
        // the opening bracket plus `(record_bytes + 1)` per element (a comma
        // or the closing bracket). Count that framing too; bounding only raw
        // line bytes allowed a high-cardinality response to exceed its stated
        // aggregate ceiling by one byte per retained event.
        let mut retained_units = 0usize;
        for (expected_first_ts, _, path) in ordered {
            let mut first_record_seen = false;
            let mut ordering_changed = false;
            let result = Self::visit_coding_event_records(&path, |value, record_bytes| {
                if !first_record_seen {
                    first_record_seen = true;
                    let observed_first_ts = value
                        .get("timestamp_ms")
                        .and_then(Value::as_i64)
                        .unwrap_or(0);
                    if observed_first_ts != expected_first_ts {
                        ordering_changed = true;
                        discard_json_iteratively(value);
                        return false;
                    }
                }
                let retained_record_units = record_bytes.saturating_add(1);
                retained_units = retained_units.saturating_add(retained_record_units);
                newest.push_back((value, retained_record_units));
                while newest.len() > limit
                    || 1usize.saturating_add(retained_units) > retained_bytes_limit
                {
                    if let Some((evicted, evicted_units)) = newest.pop_front() {
                        retained_units = retained_units.saturating_sub(evicted_units);
                        discard_json_iteratively(evicted);
                    } else {
                        break;
                    }
                }
                true
            })
            .await;
            match result {
                Ok(()) if ordering_changed => debug!(
                    path = %path.display(),
                    expected_first_ts,
                    "[ARTIFACT-V2] Skipping coding event log replaced between merge passes"
                ),
                Ok(()) => {},
                Err(error) => debug!(
                    path = %path.display(),
                    error = %error,
                    "[ARTIFACT-V2] Coding event replay retained only the admitted readable prefix"
                ),
            }
        }
        Ok(newest.into_iter().map(|(value, _)| value).collect())
    }

    /// Visit complete, admitted JSONL records with fixed-size I/O and one
    /// capped record buffer. Unterminated EOF bytes are an uncommitted crash
    /// tail. Malformed/over-limit complete records retain the legacy tolerant
    /// behavior (skip and continue), but can no longer allocate or recurse
    /// without a bound before rejection.
    async fn visit_coding_event_records(
        path: &Path,
        mut visitor: impl FnMut(Value, usize) -> bool,
    ) -> Result<(), ArtifactV2Error> {
        let mut file = fs::File::open(path).await?;
        let file_len = file.metadata().await?.len();
        let mut chunk = vec![0_u8; CODING_EVENT_READ_CHUNK_BYTES];
        let mut record = Vec::<u8>::with_capacity(CODING_EVENT_READ_CHUNK_BYTES);
        let mut record_oversized = false;
        let mut bytes_read = 0_u64;
        let mut line_number = 0_u64;

        'records: while bytes_read < file_len {
            let requested = (file_len - bytes_read).min(chunk.len() as u64) as usize;
            let count = file.read(&mut chunk[..requested]).await?;
            if count == 0 {
                return Err(ArtifactV2Error::Io(std::io::Error::new(
                    std::io::ErrorKind::UnexpectedEof,
                    "coding event log shortened during bounded replay",
                )));
            }
            let mut start = 0usize;
            while start < count {
                let newline = chunk[start..count]
                    .iter()
                    .position(|byte| *byte == b'\n')
                    .map(|relative| start + relative);
                let end = newline.unwrap_or(count);
                let segment = &chunk[start..end];
                if !record_oversized {
                    if record
                        .len()
                        .checked_add(segment.len())
                        .is_some_and(|next| next <= MAX_CODING_EVENT_RECORD_BYTES)
                    {
                        record.extend_from_slice(segment);
                    } else {
                        record.clear();
                        record_oversized = true;
                    }
                }
                let consumed = end - start + usize::from(newline.is_some());
                bytes_read = bytes_read.saturating_add(consumed as u64);
                start = end + usize::from(newline.is_some());

                if newline.is_none() {
                    continue;
                }
                line_number = line_number.saturating_add(1);
                let admitted = !record_oversized
                    && json_bytes_nesting_is_bounded(&record, MAX_RETAINED_JSON_DEPTH)
                    && json_bytes_nodes_are_bounded(&record, MAX_CODING_EVENT_RECORD_NODES);
                if admitted && !record.iter().all(u8::is_ascii_whitespace) {
                    match serde_json::from_slice::<Value>(&record) {
                        Ok(value) => {
                            if !visitor(value, record.len()) {
                                break 'records;
                            }
                        },
                        Err(error) => debug!(
                            path = %path.display(),
                            line = line_number,
                            error = %error,
                            "[ARTIFACT-V2] Skipping malformed coding event record"
                        ),
                    }
                } else if record_oversized || !record.iter().all(u8::is_ascii_whitespace) {
                    debug!(
                        path = %path.display(),
                        line = line_number,
                        max_record_bytes = MAX_CODING_EVENT_RECORD_BYTES,
                        max_record_depth = MAX_RETAINED_JSON_DEPTH,
                        max_record_nodes = MAX_CODING_EVENT_RECORD_NODES,
                        "[ARTIFACT-V2] Skipping coding event record outside admission"
                    );
                }
                record.clear();
                record_oversized = false;
            }
        }
        Ok(())
    }

    async fn load_task_attention_snapshot(
        &self,
        scope: &ScopeRef,
        task_id: &str,
    ) -> Result<Option<V3TaskAttentionRecord>, ArtifactV2Error> {
        let path = self.workspace.task_attention_projection_path(
            &scope.principal(),
            &scope.workspace(),
            task_id,
        );
        match self
            .workspace
            .read_json_path::<V3TaskAttentionRecord, _>(&path)
            .await
        {
            Ok(record) => Ok(Some(record)),
            Err(ArtifactV2Error::Io(error)) if error.kind() == std::io::ErrorKind::NotFound => {
                Ok(None)
            },
            Err(error) => Err(error),
        }
    }

    async fn attach_delegated_child_execution_once(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        parent_execution_id: &str,
        child_execution_id: &str,
        child_agent_id: &str,
        sub_goal: &str,
    ) -> Result<(), ArtifactV2Error> {
        let parent_binding = self
            .binding_for_existing_execution(scope, task_id, parent_execution_id)
            .await?;
        let child_ctx = self
            .sync_runtime_child_execution(
                &parent_binding,
                child_execution_id,
                (!child_agent_id.trim().is_empty()).then_some(child_agent_id),
                (!sub_goal.trim().is_empty()).then_some(sub_goal),
            )
            .await?;
        self.start_child_runtime_watch(parent_binding, child_ctx);
        Ok(())
    }

    /// Best-effort: write a V3 ExecutionRecord for a runtime-spawned child execution.
    ///
    /// Resolves the parent's V3 scope/task automatically. Returns `Ok(false)`
    /// only when the exact parent/child Artifact record is positively absent.
    /// Binding, task, integrity, I/O, and decoding failures propagate so an
    /// unreadable or mismatched record is never mistaken for a legacy V2-only
    /// parent.
    pub async fn record_runtime_child_execution_best_effort(
        &self,
        parent_execution_id: &str,
        child_execution_id: &str,
        child_agent_id: &str,
        sub_goal: &str,
    ) -> Result<bool, ArtifactV2Error> {
        let (scope, task_id) = match self
            .resolve_scope_for_execution_id(parent_execution_id)
            .await
        {
            Ok(pair) => pair,
            Err(ArtifactV2Error::ExecutionNotFound(_)) => return Ok(false),
            Err(err) => return Err(err),
        };

        match self
            .attach_delegated_child_execution_once(
                &scope,
                &task_id,
                parent_execution_id,
                child_execution_id,
                child_agent_id,
                sub_goal,
            )
            .await
        {
            Ok(()) => Ok(true),
            Err(ArtifactV2Error::ExecutionNotFound(_)) => Ok(false),
            Err(err) => Err(err),
        }
    }

    async fn schedule_delegated_child_attachment(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        parent_execution_id: &str,
        child_execution_id: &str,
        child_agent_id: &str,
        sub_goal: &str,
    ) {
        let key = format!(
            "{}\u{1f}{}\u{1f}{}\u{1f}{}\u{1f}{}",
            scope.principal(),
            scope.workspace(),
            task_id,
            parent_execution_id,
            child_execution_id,
        );
        let newly_admitted = self
            .active_delegated_child_attachment_recoveries
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .insert(key.clone());
        if newly_admitted {
            self.delegated_child_attachment_recovery_queue
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .insert(
                    key,
                    Utc::now().timestamp_millis(),
                    DelegatedChildAttachmentRecoveryCandidate {
                        scope: scope.clone(),
                        task_id: task_id.to_string(),
                        parent_execution_id: parent_execution_id.to_string(),
                        child_execution_id: child_execution_id.to_string(),
                        child_agent_id: child_agent_id.to_string(),
                        sub_goal: sub_goal.to_string(),
                        scan_cursor: None,
                        retry_attempt: 0,
                    },
                );
            self.delegated_child_attachment_recovery_queue_changed
                .notify_one();
        }
        self.ensure_delegated_child_attachment_recovery_coordinator();
    }

    async fn schedule_delegated_child_attachment_scan(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        parent_execution_id: &str,
        cursor: DelegatedChildAttachmentScanCursor,
    ) {
        let key = format!(
            "scan\u{1f}{}\u{1f}{}\u{1f}{}\u{1f}{}",
            scope.principal(),
            scope.workspace(),
            task_id,
            parent_execution_id,
        );
        let newly_admitted = self
            .active_delegated_child_attachment_recoveries
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .insert(key.clone());
        if newly_admitted {
            self.delegated_child_attachment_recovery_queue
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .insert(
                    key,
                    Utc::now().timestamp_millis(),
                    DelegatedChildAttachmentRecoveryCandidate {
                        scope: scope.clone(),
                        task_id: task_id.to_string(),
                        parent_execution_id: parent_execution_id.to_string(),
                        child_execution_id: String::new(),
                        child_agent_id: String::new(),
                        sub_goal: String::new(),
                        scan_cursor: Some(cursor),
                        retry_attempt: 0,
                    },
                );
            self.delegated_child_attachment_recovery_queue_changed
                .notify_one();
        }
        self.ensure_delegated_child_attachment_recovery_coordinator();
    }

    fn ensure_delegated_child_attachment_recovery_coordinator(&self) {
        if self
            .delegated_child_attachment_recovery_coordinator_active
            .compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire)
            .is_err()
        {
            return;
        }
        let service = Arc::new(self.clone_for_runtime_projection());
        let guard = SharedRecoveryCoordinatorGuard {
            active: Arc::clone(&self.delegated_child_attachment_recovery_coordinator_active),
        };
        crate::magician_v2::execution::runtime_boundary::spawn_execution_job(move || async move {
            let _guard = guard;
            loop {
                let now_ms = Utc::now().timestamp_millis();
                let candidate = service
                    .delegated_child_attachment_recovery_queue
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner)
                    .pop_due(now_ms);
                let Some((key, mut candidate)) = candidate else {
                    let next_deadline = service
                        .delegated_child_attachment_recovery_queue
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner)
                        .next_deadline_ms();
                    let wait = next_deadline
                        .map(|deadline_ms| {
                            Duration::from_millis(
                                deadline_ms
                                    .saturating_sub(Utc::now().timestamp_millis())
                                    .clamp(1, 30_000) as u64,
                            )
                        })
                        .unwrap_or_else(|| Duration::from_secs(30));
                    tokio::select! {
                        _ = service.delegated_child_attachment_recovery_queue_changed.notified() => {},
                        _ = tokio::time::sleep(wait) => {},
                    }
                    continue;
                };

                if service
                    .run_delegated_child_attachment_recovery_candidate(&mut candidate)
                    .await
                {
                    service
                        .active_delegated_child_attachment_recoveries
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner)
                        .remove(&key);
                    continue;
                }
                candidate.retry_attempt = candidate.retry_attempt.saturating_add(1);
                let retry_at_ms = Utc::now().timestamp_millis().saturating_add(
                    shared_recovery_retry_delay(candidate.retry_attempt)
                        .as_millis()
                        .min(i64::MAX as u128) as i64,
                );
                service
                    .delegated_child_attachment_recovery_queue
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner)
                    .insert(key, retry_at_ms, candidate);
            }
        });
    }

    async fn run_delegated_child_attachment_recovery_candidate(
        &self,
        candidate: &mut DelegatedChildAttachmentRecoveryCandidate,
    ) -> bool {
        if let Some(cursor) = candidate.scan_cursor {
            let parent = match self
                .get_execution(
                    &candidate.scope,
                    &candidate.task_id,
                    &candidate.parent_execution_id,
                )
                .await
            {
                Ok(parent)
                    if parent.state.execution_id != candidate.parent_execution_id
                        || parent.state.task_id != candidate.task_id =>
                {
                    warn!(
                        task_id = %candidate.task_id,
                        parent_execution_id = %candidate.parent_execution_id,
                        observed_task_id = %parent.state.task_id,
                        observed_execution_id = %parent.state.execution_id,
                        "delegated child attachment parent scan binding mismatch"
                    );
                    return false;
                },
                Ok(parent) if !is_terminal_execution_status(&parent.state.status) => parent,
                Ok(_)
                | Err(ArtifactV2Error::ExecutionNotFound(_))
                | Err(ArtifactV2Error::TaskNotFound(_)) => return true,
                Err(error) => {
                    warn!(
                        task_id = %candidate.task_id,
                        parent_execution_id = %candidate.parent_execution_id,
                        %error,
                        "delegated child attachment parent scan read deferred"
                    );
                    return false;
                },
            };
            return match self
                .recover_delegated_child_attachments_page(
                    &candidate.scope,
                    &candidate.task_id,
                    &parent,
                    cursor,
                )
                .await
            {
                Ok(page) => {
                    candidate.scan_cursor = page.next_cursor;
                    candidate.retry_attempt = 0;
                    page.next_cursor.is_none()
                },
                Err(error) => {
                    warn!(
                        task_id = %candidate.task_id,
                        parent_execution_id = %candidate.parent_execution_id,
                        %error,
                        "delegated child attachment parent scan remains queued"
                    );
                    false
                },
            };
        }

        let parent = match self
            .get_execution(
                &candidate.scope,
                &candidate.task_id,
                &candidate.parent_execution_id,
            )
            .await
        {
            Ok(parent)
                if parent.state.execution_id != candidate.parent_execution_id
                    || parent.state.task_id != candidate.task_id =>
            {
                warn!(
                    task_id = %candidate.task_id,
                    parent_execution_id = %candidate.parent_execution_id,
                    child_execution_id = %candidate.child_execution_id,
                    observed_task_id = %parent.state.task_id,
                    observed_execution_id = %parent.state.execution_id,
                    "delegated child attachment parent binding mismatch"
                );
                return false;
            },
            Ok(parent) => parent,
            Err(ArtifactV2Error::ExecutionNotFound(_)) | Err(ArtifactV2Error::TaskNotFound(_)) => {
                return true
            },
            Err(error) => {
                warn!(
                    task_id = %candidate.task_id,
                    parent_execution_id = %candidate.parent_execution_id,
                    child_execution_id = %candidate.child_execution_id,
                    %error,
                    "delegated child attachment parent read deferred"
                );
                return false;
            },
        };
        if is_terminal_execution_status(&parent.state.status) {
            return true;
        }

        let artifact_child_terminal = match self
            .get_execution(
                &candidate.scope,
                &candidate.task_id,
                &candidate.child_execution_id,
            )
            .await
        {
            Ok(child) => is_terminal_execution_status(&child.state.status),
            Err(ArtifactV2Error::ExecutionNotFound(_)) => false,
            Err(ArtifactV2Error::TaskNotFound(_)) => return true,
            Err(error) => {
                warn!(
                    task_id = %candidate.task_id,
                    parent_execution_id = %candidate.parent_execution_id,
                    child_execution_id = %candidate.child_execution_id,
                    %error,
                    "delegated child attachment Artifact child read deferred"
                );
                return false;
            },
        };
        match self
            .orchestrator
            .conversation_store()
            .get_execution(&candidate.child_execution_id)
            .await
        {
            Ok(_) => {},
            Err(crate::magician_v2::storage::V2StorageError::ExecutionNotFound(_))
                if artifact_child_terminal =>
            {
                return true
            },
            Err(crate::magician_v2::storage::V2StorageError::ExecutionNotFound(_)) => return false,
            Err(error) => {
                warn!(
                    task_id = %candidate.task_id,
                    parent_execution_id = %candidate.parent_execution_id,
                    child_execution_id = %candidate.child_execution_id,
                    %error,
                    "delegated child attachment Runtime child read deferred"
                );
                return false;
            },
        }

        match self
            .attach_delegated_child_execution_once(
                &candidate.scope,
                &candidate.task_id,
                &candidate.parent_execution_id,
                &candidate.child_execution_id,
                &candidate.child_agent_id,
                &candidate.sub_goal,
            )
            .await
        {
            Ok(()) => true,
            Err(ArtifactV2Error::ExecutionNotFound(_)) | Err(ArtifactV2Error::TaskNotFound(_)) => {
                true
            },
            Err(error) => {
                warn!(
                    task_id = %candidate.task_id,
                    parent_execution_id = %candidate.parent_execution_id,
                    child_execution_id = %candidate.child_execution_id,
                    attempt = candidate.retry_attempt,
                    %error,
                    "delegated child attachment remains owned by shared recovery coordinator"
                );
                false
            },
        }
    }

    /// Re-adopt delegated children whose launch became durable before their V3
    /// child record or runtime watcher did. Parent delegation refs are the
    /// compact steady-state authority; the committed dispatch event is the
    /// crash bridge for older unmatched-child writers and for the event -> ref
    /// window. Every candidate is rebound to the exact Runtime parent/scope by
    /// `sync_runtime_child_execution` before any Artifact mutation.
    async fn recover_delegated_child_attachments_for_execution(
        self: &Arc<Self>,
        scope: &ScopeRef,
        task_id: &str,
        parent: &ExecutionRecord,
    ) -> Result<usize, ArtifactV2Error> {
        // A child watch exists to route a child's outcome into a task that is
        // still open. Once the task itself has ended there is nothing to
        // route, and the watch would only start, read the terminal task, and
        // stop (the same rule `start_child_runtime_watch` applies). Skipping
        // here keeps every boot from re-attaching the children of long-dead
        // tasks: each such watch started an event bridge whose replayed
        // projection was older than the persisted one and was dropped with a
        // warning. Delegation refs of those children never received their
        // committed terminal status, so the ref scan alone cannot tell.
        match self.get_task(scope, task_id).await {
            Ok(task) if Self::task_status_is_terminal_for_child_watch(&task.state.status) => {
                debug!(
                    principal = %scope.principal(),
                    workspace = %scope.workspace(),
                    task_id,
                    parent_execution_id = %parent.state.execution_id,
                    task_status = %task.state.status,
                    "skipping delegated child re-attachment: task is already terminal"
                );
                return Ok(0);
            },
            Ok(_) => {},
            Err(ArtifactV2Error::TaskNotFound(_)) => return Ok(0),
            Err(error) => return Err(error),
        }
        let initial_cursor = DelegatedChildAttachmentScanCursor::default();
        match self
            .recover_delegated_child_attachments_page(scope, task_id, parent, initial_cursor)
            .await
        {
            Ok(page) => {
                if let Some(next_cursor) = page.next_cursor {
                    self.schedule_delegated_child_attachment_scan(
                        scope,
                        task_id,
                        &parent.state.execution_id,
                        next_cursor,
                    )
                    .await;
                }
                Ok(page.recovered)
            },
            Err(error) => {
                // The startup walk is intentionally bounded and one-shot. A
                // failed first page therefore has to enter the same compact
                // same-boot owner as a failed individual attachment; returning
                // this error alone would defer the whole parent until restart.
                self.schedule_delegated_child_attachment_scan(
                    scope,
                    task_id,
                    &parent.state.execution_id,
                    initial_cursor,
                )
                .await;
                Err(error)
            },
        }
    }

    async fn recover_delegated_child_attachments_page(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        parent: &ExecutionRecord,
        cursor: DelegatedChildAttachmentScanCursor,
    ) -> Result<DelegatedChildAttachmentRecoveryPage, ArtifactV2Error> {
        const MAX_ATTACHMENT_PAGE_ITEMS: usize = 4096;
        let parent_execution_id = parent.state.execution_id.as_str();
        if parent.state.task_id != task_id || parent_execution_id.trim().is_empty() {
            return Err(ArtifactV2Error::InvalidRequest(format!(
                "startup_delegated_child_parent_binding_mismatch:{task_id}:{parent_execution_id}"
            )));
        }
        let mut candidates = HashMap::<String, (String, String)>::new();
        let mut next_cursor = cursor;
        let mut examined_items = 0usize;
        let mut runtime_parent: Option<ExecutionRun> = None;
        let mut event_page = None;
        let mut event_page_index = 0usize;

        while examined_items < MAX_ATTACHMENT_PAGE_ITEMS
            && next_cursor.stage != DelegatedChildAttachmentScanStage::Complete
        {
            match next_cursor.stage {
                DelegatedChildAttachmentScanStage::ArtifactDelegations => {
                    let Some(delegation) = parent.refs.delegations.get(next_cursor.offset) else {
                        next_cursor = DelegatedChildAttachmentScanCursor {
                            stage: DelegatedChildAttachmentScanStage::RuntimeActiveGroup,
                            offset: 0,
                            event_byte_offset: 0,
                            last_event_seq: None,
                        };
                        continue;
                    };
                    next_cursor.offset = next_cursor.offset.saturating_add(1);
                    examined_items = examined_items.saturating_add(1);
                    let Some(child_execution_id) = delegation.child_execution_id.as_deref() else {
                        continue;
                    };
                    if matches!(
                        delegation.status.as_str(),
                        "terminal" | "completed" | "failed" | "cancelled" | "canceled"
                    ) {
                        continue;
                    }
                    if child_execution_id.trim().is_empty()
                        || child_execution_id.len() > 512
                        || delegation
                            .child_agent_id
                            .as_deref()
                            .is_some_and(|value| value.len() > 4096)
                        || delegation.sub_goal.len() > 64 * 1024
                    {
                        return Err(ArtifactV2Error::InvalidRequest(format!(
                            "startup_delegated_child_artifact_ref_out_of_bounds:{task_id}:{parent_execution_id}"
                        )));
                    }
                    candidates
                        .entry(child_execution_id.to_owned())
                        .or_insert_with(|| {
                            (
                                delegation.child_agent_id.clone().unwrap_or_default(),
                                delegation.sub_goal.clone(),
                            )
                        });
                },
                DelegatedChildAttachmentScanStage::RuntimeActiveGroup
                | DelegatedChildAttachmentScanStage::RuntimeChildren => {
                    if runtime_parent.is_none() {
                        runtime_parent = match self
                            .orchestrator
                            .conversation_store()
                            .get_execution(parent_execution_id)
                            .await
                        {
                            Ok(runtime_parent) => {
                                Self::validate_runtime_artifact_binding(
                                    scope,
                                    task_id,
                                    parent,
                                    &runtime_parent,
                                )?;
                                Some(runtime_parent)
                            },
                            Err(crate::magician_v2::storage::V2StorageError::ExecutionNotFound(_)) => {
                                next_cursor = DelegatedChildAttachmentScanCursor {
                                    stage: DelegatedChildAttachmentScanStage::CanonicalEventLog,
                                    offset: 0,
                                    event_byte_offset: 0,
                                    last_event_seq: None,
                                };
                                continue;
                            },
                            Err(error) => {
                                return Err(ArtifactV2Error::Runtime(format!(
                                    "startup delegated-child Runtime lineage read failed:{parent_execution_id}:{error}"
                                )))
                            },
                        };
                    }
                    let runtime_parent = runtime_parent
                        .as_ref()
                        .expect("Runtime parent loaded for lineage page");
                    let child_execution_ids = match next_cursor.stage {
                        DelegatedChildAttachmentScanStage::RuntimeActiveGroup => {
                            &runtime_parent.active_delegation_group
                        },
                        DelegatedChildAttachmentScanStage::RuntimeChildren => {
                            &runtime_parent.child_execution_ids
                        },
                        _ => unreachable!("Runtime lineage stage checked above"),
                    };
                    let Some(child_execution_id) = child_execution_ids.get(next_cursor.offset)
                    else {
                        next_cursor = DelegatedChildAttachmentScanCursor {
                            stage: match next_cursor.stage {
                                DelegatedChildAttachmentScanStage::RuntimeActiveGroup => {
                                    DelegatedChildAttachmentScanStage::RuntimeChildren
                                },
                                _ => DelegatedChildAttachmentScanStage::Complete,
                            },
                            offset: 0,
                            event_byte_offset: 0,
                            last_event_seq: None,
                        };
                        continue;
                    };
                    next_cursor.offset = next_cursor.offset.saturating_add(1);
                    examined_items = examined_items.saturating_add(1);
                    if child_execution_id.trim().is_empty() || child_execution_id.len() > 512 {
                        return Err(ArtifactV2Error::InvalidRequest(format!(
                            "startup_delegated_child_runtime_ref_out_of_bounds:{task_id}:{parent_execution_id}"
                        )));
                    }
                    candidates
                        .entry(child_execution_id.clone())
                        .or_insert_with(|| (String::new(), String::new()));
                },
                DelegatedChildAttachmentScanStage::CanonicalEventLog => {
                    if event_page.is_none() {
                        let events_path = self.workspace.execution_events_path(
                            &scope.principal(),
                            &scope.workspace(),
                            task_id,
                            parent_execution_id,
                        );
                        let commit_path = self.workspace.execution_events_commit_path(
                            &scope.principal(),
                            &scope.workspace(),
                            task_id,
                            parent_execution_id,
                        );
                        event_page = Some(
                            self.workspace
                                .read_committed_jsonl_forward_page_path::<CanonicalEvent, _, _>(
                                    &events_path,
                                    &commit_path,
                                    next_cursor.event_byte_offset,
                                    MAX_ATTACHMENT_PAGE_ITEMS.saturating_sub(examined_items),
                                    MAX_CANONICAL_EVENT_RECORD_BYTES.saturating_add(1),
                                )
                                .await?,
                        );
                        event_page_index = 0;
                    }
                    let page = event_page
                        .as_ref()
                        .expect("committed canonical-event page loaded for attachment recovery");
                    let Some(event) = page.records.get(event_page_index) else {
                        next_cursor.event_byte_offset = page.next_offset;
                        if page.is_complete() {
                            next_cursor.stage = DelegatedChildAttachmentScanStage::Complete;
                            next_cursor.offset = 0;
                        }
                        event_page = None;
                        continue;
                    };
                    event_page_index = event_page_index.saturating_add(1);
                    if next_cursor
                        .last_event_seq
                        .is_some_and(|last_seq| event.seq <= last_seq)
                    {
                        return Err(ArtifactV2Error::InvalidRequest(format!(
                            "startup_delegated_child_event_sequence_not_monotonic:{task_id}:{parent_execution_id}:{}",
                            event.seq
                        )));
                    }
                    next_cursor.last_event_seq = Some(event.seq);
                    examined_items = examined_items.saturating_add(1);
                    if event.principal != scope.principal()
                        || event.workspace != scope.workspace()
                        || event.task_id != task_id
                        || event.execution_id != parent_execution_id
                    {
                        warn!(
                            task_id,
                            parent_execution_id,
                            event_id = %event.event_id,
                            "startup delegated-child recovery ignored a misbound canonical event"
                        );
                        continue;
                    }
                    let parsed = match event.event_type.as_str() {
                        "delegation.launch_dispatched" => event
                            .payload
                            .get("child_execution_id")
                            .and_then(Value::as_str)
                            .map(|child_execution_id| {
                                (
                                    child_execution_id,
                                    event
                                        .payload
                                        .get("target_agent_id")
                                        .and_then(Value::as_str)
                                        .unwrap_or_default(),
                                    event
                                        .payload
                                        .get("sub_goal")
                                        .and_then(Value::as_str)
                                        .unwrap_or_default(),
                                )
                            }),
                        "delegation.unmatched_child_dispatched" => event
                            .payload
                            .get("child_execution_id")
                            .and_then(Value::as_str)
                            .map(|child_execution_id| {
                                (
                                    child_execution_id,
                                    event
                                        .payload
                                        .get("child_agent_id")
                                        .and_then(Value::as_str)
                                        .unwrap_or_default(),
                                    "",
                                )
                            }),
                        _ => None,
                    };
                    let Some((child_execution_id, child_agent_id, sub_goal)) = parsed else {
                        continue;
                    };
                    if child_execution_id.trim().is_empty()
                        || child_execution_id.len() > 512
                        || child_agent_id.len() > 4096
                        || sub_goal.len() > 64 * 1024
                    {
                        continue;
                    }
                    candidates
                        .entry(child_execution_id.to_owned())
                        .or_insert_with(|| (child_agent_id.to_owned(), sub_goal.to_owned()));
                },
                DelegatedChildAttachmentScanStage::Complete => break,
            }
        }
        if next_cursor.stage == DelegatedChildAttachmentScanStage::CanonicalEventLog {
            if let Some(page) = event_page.as_ref() {
                if event_page_index == page.records.len() {
                    next_cursor.event_byte_offset = page.next_offset;
                    if page.is_complete() {
                        next_cursor.stage = DelegatedChildAttachmentScanStage::Complete;
                        next_cursor.offset = 0;
                    }
                }
            }
        }

        let mut recovered = 0usize;
        for (child_execution_id, (child_agent_id, sub_goal)) in candidates {
            match self
                .get_execution(scope, task_id, &child_execution_id)
                .await
            {
                Ok(existing)
                    if existing.state.parent_execution_id.as_deref()
                        != Some(parent_execution_id) =>
                {
                    return Err(ArtifactV2Error::InvalidRequest(format!(
                        "startup_delegated_child_artifact_parent_binding_mismatch:{task_id}:{parent_execution_id}:{child_execution_id}"
                    )));
                },
                Ok(_) | Err(ArtifactV2Error::ExecutionNotFound(_)) => {},
                Err(error) => return Err(error),
            }
            match self
                .attach_delegated_child_execution_once(
                    scope,
                    task_id,
                    parent_execution_id,
                    &child_execution_id,
                    &child_agent_id,
                    &sub_goal,
                )
                .await
            {
                Ok(()) => recovered = recovered.saturating_add(1),
                Err(ArtifactV2Error::ExecutionNotFound(error))
                | Err(ArtifactV2Error::TaskNotFound(error)) => warn!(
                    task_id,
                    parent_execution_id,
                    child_execution_id,
                    %error,
                    "startup delegated-child recovery retired a positively stale candidate"
                ),
                Err(error) => {
                    warn!(
                        task_id,
                        parent_execution_id,
                        child_execution_id,
                        %error,
                        "startup delegated-child attachment deferred to the registered retry owner"
                    );
                    self.schedule_delegated_child_attachment(
                        scope,
                        task_id,
                        parent_execution_id,
                        &child_execution_id,
                        &child_agent_id,
                        &sub_goal,
                    )
                    .await;
                },
            }
        }
        Ok(DelegatedChildAttachmentRecoveryPage {
            recovered,
            next_cursor: (next_cursor.stage != DelegatedChildAttachmentScanStage::Complete)
                .then_some(next_cursor),
        })
    }

    pub async fn create_task(&self, input: CreateTaskInput) -> Result<TaskRecord, ArtifactV2Error> {
        let task_id = format!("task_{}", Uuid::new_v4().simple());
        let task = self.create_task_with_id(input, task_id).await?;
        // A task created inside a chat turn or a run inherits its engine,
        // even when the scheduler starts it later on another task.
        if let Some(pin) = crate::magician_v2::execution::plane::current_launching_run_engine_pin()
        {
            let path = self
                .workspace
                .task_dir(
                    &task.manifest.principal,
                    &task.manifest.workspace,
                    &task.manifest.task_id,
                )
                .join(TASK_LAUNCH_ENGINE_PIN_FILE);
            if let Err(error) = self.workspace.write_json_atomic_path(&path, &pin).await {
                warn!(
                    task_id = %task.manifest.task_id,
                    error = %error,
                    "[ARTIFACT-V2] Task launch pin not saved; its runs take the Settings engine"
                );
            }
        }
        Ok(task)
    }

    /// Idempotently create a normal task with a caller-supplied deterministic
    /// ID. A replay repairs projections and returns the existing task only when
    /// its immutable manifest inputs match; an ID collision with different
    /// content is rejected.
    pub async fn ensure_task_with_id(
        &self,
        input: CreateTaskInput,
        task_id: impl Into<String>,
    ) -> Result<TaskRecord, ArtifactV2Error> {
        let task_id = task_id.into();
        reject_generic_app_workflow_lifecycle(&task_id)?;
        self.ensure_task_with_id_internal(input, task_id).await
    }

    /// Create or recover the deterministic task owned by an admitted app run.
    /// The app workflow service is the sole caller allowed to mint identifiers
    /// in the canonical app namespace.
    pub(crate) async fn ensure_app_workflow_task_with_id(
        &self,
        input: CreateTaskInput,
        task_id: String,
    ) -> Result<TaskRecord, ArtifactV2Error> {
        if !is_canonical_app_workflow_task_id(&task_id) {
            return Err(ArtifactV2Error::InvalidRequest(
                "app_workflow_task_id_required".to_string(),
            ));
        }
        self.ensure_task_with_id_internal(input, task_id).await
    }

    /// Activate only a canonical app-owned task shell after the workflow owner
    /// has durably published its authenticated binding. Generic task APIs are
    /// forbidden from the reserved namespace, and app launch must not reuse
    /// their broader status-mutation surface. The task write guard makes the
    /// pending-to-ready transition race-safe against a concurrent same-key
    /// recovery or start.
    pub(crate) async fn mark_app_workflow_task_ready(
        &self,
        scope: &ScopeRef,
        task_id: &str,
    ) -> Result<TaskRecord, ArtifactV2Error> {
        if !is_canonical_app_workflow_task_id(task_id) {
            return Err(ArtifactV2Error::InvalidRequest(
                "app_workflow_task_id_required".to_string(),
            ));
        }
        let task = {
            let _guard = self.acquire_task_write_guard(scope, task_id).await?;
            self.task_writes.recover_task_writes(scope, task_id).await?;
            let mut task = self.read_task_record_unlocked(scope, task_id).await?;
            let exact_identity = task.manifest.task_id == task_id
                && task.manifest.principal == scope.principal()
                && task.manifest.workspace == scope.workspace()
                && task.state.task_id == task_id
                && task.refs.task_id == task_id;
            let app_marker = task.manifest.created_by == "app_action"
                && task
                    .manifest
                    .tags
                    .iter()
                    .any(|tag| tag.id == "app_workflow")
                && task.manifest.ui_thread_id.starts_with("app:")
                && task.manifest.approved
                && task.manifest.depends_on.is_empty()
                && task.manifest.schedule.is_none()
                && matches!(task.manifest.output_mode, TaskOutputMode::Overwrite)
                && task.manifest.chat_session_id.is_none()
                && matches!(
                    task.manifest.lifecycle,
                    TaskLifecycle::Persistent | TaskLifecycle::Internal
                )
                && matches!(task.manifest.sync_mode, TaskSyncMode::Deferred)
                && task.manifest.monitor_spec.is_none()
                && task.manifest.monitor_revision == 0;
            if !exact_identity || !app_marker {
                return Err(ArtifactV2Error::InvalidRequest(
                    "app_workflow_task_identity_mismatch".to_string(),
                ));
            }
            if matches!(task.state.status.as_str(), "pending" | "ready") {
                let pristine = task.state.active_root_execution_id.is_none()
                    && task.state.latest_root_execution_id.is_none()
                    && task.state.last_completed_root_execution_id.is_none()
                    && task.state.default_task_agent_output_id.is_none()
                    && task.state.primary_user_output_id.is_none()
                    && task.state.schedule_fire_count == 0
                    && task.state.synthesis_pending_executions.is_empty()
                    && task.state.synthesis_failed_execution_id.is_none()
                    && task.state.monitor_cursor.is_none()
                    && task.state.last_progress_at.is_none()
                    && task.refs.outputs.is_empty()
                    && task.refs.default_task_agent_output_id.is_none()
                    && task.refs.primary_user_output_id.is_none();
                if !pristine {
                    return Err(ArtifactV2Error::InvalidRequest(
                        "app_workflow_task_shell_not_pristine".to_string(),
                    ));
                }
            }
            if task.state.status == "pending" {
                let now = now_rfc3339();
                task.state.status = "ready".to_string();
                task.state.updated_at = now.clone();
                task.manifest.updated_at = now;
                self.persist_task_record_unlocked(scope, &task).await?;
            }
            task
        };
        self.project_task_feed_item(scope, task_id).await?;
        self.project_task_progress(scope, task_id).await?;
        Ok(task)
    }

    /// Only the App occurrence owner may reopen a recurring task. Historical
    /// executions stay intact; a live root is never replaced by a later tick.
    pub(crate) async fn mark_recurring_app_workflow_task_ready(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        agent_id: &str,
    ) -> Result<TaskRecord, ArtifactV2Error> {
        if !is_canonical_app_workflow_task_id(task_id) {
            return Err(ArtifactV2Error::InvalidRequest(
                "app_workflow_task_id_required".into(),
            ));
        }
        let task = {
            let _guard = self.acquire_task_write_guard(scope, task_id).await?;
            self.task_writes.recover_task_writes(scope, task_id).await?;
            let mut task = self.read_task_record_unlocked(scope, task_id).await?;
            if task.manifest.task_id != task_id
                || task.manifest.principal != scope.principal()
                || task.manifest.workspace != scope.workspace()
                || task.state.task_id != task_id
                || task.refs.task_id != task_id
                || task.manifest.created_by != "app_action"
                || !task
                    .manifest
                    .tags
                    .iter()
                    .any(|tag| tag.id == "app_workflow")
                || !task.manifest.ui_thread_id.starts_with("app:")
                || !task.manifest.approved
                || !task.manifest.depends_on.is_empty()
                || task.manifest.schedule.is_some()
                || task.manifest.chat_session_id.is_some()
                || !matches!(task.manifest.output_mode, TaskOutputMode::Overwrite)
                || !matches!(task.manifest.sync_mode, TaskSyncMode::Deferred)
                || task.manifest.monitor_spec.is_some()
                || task.manifest.monitor_revision != 0
                || !task
                    .manifest
                    .tags
                    .iter()
                    .any(|tag| tag.id == "app_recurring")
                || !matches!(task.manifest.lifecycle, TaskLifecycle::Internal)
            {
                return Err(ArtifactV2Error::InvalidRequest(
                    "app_recurring_task_identity_mismatch".into(),
                ));
            }
            if task.state.active_root_execution_id.is_some()
                || !matches!(
                    task.state.status.as_str(),
                    "pending" | "ready" | "completed" | "failed" | "cancelled"
                )
            {
                return Err(ArtifactV2Error::InvalidRequest(format!(
                    "task_execution_in_progress:{task_id}"
                )));
            }
            if let Some(previous) = task.state.latest_root_execution_id.as_deref() {
                // The task write guard already protects the execution state,
                // and its multi-write journal was recovered above. The public
                // reader would acquire this same guard again and deadlock.
                let previous_state: ExecutionState = self
                    .workspace
                    .read_json_path(self.workspace.execution_state_path(
                        &scope.principal(),
                        &scope.workspace(),
                        task_id,
                        previous,
                    ))
                    .await?;
                if !app_run_task_status_is_terminal(&previous_state.status) {
                    return Err(ArtifactV2Error::InvalidRequest(format!(
                        "task_execution_in_progress:{previous}"
                    )));
                }
            }
            task.state.status = "ready".to_owned();
            // The history container follows the newly sealed occurrence's
            // owner; historical executions retain their own agent binding.
            task.manifest.agent_id = agent_id.to_owned();
            task.state.completion_kind = None;
            task.state.open_items.clear();
            task.state.updated_at = now_rfc3339();
            task.manifest.updated_at = task.state.updated_at.clone();
            self.persist_task_record_unlocked(scope, &task).await?;
            task
        };
        self.project_task_feed_item(scope, task_id).await?;
        self.project_task_progress(scope, task_id).await?;
        Ok(task)
    }

    async fn ensure_task_with_id_internal(
        &self,
        input: CreateTaskInput,
        task_id: String,
    ) -> Result<TaskRecord, ArtifactV2Error> {
        if !valid_caller_task_id(&task_id) {
            return Err(ArtifactV2Error::InvalidRequest(
                "caller_task_id_invalid".to_string(),
            ));
        }
        let scope = ScopeRef::system_internal_unauthenticated(
            &input.principal.clone(),
            &input.workspace.clone(),
        );
        // Serialize the complete compare-or-create transaction across
        // processes. The distinct admission lock may safely nest the reducer's
        // ordinary task-record lock; using that same lock file here would
        // self-deadlock when `create_task_with_id` reaches the reducer.
        let _admission_guard = self
            .acquire_task_start_admission_guard(&scope, &task_id)
            .await?;
        if self.task_record_exists(&scope, &task_id).await? {
            let existing = self.get_task(&scope, &task_id).await?;
            if !task_manifest_matches_create_input(&existing.manifest, &input) {
                return Err(ArtifactV2Error::InvalidRequest(
                    "caller_task_id_conflict".to_string(),
                ));
            }
            // A prior attempt may have committed the task record and failed
            // while projecting feed/progress. Replaying repairs both views.
            self.project_task_feed_item(&scope, &task_id).await?;
            self.project_task_progress(&scope, &task_id).await?;
            return Ok(existing);
        }
        self.create_task_with_id(input, task_id).await
    }

    async fn create_task_with_id(
        &self,
        input: CreateTaskInput,
        task_id: String,
    ) -> Result<TaskRecord, ArtifactV2Error> {
        let now = now_rfc3339();
        self.workspace
            .ensure_task_workspace_for_lifecycle(
                &input.principal,
                &input.workspace,
                &task_id,
                input.lifecycle.clone(),
            )
            .await?;

        let manifest = TaskManifest {
            task_id: task_id.clone(),
            principal: input.principal.clone(),
            workspace: input.workspace.clone(),
            title: input.title,
            description: input.description,
            agent_id: input.agent_id,
            goal_id: input.goal_id,
            ui_thread_id: input.ui_thread_id,
            priority: input.priority,
            due_date: input.due_date,
            tags: input.tags,
            created_by: input.created_by,
            depends_on: input.depends_on,
            approved: input.approved,
            schedule: input.schedule,
            output_mode: input.output_mode,
            chat_session_id: input.chat_session_id,
            lifecycle: input.lifecycle,
            sync_mode: input.sync_mode,
            // Monitors are minted as plain tasks; the spec is attached via
            // `update_task` so the server-owned revision starts at 1.
            monitor_spec: None,
            monitor_revision: 0,
            created_at: now.clone(),
            updated_at: now.clone(),
        };
        let state = TaskState {
            task_id: task_id.clone(),
            status: "pending".to_string(),
            completion_kind: None,
            open_items: Vec::new(),
            active_root_execution_id: None,
            latest_root_execution_id: None,
            last_completed_root_execution_id: None,
            default_task_agent_output_id: None,
            primary_user_output_id: None,
            schedule_fire_count: 0,
            synthesis_pending_executions: Vec::new(),
            synthesis_failed_execution_id: None,
            monitor_cursor: None,
            // A freshly created task has not run, so it has no progress
            // instant. `None`, never `now` — a creation timestamp here would
            // read as "the run advanced when it was filed".
            last_progress_at: None,
            updated_at: now.clone(),
        };
        let refs = TaskRefs {
            task_id,
            outputs: Vec::new(),
            default_task_agent_output_id: None,
            primary_user_output_id: None,
            updated_at: Some(now),
        };
        let task = TaskRecord {
            manifest,
            state,
            refs,
        };
        self.reducer.reduce_task_created(&task).await?;
        let scope = ScopeRef::system_internal_unauthenticated(
            &task.manifest.principal.clone(),
            &task.manifest.workspace.clone(),
        );
        self.project_task_feed_item(&scope, &task.manifest.task_id)
            .await?;
        self.project_task_progress(&scope, &task.manifest.task_id)
            .await?;
        Ok(task)
    }

    pub async fn create_task_with_execution_shell(
        &self,
        input: CreateTaskInput,
    ) -> Result<(TaskRecord, ExecutionRecord), ArtifactV2Error> {
        let task = self.create_task(input).await?;
        let scope = ScopeRef::system_internal_unauthenticated(
            &task.manifest.principal.clone(),
            &task.manifest.workspace.clone(),
        );
        self.provision_execution_shell(&scope, &task.manifest.task_id)
            .await
    }

    /// Refuse a stateless launch scope before a caller creates any Artifact
    /// task or execution shell. Most task-backed roots use `task_run_factory`,
    /// but chat-inline capability packs provision their specialized shell
    /// directly through this service and need the same immutable cutover gate.
    pub async fn require_stateless_scope_activated(
        &self,
        scope: &ScopeRef,
    ) -> Result<(), ArtifactV2Error> {
        self.orchestrator
            .require_stateless_scope_activated(&scope.principal(), &scope.workspace())
            .await
            .map_err(ArtifactV2Error::Runtime)
    }

    /// Idempotently create a task with a caller-supplied `task_id`. Used by
    /// boot-time seeds (e.g. the LLM Calls Overview dashboard) that mint a
    /// system-owned task with a deterministic id. If a task with the same id
    /// already exists in the scope, the existing record is returned and no
    /// writes are performed. Tasks created via this path are marked
    /// `completed` immediately since they are non-execution system tasks.
    pub async fn ensure_seed_task(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        title: &str,
        description: &str,
        agent_id: &str,
        ui_thread_id: &str,
    ) -> Result<TaskRecord, ArtifactV2Error> {
        reject_generic_app_workflow_lifecycle(task_id)?;
        if self.task_record_exists(scope, task_id).await? {
            return self.get_task(scope, task_id).await;
        }

        self.workspace
            .ensure_task_workspace(&scope.principal(), &scope.workspace(), task_id)
            .await?;

        let now = now_rfc3339();
        let manifest = TaskManifest {
            task_id: task_id.to_string(),
            principal: scope.principal().to_string(),
            workspace: scope.workspace().to_string(),
            title: title.to_string(),
            description: description.to_string(),
            agent_id: agent_id.to_string(),
            goal_id: None,
            ui_thread_id: ui_thread_id.to_string(),
            priority: None,
            due_date: None,
            tags: Vec::new(),
            created_by: agent_id.to_string(),
            depends_on: Vec::new(),
            approved: true,
            schedule: None,
            output_mode: TaskOutputMode::Overwrite,
            chat_session_id: None,
            lifecycle: crate::magician_v2::artifact_v2::models::TaskLifecycle::default(),
            sync_mode: crate::magician_v2::artifact_v2::models::TaskSyncMode::default(),
            monitor_spec: None,
            monitor_revision: 0,
            created_at: now.clone(),
            updated_at: now.clone(),
        };
        let state = TaskState {
            task_id: task_id.to_string(),
            status: "completed".to_string(),
            completion_kind: None,
            open_items: Vec::new(),
            active_root_execution_id: None,
            latest_root_execution_id: None,
            last_completed_root_execution_id: None,
            default_task_agent_output_id: None,
            primary_user_output_id: None,
            schedule_fire_count: 0,
            synthesis_pending_executions: Vec::new(),
            synthesis_failed_execution_id: None,
            monitor_cursor: None,
            // Seed tasks never execute, so no step ever transitions.
            last_progress_at: None,
            updated_at: now.clone(),
        };
        let refs = TaskRefs {
            task_id: task_id.to_string(),
            outputs: Vec::new(),
            default_task_agent_output_id: None,
            primary_user_output_id: None,
            updated_at: Some(now),
        };
        let task = TaskRecord {
            manifest,
            state,
            refs,
        };
        self.reducer.reduce_task_created(&task).await?;
        Ok(task)
    }

    /// Write a user-output directly under an existing task without running
    /// the synthesis pipeline. Mints a fresh `OutputRef`, persists the body
    /// via the default text-writer registry, and updates the task record's
    /// `primary_user_output_id` + `outputs` list so consumers see the new
    /// payload as the canonical user-output.
    ///
    /// Used by boot-time seeds (e.g. the LLM Calls Overview dashboard) and
    /// other system flows that author user-output payloads directly.
    pub async fn write_user_output_direct(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        envelope: WriteUserOutputDirectInput,
    ) -> Result<OutputRef, ArtifactV2Error> {
        let mut task = self.get_task(scope, task_id).await?;

        let media_type = base_media_type(&envelope.media_type).to_string();
        let body = match (media_type.as_str(), envelope.body) {
            ("application/json", WriteUserOutputBody::Json(mut value)) => {
                if let Some(theme) = envelope.dashboard_theme.as_ref() {
                    if let Some(object) = value.as_object_mut() {
                        object
                            .entry("dashboard_theme".to_string())
                            .or_insert_with(|| Value::String(theme.clone()));
                    }
                }
                OutputBody::Json(value)
            },
            ("application/json", WriteUserOutputBody::Text(_)) => {
                return Err(ArtifactV2Error::InvalidRequest(
                    "write_user_output_direct: application/json requires body=Json".to_string(),
                ));
            },
            (
                "text/markdown" | "text/html" | "text/plain" | "application/xml" | "text/xml",
                WriteUserOutputBody::Text(text),
            ) => OutputBody::Text(text),
            (
                "text/markdown" | "text/html" | "text/plain" | "application/xml" | "text/xml",
                WriteUserOutputBody::Json(_),
            ) => {
                return Err(ArtifactV2Error::InvalidRequest(format!(
                    "write_user_output_direct: {media_type} requires body=Text"
                )));
            },
            (other, _) => {
                return Err(ArtifactV2Error::InvalidRequest(format!(
                    "write_user_output_direct: unsupported media_type `{other}`"
                )));
            },
        };

        let document = OutputDocument {
            media_type: media_type.clone(),
            body,
        };

        // Seed/direct writes never run inside an execution, so we use the
        // task_id itself as the synthetic projection id. With `Overwrite`
        // mode this is harmless (the formula drops the projection id); with
        // `Accumulate` mode it keeps the output_id stable across repeated
        // direct writes to the same task.
        let output_id = task_primary_output_id(
            "out_task_user",
            task_id,
            task_id,
            &task.manifest.output_mode,
        );
        let output_dir =
            self.workspace
                .task_outputs_dir(&scope.principal(), &scope.workspace(), task_id);
        let registry = OutputWriterRegistry::with_default_text_writers();
        let persisted = registry
            .persist(
                &self.workspace,
                &output_id,
                &output_dir,
                "outputs",
                &document,
            )
            .await?;

        let now = now_rfc3339();
        let output_ref = OutputRef {
            output_id: output_id.clone(),
            scope: "task".to_string(),
            audience: "user".to_string(),
            role: "primary_task_user".to_string(),
            relative_path: persisted.relative_path,
            media_type: persisted.media_type,
            created_at: now.clone(),
            source_execution_id: None,
            source_plan_id: None,
            source_output_ids: Vec::new(),
        };

        task.state.primary_user_output_id = Some(output_ref.output_id.clone());
        task.state.updated_at = now.clone();
        if let Some(existing) = task
            .refs
            .outputs
            .iter_mut()
            .find(|existing| existing.output_id == output_ref.output_id)
        {
            *existing = output_ref.clone();
        } else {
            task.refs.outputs.push(output_ref.clone());
        }
        task.refs.primary_user_output_id = Some(output_ref.output_id.clone());
        task.refs.updated_at = Some(now);

        self.persist_task_record(scope, &task).await?;
        Ok(output_ref)
    }

    // ─── Recurring Monitors Phase 2 — run acceptance + change ledger ─────

    /// Accept one monitor execution's `MonitorRunResultV1` (plan §6.2/§7).
    ///
    /// The BACKEND owns change semantics: this validates the incoming
    /// result, recomputes stable keys / content / run / change fingerprints
    /// and classifications against the bounded cursor (`compare_runs`),
    /// persists the FINALIZED result as a durable JSON execution artifact
    /// (`monitor_run_result` in `executions/{id}/artifacts/
    /// persisted_artifacts.json` — the existing persisted-artifact path, no
    /// new store), and advances `TaskState.monitor_cursor` under the task
    /// write guard.
    ///
    /// IDEMPOTENT: re-accepting the execution id the cursor already points
    /// at (retry, restart, double-dispatch) returns the previously persisted
    /// outcome without rewriting the artifact or mutating the cursor.
    ///
    /// Write order is artifact-then-cursor: a crash between the two leaves
    /// the cursor un-advanced, and the retry recomputes the identical
    /// finalized result (comparison is deterministic over the same cursor)
    /// and idempotently re-upserts the same artifact.
    pub async fn accept_monitor_run(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        execution_id: &str,
        result: MonitorRunResultV1,
    ) -> Result<AcceptedMonitorRun, ArtifactV2Error> {
        // Execution ids become one literal directory segment under
        // `executions/` — same containment rules as task ids.
        ArtifactV2Workspace::validate_task_id(execution_id).map_err(|_| {
            ArtifactV2Error::InvalidRequest("monitor_run_execution_id_invalid".to_string())
        })?;
        if result.execution_id != execution_id {
            return Err(ArtifactV2Error::InvalidRequest(
                "monitor_run_execution_id_mismatch".to_string(),
            ));
        }

        let _guard = self.acquire_task_write_guard(scope, task_id).await?;
        self.task_writes.recover_task_writes(scope, task_id).await?;
        let mut task = self.read_task_record_unlocked(scope, task_id).await?;
        let Some(spec) = task.manifest.monitor_spec.clone() else {
            return Err(ArtifactV2Error::InvalidRequest(
                "monitor_required".to_string(),
            ));
        };

        // Idempotent replay: the cursor already points at this execution —
        // return the persisted outcome verbatim, rewrite nothing.
        if task
            .state
            .monitor_cursor
            .as_ref()
            .map(|cursor| cursor.last_accepted_execution_id.as_str())
            == Some(execution_id)
        {
            let persisted = self
                .read_monitor_run_artifact(scope, task_id, execution_id)
                .await?
                .ok_or_else(|| {
                    ArtifactV2Error::Runtime(format!(
                        "monitor run artifact missing for already-accepted execution {execution_id}"
                    ))
                })?;
            let material = persisted.status == MonitorRunStatus::Changed;
            let would_notify = monitor_would_notify(&spec, persisted.status, material);
            return Ok(AcceptedMonitorRun {
                task_id: task_id.to_string(),
                execution_id: execution_id.to_string(),
                monitor_revision: task.manifest.monitor_revision,
                material,
                would_notify,
                newly_accepted: false,
                // The replay branch only fires when the cursor still points
                // at THIS execution, so the live cursor IS this acceptance's
                // post-acceptance snapshot.
                source_failures: task
                    .state
                    .monitor_cursor
                    .as_ref()
                    .map(|cursor| cursor.source_failures.clone())
                    .unwrap_or_default(),
                result: persisted,
            });
        }

        validate_monitor_run_result(&result, task_id, task.manifest.monitor_revision)
            .map_err(ArtifactV2Error::InvalidRequest)?;

        let now = now_rfc3339();
        // The monitors provider seam owns the acceptance decision (plan
        // 3.2): the failed-run carve-out, the §7 comparison, the next
        // hot-state cursor, the finalized persisted-result shape, and the
        // notify projection. This side is task-store integration only —
        // the write guard, the task read, the durable artifact, and the
        // cursor write below.
        let decision = decide_run_acceptance(
            &spec,
            task_id,
            task.manifest.monitor_revision,
            execution_id,
            task.state.monitor_cursor.as_ref(),
            result,
            now.clone(),
        );
        let (finalized, material, would_notify, next_cursor) = (
            decision.finalized,
            decision.material,
            decision.would_notify,
            decision.next_cursor,
        );

        // Durable cold artifact FIRST (deterministic artifact id → the
        // upsert is retry-idempotent), cursor second.
        let store = super::execution_artifacts::FilesystemExecutionArtifactIndexStore::new(
            self.workspace.clone(),
        );
        store
            .upsert_artifact(
                scope,
                task_id,
                execution_id,
                PersistedExecutionArtifactRecord {
                    artifact_id: MONITOR_RUN_RESULT_ARTIFACT_ID.to_string(),
                    artifact_type: MONITOR_RUN_RESULT_ARTIFACT_TYPE.to_string(),
                    content_type: "application/json".to_string(),
                    payload: serde_json::to_value(&finalized)?,
                    produced_at: now.clone(),
                    source_execution_id: None,
                    source_artifact_id: None,
                },
            )
            .await?;

        // Post-acceptance streak snapshot — carried on the return value so
        // the Phase 3 projection reads THIS acceptance's streaks even if a
        // newer run advances the task cursor before/again-between projection
        // (replay of an older acceptance must not read a newer cursor).
        let source_failures_snapshot = next_cursor.source_failures.clone();
        task.state.monitor_cursor = Some(next_cursor);
        task.state.updated_at = now;
        self.persist_task_record_unlocked(scope, &task).await?;

        Ok(AcceptedMonitorRun {
            task_id: task_id.to_string(),
            execution_id: execution_id.to_string(),
            monitor_revision: task.manifest.monitor_revision,
            material,
            would_notify,
            newly_accepted: true,
            source_failures: source_failures_snapshot,
            result: finalized,
        })
    }

    /// List accepted monitor run results, newest first (plan §6.3 rule 4:
    /// task/execution lookup — no new stores). Walks the existing execution
    /// index the same way `get_task_with_executions_enriched` does and reads
    /// each execution's persisted-artifact index; executions without an
    /// accepted `monitor_run_result` artifact are skipped.
    pub async fn get_monitor_runs(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        limit: usize,
    ) -> Result<Vec<MonitorRunResultV1>, ArtifactV2Error> {
        let task = self.get_task(scope, task_id).await?;
        if task.manifest.monitor_spec.is_none() {
            return Err(ArtifactV2Error::InvalidRequest(
                "monitor_required".to_string(),
            ));
        }
        let limit = limit.max(1);
        let mut entries = self.list_executions(scope, task_id).await?;
        entries.sort_by(|left, right| {
            right
                .started_at
                .cmp(&left.started_at)
                .then_with(|| right.execution_id.cmp(&left.execution_id))
        });

        let mut runs: Vec<MonitorRunResultV1> = Vec::new();
        for entry in entries {
            if runs.len() >= limit {
                break;
            }
            if let Some(run) = self
                .read_monitor_run_artifact(scope, task_id, &entry.execution_id)
                .await?
            {
                runs.push(run);
            }
        }
        Ok(runs)
    }

    /// Best-effort read of one execution's accepted `monitor_run_result`
    /// artifact. `Ok(None)` when the execution has no accepted run or the
    /// payload predates/fails the current contract.
    async fn read_monitor_run_artifact(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        execution_id: &str,
    ) -> Result<Option<MonitorRunResultV1>, ArtifactV2Error> {
        let store = super::execution_artifacts::FilesystemExecutionArtifactIndexStore::new(
            self.workspace.clone(),
        );
        let records = store.list_artifacts(scope, task_id, execution_id).await?;
        Ok(records
            .into_iter()
            .find(|record| record.artifact_type == MONITOR_RUN_RESULT_ARTIFACT_TYPE)
            .and_then(|record| serde_json::from_value(record.payload).ok()))
    }

    // ─── Recurring Monitors Phase 3 — notification enforcement, durable
    //     update ledger, Today/Attention projection ────────────────────────

    /// Read a monitor ledger, keeping the records that parse.
    ///
    /// The monitor ledgers are append-only and read by several surfaces. Strict,
    /// one torn append meant the monitor for that task could never record
    /// another update — the read failed, so the append that follows it never
    /// happened. Losing one row is the better failure.
    ///
    /// **Only for reads whose answer is a list.** A read that decides something
    /// from the *last* matching record is a different case: dropping a line
    /// there does not shorten the answer, it changes it. Those call sites do not
    /// use this.
    async fn read_monitor_ledger<T: serde::de::DeserializeOwned>(
        &self,
        path: &std::path::Path,
        ledger: &'static str,
    ) -> Result<Vec<T>, ArtifactV2Error> {
        let read = self
            .workspace
            .read_jsonl_path_tolerant::<T, _>(path)
            .await?;
        if read.lost_committed_records() {
            tracing::warn!(
                target: "artifact_v2::monitor",
                path = %path.display(),
                ledger,
                corrupt_records = read.corrupt,
                "monitor ledger is missing unreadable records"
            );
        }
        Ok(read.records)
    }

    /// List one monitor's durable update records, newest first (plan §5.3
    /// "Updates" tab). Reads the per-task `monitor_updates.jsonl` ledger —
    /// no new store system. 400 `monitor_required` for plain tasks.
    pub async fn list_monitor_updates(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        limit: usize,
    ) -> Result<Vec<MonitorUpdateDetailV1>, ArtifactV2Error> {
        let task = self.get_task(scope, task_id).await?;
        if task.manifest.monitor_spec.is_none() {
            return Err(ArtifactV2Error::InvalidRequest(
                "monitor_required".to_string(),
            ));
        }
        let path = self.workspace.monitor_updates_log_path(
            &scope.principal(),
            &scope.workspace(),
            task_id,
        );
        let mut updates: Vec<MonitorUpdateDetailV1> =
            self.read_monitor_ledger(&path, "monitor_updates").await?;
        updates.sort_by(|left, right| {
            right
                .occurred_at
                .cmp(&left.occurred_at)
                .then_with(|| right.update_id.cmp(&left.update_id))
        });
        updates.truncate(limit.max(1));
        Ok(updates)
    }

    /// Scope-wide monitor updates, newest first (plan §8
    /// `GET /monitor-updates`). Walks the scope's monitor tasks and merges
    /// their ledgers — the same record-read discipline the monitors list
    /// endpoint uses (no per-row execution/artifact lookups).
    pub async fn list_scope_monitor_updates(
        &self,
        scope: &ScopeRef,
        limit: usize,
    ) -> Result<Vec<MonitorUpdateDetailV1>, ArtifactV2Error> {
        let tasks = self.list_tasks(scope).await?;
        self.list_scope_monitor_updates_from(scope, &tasks, limit)
            .await
    }

    /// [`Self::list_scope_monitor_updates`] over a listing the caller already
    /// holds.
    ///
    /// `/today` lists the corpus for its Follow-ups lane anyway, and taking a
    /// second walk here made the monitor lane cost the whole corpus a second
    /// time for a set of tasks that, in a scope with no monitors, is empty.
    ///
    /// # The row already answers "is this a monitor"
    ///
    /// This used to re-read every listed task's record with `get_task` and
    /// test `manifest.monitor_spec.is_none()` — a full record triple and, back
    /// when `get_task` took one, an exclusive cross-process lock, per row, to
    /// learn a fact the row in hand already carried.
    /// [`TaskListItemV3::monitor_revision`] exists for exactly this question;
    /// its doc comment says so ("so task-list clients can tell 'already a
    /// monitor' (`> 0`) from 'eligible for explicit conversion' (`0`) WITHOUT
    /// a per-row manifest read").
    ///
    /// **The equivalence is enforced by there being one writer.** `0` and
    /// `None` are set together at creation, and `update_task` is the only code
    /// that ever writes `monitor_spec` — inside `if let Some(spec)`, where it
    /// assigns `Some(spec)` and bumps the revision to at least 1 in the same
    /// two statements, under one lock, into one manifest write. There is no
    /// path that clears a spec, so a revision can never outlive one. Both
    /// fields arrived in the same phase, so no legacy manifest can carry a
    /// spec without a revision either.
    /// `monitor_revision_is_zero_exactly_when_there_is_no_monitor_spec` holds
    /// that shut.
    pub async fn list_scope_monitor_updates_from(
        &self,
        scope: &ScopeRef,
        tasks: &[TaskListItemV3],
        limit: usize,
    ) -> Result<Vec<MonitorUpdateDetailV1>, ArtifactV2Error> {
        let mut updates: Vec<MonitorUpdateDetailV1> = Vec::new();
        for item in tasks {
            if item.monitor_revision == 0 {
                continue;
            }
            let path = self.workspace.monitor_updates_log_path(
                &scope.principal(),
                &scope.workspace(),
                &item.id,
            );
            updates.extend(
                self.read_monitor_ledger::<MonitorUpdateDetailV1>(&path, "monitor_updates")
                    .await?,
            );
        }
        updates.sort_by(|left, right| {
            right
                .occurred_at
                .cmp(&left.occurred_at)
                .then_with(|| right.update_id.cmp(&left.update_id))
        });
        updates.truncate(limit.max(1));
        Ok(updates)
    }

    /// Best-effort scoped observability trace for monitor events (plan §12),
    /// following the EXISTING attention-funnel eventing idiom the Phase 3
    /// monitor projections already use (UNIQUE `event_id` + `INSERT OR
    /// IGNORE` = restart/replay-safe; scope carried on every row; no new
    /// event bus). The event id is deterministic over `trace` + `seed`, so
    /// idempotent replays of the same action append NOTHING new.
    ///
    /// Returns whether THIS call inserted the row. No-op (false) when no
    /// funnel store is wired; never fails the caller.
    pub async fn append_monitor_trace_event(
        &self,
        scope: &ScopeRef,
        trace: &'static str,
        task_id: &str,
        seed: &str,
        stage: AttentionFunnelStage,
        status: AttentionTraceStatus,
        metadata: Value,
    ) -> bool {
        let Some(store) = self.attention_funnel_store.get() else {
            return false;
        };
        let now_ms = Utc::now().timestamp_millis();
        let mut metadata = metadata;
        if let Some(object) = metadata.as_object_mut() {
            object.insert("producer".to_string(), json!("monitor_observability"));
            object.insert("trace".to_string(), json!(trace));
            object.insert("monitor_task_id".to_string(), json!(task_id));
        }
        let event = AttentionRouteEvent {
            event_id: format!(
                "monitor-obs:{trace}:{}",
                blake3::hash(seed.as_bytes()).to_hex()
            ),
            scope: AttentionScope {
                principal: scope.principal().to_string(),
                workspace: scope.workspace().to_string(),
            },
            source: AttentionSource {
                kind: AttentionSourceKind::Task,
                source_ref: format!("monitor:{task_id}"),
                provider: None,
                account_alias: None,
            },
            source_family: AttentionSourceFamily::Task,
            candidate_key: task_id.to_string(),
            stage,
            outcome: RouteOutcome::Traced { status },
            occurred_at: now_ms,
            created_at: now_ms,
            confidence: None,
            metadata,
        };
        match store.append_event_returning_new(event).await {
            Ok(new) => {
                if !new {
                    debug!(
                        trace,
                        task_id, "[MONITORS] replayed observability trace suppressed"
                    );
                }
                new
            },
            Err(error) => {
                warn!(trace, task_id, error = %error, "[MONITORS] failed to record observability trace");
                false
            },
        }
    }

    /// §12 monitor lifecycle traces (`monitor_created` / `monitor_updated` /
    /// `monitor_paused` / `monitor_resumed`) — emitted by the monitor API
    /// handlers and the shared chat-tool paths. `pub` so
    /// `monitors_api` / `monitor_tools` reach the single event idiom; never
    /// called from any generic-task path.
    pub async fn record_monitor_lifecycle_event(
        &self,
        scope: &ScopeRef,
        trace: &'static str,
        task_id: &str,
        seed: &str,
        metadata: Value,
    ) {
        self.append_monitor_trace_event(
            scope,
            trace,
            task_id,
            seed,
            AttentionFunnelStage::Ingested,
            AttentionTraceStatus::Succeeded,
            metadata,
        )
        .await;
    }

    /// Append one record to a bounded per-task monitor ledger (Phase 6
    /// retention, plan §13 Phase 6 item 3): plain O(1) append below
    /// [`MONITOR_LEDGER_RETENTION_CAP`], compact-on-append past it — the
    /// ledger is atomically rewritten (`write_jsonl_records_atomic_path`,
    /// the workspace's existing tmp+rename helper) keeping only the NEWEST
    /// `MONITOR_LEDGER_RETENTION_CAP` records including the new one.
    ///
    /// See the cap's doc comment in `monitor_updates.rs` for why dedupe
    /// survives compaction (deterministic ids) and why a change fingerprint
    /// older than the horizon re-emitting is acceptable.
    ///
    /// Callers hold the task write guard and pass the ledger they already
    /// read (both call-sites read it for dedupe), so compaction adds no
    /// extra I/O.
    async fn append_monitor_ledger_bounded<T: Serialize + Clone>(
        &self,
        path: &Path,
        existing: &[T],
        record: &T,
    ) -> Result<(), ArtifactV2Error> {
        if existing.len() + 1 > MONITOR_LEDGER_RETENTION_CAP {
            let skip = existing.len() + 1 - MONITOR_LEDGER_RETENTION_CAP;
            let mut records: Vec<T> = existing[skip..].to_vec();
            records.push(record.clone());
            self.workspace
                .write_jsonl_records_atomic_path(path, &records)
                .await
        } else {
            if let Some(parent) = path.parent() {
                self.workspace.create_dir_all_path(parent).await?;
            }
            self.workspace.append_jsonl_path(path, record).await
        }
    }

    /// Deterministic Phase 3 projection for one accepted monitor run
    /// (plan §7.2: gating is backend-owned, never a prompt convention):
    ///
    /// 1. **Update ledger** — build the [`MonitorUpdateDetailV1`] record
    ///    (policy-aware; `None` for quiet runs under the default policy) and
    ///    append it to the per-task `monitor_updates.jsonl` under the task
    ///    write guard. The `update_id` is a hash of the §7.4 dedupe key, so
    ///    a replayed acceptance or restart re-derives the SAME id and the
    ///    append is skipped — the ledger itself is a durable dedupe. The
    ///    ledger is bounded at [`MONITOR_LEDGER_RETENTION_CAP`]
    ///    (compact-on-append, Phase 6).
    /// 2. **Per-channel notification dedupe** — when the record is emitted,
    ///    insert the UNIQUE `event_id = hash(dedupe key)` row into the
    ///    attention-funnel store (when wired). `INSERT OR IGNORE` makes
    ///    retries/restarts observable as suppressed replays.
    /// 3. **Attention (§5.5)** — route an access-problem candidate to
    ///    Needs You on the SECOND consecutive failure of the same source,
    ///    and auto-resolve items for sources that read ok+complete again.
    /// 4. **§12 observability** — run lifecycle traces
    ///    (`monitor_run_started` / `monitor_run_completed` /
    ///    `monitor_run_degraded` / `monitor_change_detected`) plus the
    ///    notification sent/suppressed traces from step 2. NOTE:
    ///    `monitor_run_started` is deliberately emitted HERE (at
    ///    acceptance, with `started_at` taken from the run result) rather
    ///    than at dispatch/context-injection — the injection seam
    ///    (`goal_with_monitor_context`) sits on the generic execution hot
    ///    path with no store access, and instrumenting it would touch every
    ///    non-monitor execution. Acceptance is the first monitor-only seam
    ///    that observes the run.
    ///
    /// Idempotent end-to-end: calling this again for the same accepted
    /// execution (retry, restart, repeated terminal short-circuit) emits
    /// nothing new — ledger appends dedupe on the deterministic update id
    /// and every funnel event id is deterministic over the same action.
    /// Returns the durable update record when one exists.
    pub async fn project_monitor_run_outcome(
        &self,
        scope: &ScopeRef,
        accepted: &AcceptedMonitorRun,
    ) -> Result<Option<MonitorUpdateDetailV1>, ArtifactV2Error> {
        let task = self.get_task(scope, &accepted.task_id).await?;
        let Some(spec) = task.manifest.monitor_spec.clone() else {
            return Err(ArtifactV2Error::InvalidRequest(
                "monitor_required".to_string(),
            ));
        };

        // §12 run lifecycle traces — deterministic per-execution event ids,
        // so replays of the same acceptance append nothing new.
        self.record_monitor_run_trace_events(scope, accepted).await;

        // 1) Durable update ledger, idempotent by deterministic update_id,
        //    bounded at MONITOR_LEDGER_RETENTION_CAP (compact-on-append).
        let mut recorded_update: Option<MonitorUpdateDetailV1> = None;
        let mut newly_recorded = false;
        if let Some(update) =
            build_monitor_update(&scope.principal(), &scope.workspace(), &spec, accepted)
        {
            let _guard = self
                .acquire_task_write_guard(scope, &accepted.task_id)
                .await?;
            let path = self.workspace.monitor_updates_log_path(
                &scope.principal(),
                &scope.workspace(),
                &accepted.task_id,
            );
            // Torn tail tolerated, corruption refused. This read decides
            // whether `update_id` was already recorded; a silently dropped row
            // makes the dedupe miss and appends the update twice. A torn tail
            // was never committed, so it cannot be the record we are looking
            // for and dropping it is safe.
            let existing_read = self
                .workspace
                .read_jsonl_path_tolerant::<MonitorUpdateDetailV1, _>(&path)
                .await?;
            if existing_read.lost_committed_records() {
                return Err(ArtifactV2Error::Runtime(format!(
                    "monitor update ledger {} has {} unreadable record(s); refusing to \
                     record an update that may already be present",
                    path.display(),
                    existing_read.corrupt
                )));
            }
            let existing: Vec<MonitorUpdateDetailV1> = existing_read.records;
            if let Some(persisted) = existing
                .iter()
                .find(|record| record.update_id == update.update_id)
            {
                // Replay — serve the persisted record verbatim, write nothing.
                recorded_update = Some(persisted.clone());
            } else {
                self.append_monitor_ledger_bounded(&path, &existing, &update)
                    .await?;
                newly_recorded = true;
                recorded_update = Some(update);
            }
        }

        // 2) Durable per-channel dedupe + notification sent/suppressed
        //    observability (covers runs with no update record too).
        self.record_monitor_notification_outcome(
            scope,
            &spec,
            accepted,
            recorded_update.as_ref(),
            newly_recorded,
        )
        .await;

        // 3) Attention lifecycle for source-access problems.
        self.project_monitor_access_attention(scope, &task, accepted, recorded_update.as_ref())
            .await;

        Ok(recorded_update)
    }

    /// §12 run lifecycle traces for one accepted run. Best-effort; every
    /// event id is deterministic over the execution id, so replayed
    /// acceptances/projections emit nothing new (`INSERT OR IGNORE`).
    async fn record_monitor_run_trace_events(
        &self,
        scope: &ScopeRef,
        accepted: &AcceptedMonitorRun,
    ) {
        let result = &accepted.result;
        let task_id = accepted.task_id.as_str();
        let execution_id = accepted.execution_id.as_str();

        // monitor_run_started — emitted at acceptance with the run's own
        // started_at (see project_monitor_run_outcome docs for why the
        // dispatch seam is not instrumented).
        self.append_monitor_trace_event(
            scope,
            "monitor_run_started",
            task_id,
            &format!("{task_id}\u{1f}{execution_id}\u{1f}started"),
            AttentionFunnelStage::Ingested,
            AttentionTraceStatus::Started,
            json!({
                "execution_id": execution_id,
                "monitor_revision": accepted.monitor_revision,
                "started_at": result.started_at,
            }),
        )
        .await;

        // monitor_run_completed — every accepted terminal run, including
        // synthesized failed markers (status carries the truth).
        let completed_status = if result.status == MonitorRunStatus::Failed {
            AttentionTraceStatus::Failed
        } else {
            AttentionTraceStatus::Succeeded
        };
        self.append_monitor_trace_event(
            scope,
            "monitor_run_completed",
            task_id,
            &format!("{task_id}\u{1f}{execution_id}\u{1f}completed"),
            AttentionFunnelStage::Distilled,
            completed_status,
            json!({
                "execution_id": execution_id,
                "monitor_revision": accepted.monitor_revision,
                "status": result.status,
                "complete_scan": result.complete_scan,
                "counts": result.counts,
                "completed_at": result.completed_at,
                "material": accepted.material,
                "would_notify": accepted.would_notify,
            }),
        )
        .await;

        if result.status == MonitorRunStatus::Degraded {
            self.append_monitor_trace_event(
                scope,
                "monitor_run_degraded",
                task_id,
                &format!("{task_id}\u{1f}{execution_id}\u{1f}degraded"),
                AttentionFunnelStage::Distilled,
                AttentionTraceStatus::Failed,
                json!({
                    "execution_id": execution_id,
                    "monitor_revision": accepted.monitor_revision,
                    "access_problem_source": result
                        .access_problem
                        .as_ref()
                        .map(|problem| problem.source.clone()),
                }),
            )
            .await;
        }

        if accepted.material {
            self.append_monitor_trace_event(
                scope,
                "monitor_change_detected",
                task_id,
                &format!("{task_id}\u{1f}{execution_id}\u{1f}change"),
                AttentionFunnelStage::Extracted,
                AttentionTraceStatus::Succeeded,
                json!({
                    "execution_id": execution_id,
                    "monitor_revision": accepted.monitor_revision,
                    "change_fingerprint": result.change_fingerprint,
                    "new": result.counts.new,
                    "updated": result.counts.updated,
                    "possibly_removed": result.counts.possibly_removed,
                }),
            )
            .await;
        }
    }

    /// Best-effort notification observability + the durable §7.4 dedupe row.
    /// Never fails the projection: the ledger written above is authoritative.
    ///
    /// §12 mapping (bounded reason enum, `monitor_updates::
    /// notification_suppression_reason`):
    /// * Changed-surface notification → `monitor_notification_sent` (the
    ///   UNIQUE `monitor-notify:` row IS the durable per-channel dedupe);
    ///   when a NEWLY recorded update finds its dedupe row already durable
    ///   (same change fingerprint resurfacing past the compaction horizon)
    ///   → `monitor_notification_suppressed` with reason `dedupe_replay`.
    /// * recorded-but-quiet updates → `monitor_notification_suppressed`
    ///   with `policy_never` / `unchanged` / `quiet_every_run`.
    /// * runs that minted NO update record (quiet runs under the default
    ///   policy) → `monitor_notification_suppressed` keyed on the execution
    ///   id, so every accepted run's surfaced/suppressed decision is
    ///   explained exactly once (§12 exit criterion).
    async fn record_monitor_notification_outcome(
        &self,
        scope: &ScopeRef,
        spec: &MonitorSpecV1,
        accepted: &AcceptedMonitorRun,
        update: Option<&MonitorUpdateDetailV1>,
        newly_recorded: bool,
    ) {
        let Some(store) = self.attention_funnel_store.get() else {
            return;
        };
        let suppression = notification_suppression_reason(&spec.notification_policy, update);

        let Some(update) = update else {
            // No update record at all — explain the quiet run once,
            // deterministically keyed on the execution id.
            let reason = suppression.unwrap_or(MonitorNotificationSuppressionReason::Unchanged);
            self.append_monitor_trace_event(
                scope,
                "monitor_notification_suppressed",
                &accepted.task_id,
                &format!(
                    "{}\u{1f}{}\u{1f}no-record-suppressed",
                    accepted.task_id, accepted.execution_id
                ),
                AttentionFunnelStage::Filtered,
                AttentionTraceStatus::Skipped,
                json!({
                    "execution_id": accepted.execution_id,
                    "monitor_revision": accepted.monitor_revision,
                    "status": accepted.result.status,
                    "reason": reason.as_str(),
                    "channel": MONITOR_UPDATE_CHANNEL_TODAY_CHANGED,
                }),
            )
            .await;
            return;
        };

        let occurred_at = chrono::DateTime::parse_from_rfc3339(&update.occurred_at)
            .map(|value| value.timestamp_millis())
            .unwrap_or_else(|_| Utc::now().timestamp_millis());
        let created_at = Utc::now().timestamp_millis();
        let source = AttentionSource {
            kind: AttentionSourceKind::Task,
            source_ref: format!("monitor:{}", update.monitor_task_id),
            provider: None,
            account_alias: None,
        };
        let metadata = |reason: Option<MonitorNotificationSuppressionReason>| {
            json!({
                "producer": "monitor_projection",
                "trace": if reason.is_some() {
                    "monitor_notification_suppressed"
                } else {
                    "monitor_notification_sent"
                },
                "monitor_task_id": update.monitor_task_id,
                "update_id": update.update_id,
                "execution_id": update.execution_id,
                "monitor_revision": update.monitor_revision,
                "change_fingerprint": update.change_fingerprint,
                "channel": update.notification.channel,
                "dedupe_key": update.notification.dedupe_key,
                "newly_recorded": newly_recorded,
                "reason": reason.map(|reason| reason.as_str()),
            })
        };
        match suppression {
            None => {
                // The UNIQUE event id IS the durable per-channel dedupe (§7.4).
                let event = AttentionRouteEvent {
                    event_id: format!(
                        "monitor-notify:{}",
                        blake3::hash(update.notification.dedupe_key.as_bytes()).to_hex()
                    ),
                    scope: AttentionScope {
                        principal: scope.principal().to_string(),
                        workspace: scope.workspace().to_string(),
                    },
                    source,
                    source_family: AttentionSourceFamily::Task,
                    candidate_key: update.update_id.clone(),
                    stage: AttentionFunnelStage::Routed,
                    outcome: RouteOutcome::Routed {
                        lane: AttentionLane::Changed,
                        reason: RouteReason::ObservedChange,
                        priority: RoutePriority::Normal,
                    },
                    occurred_at,
                    created_at,
                    confidence: None,
                    metadata: metadata(None),
                };
                match store.append_event_returning_new(event).await {
                    Ok(true) => debug!(
                        update_id = %update.update_id,
                        "[MONITORS] notification recorded (monitor_notification_sent)"
                    ),
                    Ok(false) if newly_recorded => {
                        // A NEWLY recorded update whose §7.4 dedupe row was
                        // already durable: the same change fingerprint
                        // resurfaced (e.g. past the update-ledger compaction
                        // horizon) and the durable dedupe suppressed the
                        // duplicate notification. Explain it (§12
                        // `dedupe_replay`). Idempotent replays of the SAME
                        // acceptance never reach here (newly_recorded is
                        // false on replay), so replays still emit nothing.
                        self.append_monitor_trace_event(
                            scope,
                            "monitor_notification_suppressed",
                            &update.monitor_task_id,
                            &format!("{}\u{1f}dedupe-replay", update.notification.dedupe_key),
                            AttentionFunnelStage::Filtered,
                            AttentionTraceStatus::Skipped,
                            metadata(Some(MonitorNotificationSuppressionReason::DedupeReplay)),
                        )
                        .await;
                    },
                    Ok(false) => debug!(
                        update_id = %update.update_id,
                        "[MONITORS] replayed notification suppressed by durable dedupe"
                    ),
                    Err(error) => warn!(
                        update_id = %update.update_id,
                        error = %error,
                        "[MONITORS] failed to record notification dedupe row"
                    ),
                }
            },
            Some(reason) => {
                // Suppressed — record the bounded §12 reason, idempotent by
                // event id (same scheme Phase 3 used).
                let event = AttentionRouteEvent {
                    event_id: format!(
                        "monitor-notify-suppressed:{}",
                        blake3::hash(update.notification.dedupe_key.as_bytes()).to_hex()
                    ),
                    scope: AttentionScope {
                        principal: scope.principal().to_string(),
                        workspace: scope.workspace().to_string(),
                    },
                    source,
                    source_family: AttentionSourceFamily::Task,
                    candidate_key: update.update_id.clone(),
                    stage: AttentionFunnelStage::Filtered,
                    outcome: RouteOutcome::Traced {
                        status: AttentionTraceStatus::Skipped,
                    },
                    occurred_at,
                    created_at,
                    confidence: None,
                    metadata: metadata(Some(reason)),
                };
                if let Err(error) = store.append_event(event).await {
                    warn!(
                        update_id = %update.update_id,
                        error = %error,
                        "[MONITORS] failed to record notification suppression event"
                    );
                }
            },
        }
    }

    // ─── Recurring Monitors Phase 6 — useful / not-relevant feedback ─────

    /// Record one §10 feedback verdict against a durable monitor update.
    ///
    /// Contract (fixed wire contract — see `monitor_feedback.rs`):
    /// * idempotent per `(update_id, verdict)` — re-posting the CURRENT
    ///   verdict replays the persisted record (`newly_recorded: false`,
    ///   same deterministic `feedback_id`), writing nothing;
    /// * posting the OTHER verdict appends a new record — LATEST WINS per
    ///   update (the ledger keeps the append-only history, reads fold to
    ///   the current verdict);
    /// * a `not_relevant` verdict copies the implicated finding stable keys
    ///   + content fingerprints from the update record AT WRITE TIME as
    ///   retained evidence (§10 — feedback never rewrites the monitor
    ///   contract in v1);
    /// * the ledger is bounded at [`MONITOR_LEDGER_RETENTION_CAP`]
    ///   (compact-on-append, same discipline as the update ledger);
    /// * emits the §12 `monitor_feedback_recorded` trace exactly once per
    ///   newly recorded verdict.
    ///
    /// Errors: `monitor_required` for plain tasks (the API layer 404s
    /// monitors first), `monitor_update_not_found` when the update id is
    /// not in this monitor's update ledger (the API renders the contract's
    /// 404 `update_not_found`).
    pub async fn record_monitor_update_feedback(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        update_id: &str,
        verdict: MonitorFeedbackVerdict,
        note: Option<String>,
    ) -> Result<MonitorFeedbackOutcome, ArtifactV2Error> {
        let task = self.get_task(scope, task_id).await?;
        if task.manifest.monitor_spec.is_none() {
            return Err(ArtifactV2Error::InvalidRequest(
                "monitor_required".to_string(),
            ));
        }

        let _guard = self.acquire_task_write_guard(scope, task_id).await?;
        let updates_path = self.workspace.monitor_updates_log_path(
            &scope.principal(),
            &scope.workspace(),
            task_id,
        );
        // Tolerant: the answer is "does this update exist", so a dropped row
        // degrades to not-found, which this caller already handles. Failing the
        // whole lookup because an unrelated record is corrupt would be worse.
        let updates: Vec<MonitorUpdateDetailV1> = self
            .read_monitor_ledger(&updates_path, "monitor_updates")
            .await?;
        let Some(update) = updates
            .into_iter()
            .find(|record| record.update_id == update_id)
        else {
            return Err(ArtifactV2Error::InvalidRequest(
                "monitor_update_not_found".to_string(),
            ));
        };

        let feedback_path = self.workspace.monitor_feedback_log_path(
            &scope.principal(),
            &scope.workspace(),
            task_id,
        );
        // Torn tail tolerated, corruption refused. Latest-wins means the last
        // line for an update *is* the verdict, so dropping a line does not
        // shorten the answer — it silently returns an older verdict as current.
        let existing_read = self
            .workspace
            .read_jsonl_path_tolerant::<MonitorUpdateFeedbackV1, _>(&feedback_path)
            .await?;
        if existing_read.lost_committed_records() {
            return Err(ArtifactV2Error::Runtime(format!(
                "monitor feedback ledger {} has {} unreadable record(s); refusing to \
                 resolve a latest-wins verdict from an incomplete ledger",
                feedback_path.display(),
                existing_read.corrupt
            )));
        }
        let existing: Vec<MonitorUpdateFeedbackV1> = existing_read.records;

        // Latest-wins: the LAST ledger line for this update is its current
        // verdict. Same verdict again → idempotent replay.
        if let Some(current) = existing
            .iter()
            .rev()
            .find(|record| record.update_id == update_id)
        {
            if current.verdict == verdict {
                debug_assert_eq!(
                    current.feedback_id,
                    monitor_feedback_id(
                        &scope.principal(),
                        &scope.workspace(),
                        task_id,
                        update_id,
                        verdict
                    ),
                    "persisted feedback ids are deterministic"
                );
                return Ok(MonitorFeedbackOutcome {
                    feedback: current.clone(),
                    newly_recorded: false,
                });
            }
        }

        let feedback = build_monitor_feedback(
            &scope.principal(),
            &scope.workspace(),
            &update,
            verdict,
            normalize_feedback_note(note),
            now_rfc3339(),
        );
        self.append_monitor_ledger_bounded(&feedback_path, &existing, &feedback)
            .await?;

        // §12 monitor_feedback_recorded — once per newly recorded verdict
        // (idempotent replays return above, before this point). The seed
        // carries recorded_at so a later re-flip to the same verdict (same
        // deterministic feedback_id) still gets its own trace row.
        self.append_monitor_trace_event(
            scope,
            "monitor_feedback_recorded",
            task_id,
            &format!("{}\u{1f}{}", feedback.feedback_id, feedback.recorded_at),
            AttentionFunnelStage::Acted,
            AttentionTraceStatus::Succeeded,
            json!({
                "feedback_id": feedback.feedback_id,
                "update_id": feedback.update_id,
                "verdict": feedback.verdict.as_str(),
                "has_note": feedback.note.is_some(),
                "evidence_stable_keys": feedback
                    .evidence
                    .as_ref()
                    .map(|evidence| evidence.stable_keys.len())
                    .unwrap_or(0),
            }),
        )
        .await;

        Ok(MonitorFeedbackOutcome {
            feedback,
            newly_recorded: true,
        })
    }

    /// List one monitor's CURRENT feedback (latest verdict per update),
    /// newest first. Reads the per-task `monitor_feedback.jsonl` ledger —
    /// no new store. 400 `monitor_required` for plain tasks (the API layer
    /// 404s them first).
    pub async fn list_monitor_update_feedback(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        limit: usize,
    ) -> Result<Vec<MonitorUpdateFeedbackV1>, ArtifactV2Error> {
        let task = self.get_task(scope, task_id).await?;
        if task.manifest.monitor_spec.is_none() {
            return Err(ArtifactV2Error::InvalidRequest(
                "monitor_required".to_string(),
            ));
        }
        let path = self.workspace.monitor_feedback_log_path(
            &scope.principal(),
            &scope.workspace(),
            task_id,
        );
        let records: Vec<MonitorUpdateFeedbackV1> =
            self.read_monitor_ledger(&path, "monitor_feedback").await?;
        let mut current = latest_feedback_per_update(records);
        current.truncate(limit.max(1));
        Ok(current)
    }

    /// §5.5 Attention lifecycle: auto-resolve recovered sources, then route
    /// a Needs-You candidate when the accepted run carries an
    /// `access_problem` whose source has now failed on
    /// [`MONITOR_SOURCE_FAILURE_ATTENTION_THRESHOLD`] consecutive runs.
    /// Best-effort and idempotent — attention must never block acceptance.
    async fn project_monitor_access_attention(
        &self,
        scope: &ScopeRef,
        task: &TaskRecord,
        accepted: &AcceptedMonitorRun,
        update: Option<&MonitorUpdateDetailV1>,
    ) {
        let result = &accepted.result;
        // Auto-resolve first: every source this run read ok+complete clears
        // its (possibly absent) item — unconditional and idempotent, so a
        // crash between acceptance and projection self-heals on replay.
        // Failed-run markers resolve nothing (they prove nothing).
        if result.status != MonitorRunStatus::Failed {
            for outcome in &result.source_outcomes {
                if outcome.status == MonitorSourceOutcomeStatus::Ok && outcome.complete {
                    self.resolve_monitor_access_problem(
                        scope,
                        &accepted.task_id,
                        &outcome.source,
                        &accepted.execution_id,
                    )
                    .await;
                }
            }
        }

        let Some(problem) = result.access_problem.as_ref() else {
            return;
        };
        // The streaks come from the ACCEPTANCE'S OWN post-acceptance
        // snapshot (`AcceptedMonitorRun.source_failures`), never from a
        // re-read of the task cursor: a replayed projection of an OLDER
        // acceptance must see that run's streaks, not whatever a newer
        // accepted run has since written to the cursor.
        let Some(entry) = accepted
            .source_failures
            .iter()
            .find(|entry| entry.source == problem.source)
            .cloned()
        else {
            return;
        };
        if entry.consecutive_failures < MONITOR_SOURCE_FAILURE_ATTENTION_THRESHOLD {
            // First blip — quiet by design (§5.5 step 3).
            return;
        }

        let now_ms = Utc::now().timestamp_millis();
        let item = monitor_access_problem_feed_item(
            &scope.principal(),
            &scope.workspace(),
            &accepted.task_id,
            &task.manifest.title,
            problem,
            &entry,
            &accepted.execution_id,
            update.map(|update| update.update_id.as_str()),
            now_ms,
        );

        // Deterministic canonical routing — the shared router owns the lane.
        let candidate = AttentionCandidate {
            candidate_key: item.id.clone(),
            source: AttentionSource {
                kind: AttentionSourceKind::Task,
                source_ref: format!("monitor:{}:{}", accepted.task_id, problem.source),
                provider: None,
                account_alias: None,
            },
            source_family: AttentionSourceFamily::Task,
            evidence_refs: vec![format!("task:{}", accepted.task_id)],
            title: item.title.clone(),
            summary: item.summary.clone().unwrap_or_default(),
            action: None,
            urgency: AttentionUrgency::High,
            confidence: None,
            metadata: item.metadata.clone(),
        };
        let outcome = route_attention_candidate(
            &candidate,
            &AttentionRouteContext {
                access_problem_detected: true,
                ..Default::default()
            },
        );
        let RouteOutcome::Routed {
            lane,
            reason,
            priority,
        } = outcome
        else {
            return;
        };

        match self.feed_projection_adapter.get() {
            Some(adapter) => {
                // At the streak's FIRST threshold crossing, clear any stale
                // dismissal tombstone (from a previous resolved streak or an
                // old owner dismissal) so a NEW problem resurfaces; while a
                // streak persists past the threshold, an owner dismissal
                // stands (§7.4: dismissal suppresses the occurrence, not the
                // monitor forever).
                if entry.consecutive_failures == MONITOR_SOURCE_FAILURE_ATTENTION_THRESHOLD {
                    if let Err(error) = adapter
                        .record_monitor_attention_dismissal(scope, &item.id, false)
                        .await
                    {
                        warn!(
                            item_id = %item.id,
                            error = %error,
                            "[MONITORS] failed to clear stale access-problem dismissal"
                        );
                    }
                }
                if let Err(error) = adapter.upsert_monitor_attention_item(item.clone()).await {
                    warn!(
                        item_id = %item.id,
                        error = %error,
                        "[MONITORS] failed to materialize access-problem attention item"
                    );
                }
            },
            None => debug!(
                item_id = %item.id,
                "[MONITORS] no feed projection wired; access-problem item not materialized"
            ),
        }

        if let Some(store) = self.attention_funnel_store.get() {
            // Idempotent per (item, streak length): each additional failing
            // run appends one routed event, replays of the same run none.
            let event_id = format!(
                "monitor-access:{}",
                blake3::hash(format!("{}\u{1f}{}", item.id, entry.consecutive_failures).as_bytes())
                    .to_hex()
            );
            let event = AttentionRouteEvent {
                event_id,
                scope: AttentionScope {
                    principal: scope.principal().to_string(),
                    workspace: scope.workspace().to_string(),
                },
                source: candidate.source.clone(),
                source_family: candidate.source_family,
                candidate_key: candidate.candidate_key.clone(),
                stage: AttentionFunnelStage::Routed,
                outcome: RouteOutcome::Routed {
                    lane,
                    reason,
                    priority,
                },
                occurred_at: now_ms,
                created_at: now_ms,
                confidence: None,
                metadata: json!({
                    "producer": "monitor_projection",
                    "trace": "monitor_source_access_failed",
                    "monitor_task_id": accepted.task_id,
                    "source": problem.source,
                    "consecutive_failures": entry.consecutive_failures,
                    "execution_id": accepted.execution_id,
                    "update_id": update.map(|update| update.update_id.as_str()),
                }),
            };
            if let Err(error) = store.append_event(event).await {
                warn!(
                    error = %error,
                    "[MONITORS] failed to record access-problem route event"
                );
            }
        }
    }

    /// Auto-resolve one monitor+source access item: remove the materialized
    /// escalation (no-op when absent) and record the funnel-supported
    /// dismissal so any projected attention row clears too (§5.5 step 5).
    async fn resolve_monitor_access_problem(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        source: &str,
        execution_id: &str,
    ) {
        let item_id = monitor_access_problem_item_id(task_id, source);
        let Some(adapter) = self.feed_projection_adapter.get() else {
            return;
        };
        match adapter.remove_monitor_attention_item(scope, &item_id).await {
            Ok(true) => {
                if let Err(error) = adapter
                    .record_monitor_attention_dismissal(scope, &item_id, true)
                    .await
                {
                    warn!(
                        item_id = %item_id,
                        error = %error,
                        "[MONITORS] failed to record access-problem resolution dismissal"
                    );
                }
                if let Some(store) = self.attention_funnel_store.get() {
                    let now_ms = Utc::now().timestamp_millis();
                    let event = AttentionRouteEvent {
                        event_id: format!(
                            "monitor-access-restored:{}",
                            blake3::hash(format!("{item_id}\u{1f}{execution_id}").as_bytes())
                                .to_hex()
                        ),
                        scope: AttentionScope {
                            principal: scope.principal().to_string(),
                            workspace: scope.workspace().to_string(),
                        },
                        source: AttentionSource {
                            kind: AttentionSourceKind::Task,
                            source_ref: format!("monitor:{task_id}:{source}"),
                            provider: None,
                            account_alias: None,
                        },
                        source_family: AttentionSourceFamily::Task,
                        candidate_key: item_id.clone(),
                        stage: AttentionFunnelStage::Acted,
                        outcome: RouteOutcome::Traced {
                            status: AttentionTraceStatus::Succeeded,
                        },
                        occurred_at: now_ms,
                        created_at: now_ms,
                        confidence: None,
                        metadata: json!({
                            "producer": "monitor_projection",
                            "trace": "monitor_source_access_restored",
                            "monitor_task_id": task_id,
                            "source": source,
                            "execution_id": execution_id,
                        }),
                    };
                    if let Err(error) = store.append_event(event).await {
                        warn!(
                            error = %error,
                            "[MONITORS] failed to record access-restored event"
                        );
                    }
                }
            },
            Ok(false) => {},
            Err(error) => warn!(
                item_id = %item_id,
                error = %error,
                "[MONITORS] failed to remove resolved access-problem item"
            ),
        }
    }

    /// Phase 3 terminal wiring: when a MONITOR task's ROOT execution reaches
    /// terminal, extract the agent-emitted `monitor_run_result` artifact from
    /// the persisted-artifacts index, accept it (validation + §7 change
    /// ledger — idempotent), and run the deterministic notification/Attention
    /// projection. A completed run without a parseable/valid artifact — and
    /// any failed/cancelled run — records a synthesized FAILED run marker so
    /// monitor history stays complete without ever advancing the change
    /// ledger.
    ///
    /// STRICTLY gated on `manifest.monitor_spec` — non-monitor executions
    /// take one boolean check and return. Best-effort by contract: every
    /// failure warns and returns; generic finalization is never blocked.
    async fn finalize_monitor_run_at_terminal(
        &self,
        binding: &V3ExecutionBinding,
        task: &TaskRecord,
        execution: &ExecutionRecord,
        outcome: &ExecutionOutcomeSnapshot,
    ) {
        if task.manifest.monitor_spec.is_none() || !outcome.is_terminal {
            return;
        }
        // The monitor output contract targets the task's ROOT run; child
        // delegation executions terminating must not mint failed markers.
        if execution.state.parent_execution_id.is_some() {
            return;
        }
        let scope = &binding.scope;
        let task_id = &binding.execution.task_id;
        let execution_id = &binding.execution.execution_id;

        let extracted = if outcome.execution_status == "completed" {
            match self
                .extract_monitor_run_result_artifact(scope, task_id, execution_id)
                .await
            {
                Ok(Some(result)) => Some(result),
                Ok(None) => {
                    warn!(
                        task_id = %task_id,
                        execution_id = %execution_id,
                        "[MONITORS] completed monitor run emitted no monitor_run_result artifact — recording a failed-run marker"
                    );
                    None
                },
                Err(error) => {
                    warn!(
                        task_id = %task_id,
                        execution_id = %execution_id,
                        error = %error,
                        "[MONITORS] could not read persisted artifacts for monitor run — recording a failed-run marker"
                    );
                    None
                },
            }
        } else {
            // failed/cancelled executions record a marker for history.
            None
        };

        let accepted = match extracted {
            Some(result) => match self
                .accept_monitor_run(scope, task_id, execution_id, result)
                .await
            {
                Ok(accepted) => Some(accepted),
                Err(error) => {
                    warn!(
                        task_id = %task_id,
                        execution_id = %execution_id,
                        error = %error,
                        "[MONITORS] monitor run result failed validation/acceptance — recording a failed-run marker"
                    );
                    self.accept_failed_monitor_run_marker(
                        scope,
                        task,
                        execution,
                        &format!("monitor_run_result rejected: {error}"),
                    )
                    .await
                },
            },
            None => {
                self.accept_failed_monitor_run_marker(
                    scope,
                    task,
                    execution,
                    &format!(
                        "execution reached terminal status `{}` without an acceptable monitor_run_result",
                        outcome.execution_status
                    ),
                )
                .await
            },
        };

        if let Some(accepted) = accepted {
            if let Err(error) = self.project_monitor_run_outcome(scope, &accepted).await {
                warn!(
                    task_id = %task_id,
                    execution_id = %execution_id,
                    error = %error,
                    "[MONITORS] monitor run projection failed; acceptance is durable and a later replay re-projects"
                );
            }
        }
    }

    /// Find the agent-emitted `monitor_run_result` in the persisted-artifact
    /// index: a typed `monitor_run_result` record's payload first, then a
    /// tolerant fallback for runs that wrote the JSON as a tool-output FILE
    /// named `monitor_run_result*.json`.
    async fn extract_monitor_run_result_artifact(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        execution_id: &str,
    ) -> Result<Option<MonitorRunResultV1>, ArtifactV2Error> {
        let store = super::execution_artifacts::FilesystemExecutionArtifactIndexStore::new(
            self.workspace.clone(),
        );
        let records = store.list_artifacts(scope, task_id, execution_id).await?;
        // Newest matching typed record wins (list_artifacts sorts by
        // produced_at ascending).
        if let Some(result) = records
            .iter()
            .rev()
            .filter(|record| record.artifact_type == MONITOR_RUN_RESULT_ARTIFACT_TYPE)
            .find_map(|record| MonitorRunResultV1::deserialize(&record.payload).ok())
        {
            return Ok(Some(result));
        }
        // Fallback: a tool-output file whose name carries the contract name.
        for record in records.iter().rev() {
            if record.artifact_type != "tool_output_file" {
                continue;
            }
            let named_monitor_result = ["display_name", "file_name"].iter().any(|key| {
                record
                    .payload
                    .get(*key)
                    .and_then(Value::as_str)
                    .map(|name| name.starts_with("monitor_run_result"))
                    .unwrap_or(false)
            });
            if !named_monitor_result {
                continue;
            }
            for path_key in ["execution_absolute_path", "task_absolute_path"] {
                let Some(path) = record.payload.get(path_key).and_then(Value::as_str) else {
                    continue;
                };
                if let Ok(result) = read_monitor_run_result_tool_output(
                    &self.workspace,
                    Path::new(path),
                    MONITOR_RUN_RESULT_TOOL_OUTPUT_MAX_BYTES,
                )
                .await
                {
                    return Ok(Some(result));
                }
            }
        }
        Ok(None)
    }

    /// Record a synthesized FAILED run marker through the normal acceptance
    /// path (idempotent; never advances the change ledger — see the failed
    /// branch of `accept_monitor_run`). Returns `None` when even the marker
    /// cannot be accepted; that is warned, never propagated.
    async fn accept_failed_monitor_run_marker(
        &self,
        scope: &ScopeRef,
        task: &TaskRecord,
        execution: &ExecutionRecord,
        reason: &str,
    ) -> Option<AcceptedMonitorRun> {
        let task_id = &task.manifest.task_id;
        let execution_id = &execution.state.execution_id;
        let started_at = execution.state.started_at.clone();
        let completed_at = execution
            .state
            .completed_at
            .clone()
            .unwrap_or_else(|| execution.state.updated_at.clone());
        let marker = MonitorRunResultV1 {
            monitor_task_id: task_id.clone(),
            execution_id: execution_id.clone(),
            monitor_revision: task.manifest.monitor_revision,
            started_at,
            completed_at,
            status: MonitorRunStatus::Failed,
            complete_scan: false,
            source_outcomes: vec![MonitorSourceOutcomeV1 {
                source: "monitor_runtime".to_string(),
                status: MonitorSourceOutcomeStatus::Error,
                complete: false,
                items_scanned: 0,
                note: Some(reason.chars().take(2000).collect()),
            }],
            counts: MonitorCountsV1 {
                scanned: 0,
                new: 0,
                updated: 0,
                unchanged: 0,
                possibly_removed: 0,
            },
            findings: Vec::new(),
            run_fingerprint: monitor_run_fingerprint(task_id, task.manifest.monitor_revision, &[]),
            change_fingerprint: None,
            access_problem: None,
        };
        match self
            .accept_monitor_run(scope, task_id, execution_id, marker)
            .await
        {
            Ok(accepted) => Some(accepted),
            Err(error) => {
                warn!(
                    task_id = %task_id,
                    execution_id = %execution_id,
                    error = %error,
                    "[MONITORS] failed-run marker could not be recorded"
                );
                None
            },
        }
    }

    pub async fn find_task_scope(
        &self,
        task_id: &str,
    ) -> Result<Option<ScopeRef>, ArtifactV2Error> {
        ArtifactV2Workspace::validate_task_id(task_id)?;
        let scopes = self.workspace.list_scope_segments().await?;
        let mut matched_scope = None;
        for (principal, workspace) in scopes {
            let manifest_path = self
                .workspace
                .task_manifest_path(&principal, &workspace, task_id);
            if !self.workspace.exists_path(&manifest_path).await? {
                continue;
            }

            let scope = ScopeRef::system_internal_unauthenticated(&principal, &workspace);
            if matched_scope.is_some() {
                return Err(ArtifactV2Error::InvalidRequest(format!(
                    "task_id_ambiguous:{task_id}"
                )));
            }
            matched_scope = Some(scope);
        }
        Ok(matched_scope)
    }

    pub async fn get_task_by_id(
        &self,
        task_id: &str,
    ) -> Result<Option<(ScopeRef, TaskRecord)>, ArtifactV2Error> {
        let Some(scope) = self.find_task_scope(task_id).await? else {
            return Ok(None);
        };
        let task = self.get_task(&scope, task_id).await?;
        Ok(Some((scope, task)))
    }

    pub async fn get_task_list_item(
        &self,
        scope: &ScopeRef,
        task_id: &str,
    ) -> Result<TaskListItemV3, ArtifactV2Error> {
        let task = self.get_task(scope, task_id).await?;
        // One task, so derive the answer for one task — do not build the
        // scope-wide snapshot to read one row out of it.
        //
        // This is not a listing path. The feed materializer calls it from
        // `apply_task_message`, which runs on **every** progress message, so
        // at heartbeat cadence the scope-wide form was a full walk of
        // `code_change_proposals/` per message — with a full
        // `CodeChangeProposal` parse per pending record, diff text included,
        // and a scope-wide map built and thrown away to answer one boolean and
        // one short id list.
        let pending = self.pending_diff_approvals_for_task(scope, task_id);
        self.build_task_list_item(scope, task, &pending).await
    }

    fn emit_scheduled_task_routine_result(
        &self,
        scope: &ScopeRef,
        task: &TaskRecord,
        execution: &ExecutionRecord,
        outcome: &ExecutionOutcomeSnapshot,
        summary_override: Option<&str>,
    ) {
        let Some(payload) = scheduled_task_routine_result_payload(
            scope,
            task,
            execution,
            outcome,
            summary_override,
        ) else {
            return;
        };
        let Some(broadcaster) = self.runtime_event_broadcaster.get() else {
            return;
        };
        broadcaster.emit_agent_transport_event(AgentEventEnvelope::new_scoped(
            ROUTINE_RESULT_PUBLISHED_EVENT_TYPE,
            &task.manifest.agent_id,
            &scope.principal(),
            &scope.workspace(),
            payload,
        ));
    }

    fn emit_task_updated_transport(&self, task: &TaskRecord) {
        let Some(broadcaster) = self.runtime_event_broadcaster.get() else {
            return;
        };
        let updated_at = rfc3339_to_millis(&task.state.updated_at)
            .unwrap_or_else(|| chrono::Utc::now().timestamp_millis());
        broadcaster.emit(
            crate::magician_v2::realtime_events::RuntimeTransportEvent::TaskUpdated {
                principal: task.manifest.principal.clone(),
                workspace: task.manifest.workspace.clone(),
                task_id: task.manifest.task_id.clone(),
                execution_id: task
                    .state
                    .active_root_execution_id
                    .clone()
                    .or_else(|| task.state.latest_root_execution_id.clone()),
                ui_thread_id: Some(task.manifest.ui_thread_id.clone()),
                title: task.manifest.title.clone(),
                updated_at,
                timestamp: chrono::Utc::now().timestamp_millis(),
            },
        );

        // Parallel emission for the operator-facing feed. Map
        // `task.state.status` to the appropriate AgentUpdateKind variant so
        // the feed distinguishes create / progress / complete / fail rather
        // than just showing `TaskUpdated` for everything.
        let task_id = task.manifest.task_id.clone();
        let title = task.manifest.title.clone();
        let kind = match task.state.status.as_str() {
            "planning" | "ready" => {
                crate::magician_v2::agents::agent_update::AgentUpdateKind::TaskCreated {
                    task_id: task_id.clone(),
                    title,
                }
            },
            "completed" => {
                crate::magician_v2::agents::agent_update::AgentUpdateKind::TaskCompleted {
                    task_id: task_id.clone(),
                    artifacts: Vec::new(),
                }
            },
            "failed" | "cancelled" => {
                crate::magician_v2::agents::agent_update::AgentUpdateKind::TaskFailed {
                    task_id: task_id.clone(),
                    error: task.state.status.clone(),
                }
            },
            // "running", "paused", or anything else → progress update.
            _ => crate::magician_v2::agents::agent_update::AgentUpdateKind::TaskUpdated {
                task_id: task_id.clone(),
                changed_fields: vec![task.state.status.clone()],
            },
        };
        let update = crate::magician_v2::agents::agent_update::AgentUpdate::new(
            task.manifest.workspace.clone(),
            task.manifest.agent_id.clone(),
            kind,
        );
        crate::magician_v2::agents::agent_update_emitter::publish_agent_update(
            broadcaster,
            Some(task.manifest.principal.as_str()),
            Some(task.manifest.workspace.as_str()),
            update,
        );
    }

    fn emit_planning_transport(&self, event: RuntimeTransportEvent) {
        let Some(broadcaster) = self.runtime_event_broadcaster.get() else {
            return;
        };
        broadcaster.emit_transport_only(event);
    }

    fn emit_v3_planning_started(&self, scope: &ScopeRef, task: &TaskRecord, plan: &TaskPlanRecord) {
        self.emit_planning_transport(RuntimeTransportEvent::V3PlanningStarted {
            principal: scope.principal().to_string(),
            workspace: scope.workspace().to_string(),
            task_id: task.manifest.task_id.clone(),
            task_title: task.manifest.title.clone(),
            agent_id: task.manifest.agent_id.clone(),
            plan_id: plan.plan_id.clone(),
            ui_thread_id: task.manifest.ui_thread_id.clone(),
            timestamp: chrono::Utc::now().timestamp_millis(),
        });
    }

    fn emit_v3_planning_progress(
        &self,
        scope: &ScopeRef,
        task: &TaskRecord,
        plan: &TaskPlanRecord,
        phase: &str,
        detail: impl Into<Option<String>>,
    ) {
        self.emit_planning_transport(RuntimeTransportEvent::V3PlanningProgress {
            principal: scope.principal().to_string(),
            workspace: scope.workspace().to_string(),
            task_id: task.manifest.task_id.clone(),
            task_title: task.manifest.title.clone(),
            agent_id: task.manifest.agent_id.clone(),
            plan_id: plan.plan_id.clone(),
            ui_thread_id: task.manifest.ui_thread_id.clone(),
            phase: phase.to_string(),
            detail: detail.into(),
            timestamp: chrono::Utc::now().timestamp_millis(),
        });
    }

    fn emit_v3_planning_clarification_needed(
        &self,
        scope: &ScopeRef,
        task: &TaskRecord,
        plan: &TaskPlanRecord,
        questions: Vec<RecommendedQuestion>,
    ) {
        if questions.is_empty() {
            return;
        }
        let timestamp = chrono::Utc::now().timestamp_millis();
        // Phase H4 — canonical `HitlRequested` dual-emit per question so
        // the unified `pendingHitlStore` (subscribes via `category=hitl`)
        // counts V3 planning clarifications alongside agentic pauses,
        // approvals, and ask_loop clarifications. `correlation_id =
        // question.id` matches the ask_loop `clarification.queued`
        // helper, so when both paths fire on the same question the
        // frontend deduplicates into one pending entry.
        //
        // Multi-stage MVP: when the elicitor returns N questions in one
        // pass (a batch), stamp a shared `chain_id` + per-question
        // `chain_position` / `chain_total` onto each emitted
        // `HitlRequested.input_schema`. The frontend reads these and
        // renders a "Step X of N" indicator in the prompt modal so the
        // operator sees the batch as one logical decision rather than N
        // independent prompts. Single-question emissions (the common
        // case) omit the fields entirely, preserving today's
        // "no chain" rendering.
        //
        // Chain id is *deterministic* across re-emits — derived from
        // `plan_id` + a 16-char hash of the sorted question ids — so
        // when the planner re-clarifies the same batch (retry, re-run),
        // the modal's "Step X of N" header stays attached to the same
        // chain instead of minting a fresh chain on every retry.
        // Stable across process restarts: `DefaultHasher` (SipHasher13)
        // is seeded with per-process random keys, so the same batch would
        // mint a fresh chain_id after every server restart and the
        // modal's "Step X of N" header would rebind. Use SHA-256 over a
        // joined string instead so re-emission of the same batch reuses
        // the same chain_id across restarts.
        let questions: Vec<RecommendedQuestion> = questions.into_iter().take(3).collect();
        let chain_id = planning_clarification_chain_id(&plan.plan_id, &questions);
        let chain_total = questions.len();
        if let Some(broadcaster) = self.runtime_event_broadcaster.get() {
            if questions.len() >= 2 {
                let Some(chain_id) = chain_id.clone() else {
                    return;
                };
                let (input_schema, hint) =
                    planning_clarification_form_schema(task, plan, &questions, &chain_id);
                broadcaster.emit(RuntimeTransportEvent::HitlRequested {
                    correlation_id: chain_id,
                    source: "clarification".to_string(),
                    input_type: "form".to_string(),
                    prompt: format!(
                        "Planning needs {} answers before it can continue.",
                        questions.len()
                    ),
                    hint,
                    input_schema: Some(input_schema),
                    task_id: Some(task.manifest.task_id.clone()),
                    execution_id: plan
                        .planning_execution_id
                        .clone()
                        .or_else(|| Some(task.manifest.task_id.clone())),
                    agent_id: Some(task.manifest.agent_id.clone()),
                    principal: Some(scope.principal().to_string()),
                    workspace: Some(scope.workspace().to_string()),
                    timestamp,
                });
            } else {
                for (idx, question) in questions.iter().enumerate() {
                    let (input_type, hint, input_schema, _) = planning_clarification_presentation(
                        task,
                        plan,
                        question,
                        chain_id.as_deref(),
                        idx,
                        chain_total,
                    );
                    // Use `emit` (not `emit_transport_only`) so `map_v2_realtime_event`
                    // writes a `hitl.requested` row into `events.jsonl`. Without this,
                    // `/api/magician/v3/events?category=hitl` backfill misses the pending
                    // HITL on fresh page loads — operator sees a stale empty `/attention`
                    // until the next live event re-arrives. Same fix on the resolve side
                    // below.
                    broadcaster.emit(RuntimeTransportEvent::HitlRequested {
                        correlation_id: question.id.clone(),
                        source: "clarification".to_string(),
                        input_type,
                        prompt: question.question_text.clone(),
                        hint,
                        input_schema: Some(input_schema),
                        task_id: Some(task.manifest.task_id.clone()),
                        // Persist under the real planning execution. The target
                        // also carries task_id, which the frontend sends as the
                        // clarification workflow id when responding.
                        execution_id: plan
                            .planning_execution_id
                            .clone()
                            .or_else(|| Some(task.manifest.task_id.clone())),
                        agent_id: Some(task.manifest.agent_id.clone()),
                        principal: Some(scope.principal().to_string()),
                        workspace: Some(scope.workspace().to_string()),
                        timestamp,
                    });
                }
            }
        }
        // Phase H6.3 — legacy `V3PlanningClarificationNeeded` typed
        // emit retired. The canonical `HitlRequested` loop above
        // covers `pendingHitlStore` + Plan Inspector (consumers
        // already on canonical via H4.9). `questions` is dropped
        // here intentionally — without the typed-variant emit there's
        // no consumer of the legacy event shape.
        let _ = (plan, questions);

        // Phase H4.9 — canonical `HitlRequested` per question already
        // emitted above; `HitlResolved` will fire on resolution.
    }

    /// Emit canonical `HitlRequested { source: "plan_approval" }` when
    /// a task plan reaches `Draft` (= ready for human review). Operators
    /// see the row in `/attention`, click → modal renders an
    /// Approve / Reject confirmation, response routes through the
    /// canonical `/hitl/{plan_id}/respond` endpoint with
    /// `source: "plan_approval"`. Resolved by
    /// `emit_plan_approval_resolved` from `approve_task_plan` /
    /// `reject_task_plan`.
    ///
    /// `correlation_id == plan_id` so the same plan never spawns
    /// duplicate prompts across re-validations of the same Draft
    /// version (`pendingHitlStore` dedups on correlation_id).
    fn emit_plan_approval_requested(
        &self,
        scope: &ScopeRef,
        task: &TaskRecord,
        plan: &TaskPlanRecord,
    ) {
        if let Some(broadcaster) = self.runtime_event_broadcaster.get() {
            let title = task.manifest.title.clone();
            let input_schema = serde_json::json!({
                "type": "confirmation",
                "confirm_label": "Approve",
                "deny_label": "Reject",
                "plan_id": plan.plan_id,
                "task_id": task.manifest.task_id,
            });
            // Use `emit` (not `emit_transport_only`) so `map_v2_realtime_event`
            // writes a `hitl.requested` row into `events.jsonl`. Without this,
            // `/api/magician/v3/events?category=hitl` backfill misses the pending
            // HITL on fresh page loads — operator sees a stale empty `/attention`
            // until the next live event re-arrives. Same fix on the resolve side
            // below.
            broadcaster.emit(RuntimeTransportEvent::HitlRequested {
                correlation_id: plan.plan_id.clone(),
                source: "plan_approval".to_string(),
                input_type: "confirmation".to_string(),
                prompt: format!("Plan ready for review: {title}"),
                hint: Some("Approve to execute, or reject to send back for revision.".to_string()),
                input_schema: Some(input_schema),
                task_id: Some(task.manifest.task_id.clone()),
                execution_id: plan
                    .planning_execution_id
                    .clone()
                    .or_else(|| Some(task.manifest.task_id.clone())),
                agent_id: Some(task.manifest.agent_id.clone()),
                principal: Some(scope.principal().to_string()),
                workspace: Some(scope.workspace().to_string()),
                timestamp: chrono::Utc::now().timestamp_millis(),
            });
        }
    }

    /// Emit canonical `HitlResolved` for a Draft plan that has been
    /// approved or rejected. Called from `approve_task_plan` /
    /// `reject_task_plan` so `pendingHitlStore` and `/attention`
    /// decrement immediately.
    fn emit_plan_approval_resolved(
        &self,
        scope: &ScopeRef,
        task: &TaskRecord,
        plan: &TaskPlanRecord,
        approved: bool,
    ) {
        if let Some(broadcaster) = self.runtime_event_broadcaster.get() {
            // `emit` (not `emit_transport_only`) so the resolution is persisted
            // to `events.jsonl`. Otherwise backfill on a fresh `/attention` load
            // after the resolve shows the stale Requested row as still pending.
            broadcaster.emit(RuntimeTransportEvent::HitlResolved {
                correlation_id: plan.plan_id.clone(),
                source: "plan_approval".to_string(),
                outcome: "responded".to_string(),
                decision: Some(if approved { "approve" } else { "reject" }.to_string()),
                task_id: Some(task.manifest.task_id.clone()),
                execution_id: plan
                    .planning_execution_id
                    .clone()
                    .or_else(|| Some(task.manifest.task_id.clone())),
                agent_id: Some(task.manifest.agent_id.clone()),
                principal: Some(scope.principal().to_string()),
                workspace: Some(scope.workspace().to_string()),
                timestamp: chrono::Utc::now().timestamp_millis(),
            });
        }
    }

    /// Emit canonical `HitlResolved { outcome: "cancelled" }` for a
    /// pending V3 plan clarification that has been dropped from the
    /// next elicitation batch (the elicitor refined the question set).
    /// Without this, `pendingHitlStore` accumulates orphaned correlation
    /// keys across re-elicitation rounds.
    fn emit_v3_planning_clarification_cancelled(
        &self,
        scope: &ScopeRef,
        task: &TaskRecord,
        plan: &TaskPlanRecord,
        question_id: &str,
    ) {
        if let Some(broadcaster) = self.runtime_event_broadcaster.get() {
            // `emit` (not `emit_transport_only`) so the resolution is persisted
            // to `events.jsonl`. Otherwise backfill on a fresh `/attention` load
            // after the resolve shows the stale Requested row as still pending.
            broadcaster.emit(RuntimeTransportEvent::HitlResolved {
                correlation_id: question_id.to_string(),
                source: "clarification".to_string(),
                outcome: "cancelled".to_string(),
                decision: None,
                task_id: Some(task.manifest.task_id.clone()),
                execution_id: plan
                    .planning_execution_id
                    .clone()
                    .or_else(|| Some(task.manifest.task_id.clone())),
                agent_id: Some(task.manifest.agent_id.clone()),
                principal: Some(scope.principal().to_string()),
                workspace: Some(scope.workspace().to_string()),
                timestamp: chrono::Utc::now().timestamp_millis(),
            });
        }
    }

    /// A task reaching a terminal status makes any outstanding V3 plan
    /// clarification HITL moot. Resolve each (persisted canonical
    /// `HitlResolved { outcome: "cancelled" }`) and clear the plan's pending
    /// questions, so `pendingHitlStore` / the attention pill stop stranding an
    /// orphaned `hitl.requested` — cancelling a task previously emitted no
    /// resolve, leaving the pause pending forever. Best-effort + idempotent (no
    /// plan / no pending questions is a no-op), so it is safe on every terminal
    /// transition AND on a re-assert of a terminal status (how an already-
    /// cancelled task's stranded clarification is cleared: re-cancel it).
    async fn resolve_pending_clarifications_on_terminal(
        &self,
        scope: &ScopeRef,
        task: &TaskRecord,
    ) {
        let task_id = &task.manifest.task_id;
        let result: Result<Option<(TaskPlanRecord, Vec<String>)>, ArtifactV2Error> = async {
            let _guard = self.acquire_task_write_guard(scope, task_id).await?;
            self.task_writes.recover_task_writes(scope, task_id).await?;
            let mut plan = match self.get_task_plan(scope, task_id).await {
                Ok(plan) => plan,
                Err(ArtifactV2Error::TaskPlanNotFound(_)) => return Ok(None),
                Err(error) => return Err(error),
            };
            if plan.pending_questions.is_empty() {
                return Ok(None);
            }
            let question_ids = plan
                .pending_questions
                .iter()
                .map(|question| question.id.clone())
                .collect();
            plan.pending_questions.clear();
            plan.updated_at = now_rfc3339();
            let mut index = self.load_task_plan_index(scope, task_id).await?;
            index.updated_at = Some(plan.updated_at.clone());
            Self::upsert_task_plan_index_entry(&mut index, &plan);
            self.commit_task_plan_bundle_unlocked(scope, task_id, &plan, &index, None, None)
                .await?;
            Ok(Some((plan, question_ids)))
        }
        .await;
        match result {
            Ok(Some((plan, question_ids))) => {
                let id_refs: Vec<&str> = question_ids.iter().map(String::as_str).collect();
                if let Some(chain_id) =
                    planning_clarification_chain_id_from_ids(&plan.plan_id, &id_refs)
                {
                    self.emit_v3_planning_clarification_cancelled(scope, task, &plan, &chain_id);
                }
                for question_id in question_ids {
                    self.emit_v3_planning_clarification_cancelled(scope, task, &plan, &question_id);
                }
            },
            Ok(None) => {},
            Err(error) => {
                tracing::warn!(
                    task_id = %task_id,
                    error = %error,
                    "[ARTIFACT-V2] failed to persist terminal-task clarification resolution"
                );
            },
        }
    }

    // `emit_v3_planning_clarification_resolved` retired in Phase H8.2
    // (2026-05-12). The ask-loop's `submit_clarification` path emits
    // canonical `HitlResolved { source: "clarification" }` first
    // chronologically; the downstream V3-service observer emit
    // double-fired the same envelope for the same `correlation_id`.
    // `correlation_id == question_id` is all consumers need on resolve.

    fn emit_v3_planning_completed(
        &self,
        scope: &ScopeRef,
        task: &TaskRecord,
        plan: &TaskPlanRecord,
    ) {
        self.emit_planning_transport(RuntimeTransportEvent::V3PlanningCompleted {
            principal: scope.principal().to_string(),
            workspace: scope.workspace().to_string(),
            task_id: task.manifest.task_id.clone(),
            task_title: task.manifest.title.clone(),
            agent_id: task.manifest.agent_id.clone(),
            plan_id: plan.plan_id.clone(),
            ui_thread_id: task.manifest.ui_thread_id.clone(),
            timestamp: chrono::Utc::now().timestamp_millis(),
        });
    }

    fn emit_v3_planning_failed(
        &self,
        scope: &ScopeRef,
        task: &TaskRecord,
        plan: &TaskPlanRecord,
        error: &str,
    ) {
        self.emit_planning_transport(RuntimeTransportEvent::V3PlanningFailed {
            principal: scope.principal().to_string(),
            workspace: scope.workspace().to_string(),
            task_id: task.manifest.task_id.clone(),
            task_title: task.manifest.title.clone(),
            agent_id: task.manifest.agent_id.clone(),
            plan_id: plan.plan_id.clone(),
            ui_thread_id: task.manifest.ui_thread_id.clone(),
            error: error.to_string(),
            timestamp: chrono::Utc::now().timestamp_millis(),
        });
    }

    fn default_task_plan_index(task_id: &str) -> TaskPlanIndexRecord {
        TaskPlanIndexRecord {
            task_id: task_id.to_string(),
            latest_plan_id: None,
            approved_plan_id: None,
            plans: Vec::new(),
            updated_at: None,
        }
    }

    fn upsert_task_plan_index_entry(index: &mut TaskPlanIndexRecord, plan: &TaskPlanRecord) {
        if let Some(existing) = index
            .plans
            .iter_mut()
            .find(|entry| entry.plan_id == plan.plan_id)
        {
            existing.status = plan.status.clone();
            existing.updated_at = plan.updated_at.clone();
            return;
        }
        index.plans.push(TaskPlanIndexEntry {
            plan_id: plan.plan_id.clone(),
            status: plan.status.clone(),
            created_at: plan.created_at.clone(),
            updated_at: plan.updated_at.clone(),
        });
        index
            .plans
            .sort_by(|left, right| right.updated_at.cmp(&left.updated_at));
    }

    async fn load_task_plan_index(
        &self,
        scope: &ScopeRef,
        task_id: &str,
    ) -> Result<TaskPlanIndexRecord, ArtifactV2Error> {
        ArtifactV2Workspace::validate_task_id(task_id)?;
        let path =
            self.workspace
                .task_plan_index_path(&scope.principal(), &scope.workspace(), task_id);
        match self
            .workspace
            .read_json_path::<TaskPlanIndexRecord, _>(&path)
            .await
        {
            Ok(mut index) => {
                index.task_id = task_id.to_string();
                Ok(index)
            },
            Err(ArtifactV2Error::Io(err)) if err.kind() == std::io::ErrorKind::NotFound => {
                Ok(Self::default_task_plan_index(task_id))
            },
            Err(err) => Err(err),
        }
    }

    #[allow(dead_code)] // retained for focused fixtures and compatibility helpers
    async fn persist_task_plan_index(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        index: &TaskPlanIndexRecord,
    ) -> Result<(), ArtifactV2Error> {
        let path =
            self.workspace
                .task_plan_index_path(&scope.principal(), &scope.workspace(), task_id);
        self.workspace.write_json_atomic_path(&path, index).await
    }

