    async fn approved_plan_runtime_context(
        &self,
        scope: &ScopeRef,
        task: &TaskRecord,
        refinement: Option<&str>,
    ) -> Result<Option<ApprovedPlanRuntimeContext>, ArtifactV2Error> {
        let index = self
            .load_task_plan_index(scope, &task.manifest.task_id)
            .await?;
        let Some(plan_id) = index.approved_plan_id.as_deref() else {
            return Ok(None);
        };
        let Some(plan) = self
            .load_task_plan_record_optional(scope, &task.manifest.task_id, plan_id)
            .await?
        else {
            warn!(
                task_id = %task.manifest.task_id,
                plan_id,
                "[ARTIFACT-V2] Approved plan index points to a missing plan record; executing from task goal only"
            );
            return Ok(None);
        };
        if plan.status != TaskPlanStatus::Approved {
            warn!(
                task_id = %task.manifest.task_id,
                plan_id = %plan.plan_id,
                status = ?plan.status,
                "[ARTIFACT-V2] Approved plan index points to a non-approved plan; executing from task goal only"
            );
            return Ok(None);
        }
        let Some(plan_graph) = plan.plan_graph.as_ref() else {
            warn!(
                task_id = %task.manifest.task_id,
                plan_id = %plan.plan_id,
                "[ARTIFACT-V2] Approved plan has no PlanGraph; executing from task goal only"
            );
            return Ok(None);
        };

        let goal = task_goal_with_refinement(&task.manifest, refinement);
        let success_criteria = derive_plan_graph_success_criteria(plan_graph, &goal);
        let context = render_plan_graph_runtime_context(&goal, &success_criteria, plan_graph);
        Ok(Some(ApprovedPlanRuntimeContext {
            context,
            success_criteria,
        }))
    }

    #[allow(dead_code)] // retained for focused fixtures and compatibility helpers
    async fn persist_task_plan_record(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        plan: &TaskPlanRecord,
    ) -> Result<(), ArtifactV2Error> {
        let path = self.workspace.task_plan_record_path(
            &scope.principal(),
            &scope.workspace(),
            task_id,
            &plan.plan_id,
        );
        self.workspace.write_json_atomic_path(&path, plan).await
    }

    /// Commit every projection owned by one plan mutation through the existing
    /// recoverable per-task journal. The caller must hold the task write guard.
    async fn commit_task_plan_bundle_unlocked(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        plan: &TaskPlanRecord,
        index: &TaskPlanIndexRecord,
        versions: Option<&TaskPlanVersionsRecord>,
        task: Option<&TaskRecord>,
    ) -> Result<(), ArtifactV2Error> {
        ArtifactV2Workspace::validate_task_id(task_id)?;
        let recovery_catalog_entry = TaskPlanningRecoveryCatalogEntry {
            schema_version: 1,
            task_id: task_id.to_owned(),
        };
        let catalog_path = self.workspace.task_planning_recovery_catalog_entry_path(
            &scope.principal(),
            &scope.workspace(),
            task_id,
        );
        let planning_active = matches!(
            plan.status,
            TaskPlanStatus::Planning | TaskPlanStatus::Eliciting
        ) || (!plan.status.is_terminal()
            && plan.planning_recovery.as_ref().is_some_and(|receipt| {
                receipt
                    .resume_recoveries
                    .iter()
                    .any(|resume| !resume.settled)
            }));
        let mut writes = Vec::new();
        if planning_active {
            // Discovery lands first. If a crash follows, startup sees the
            // marker and replays/reads the exact plan; the reverse order could
            // commit `Planning` and die while the only authoritative catalog
            // entry was still absent.
            writes.push((
                catalog_path.clone(),
                serde_json::to_vec_pretty(&recovery_catalog_entry)?,
            ));
        }
        writes.extend([
            (
                self.workspace.task_plan_record_path(
                    &scope.principal(),
                    &scope.workspace(),
                    task_id,
                    &plan.plan_id,
                ),
                serde_json::to_vec_pretty(plan)?,
            ),
            (
                self.workspace.task_plan_index_path(
                    &scope.principal(),
                    &scope.workspace(),
                    task_id,
                ),
                serde_json::to_vec_pretty(index)?,
            ),
        ]);
        if let Some(versions) = versions {
            writes.push((
                self.workspace.task_plan_versions_path(
                    &scope.principal(),
                    &scope.workspace(),
                    task_id,
                ),
                serde_json::to_vec_pretty(versions)?,
            ));
        }
        // `task` is `Some` for seven of this function's nine callers, and
        // `fail_task_plan` among them writes the terminal `"failed"` status.
        // That makes this a task-record writer, not just a plan writer — the
        // reconciler sees the record paths in the write set and brings the
        // index and Today with it, and sees nothing to do when a caller
        // commits a plan alone.
        if let Some(task) = task {
            writes.extend([
                (
                    self.workspace.task_manifest_path(
                        &scope.principal(),
                        &scope.workspace(),
                        task_id,
                    ),
                    serde_json::to_vec_pretty(&task.manifest)?,
                ),
                (
                    self.workspace
                        .task_state_path(&scope.principal(), &scope.workspace(), task_id),
                    serde_json::to_vec_pretty(&task.state)?,
                ),
                (
                    self.workspace
                        .task_refs_path(&scope.principal(), &scope.workspace(), task_id),
                    serde_json::to_vec_pretty(&task.refs)?,
                ),
            ]);
        }
        self.task_writes
            .commit_task_writes(scope, task_id, &writes)
            .await?;
        if !planning_active {
            match self.workspace.remove_file_path(&catalog_path).await {
                Ok(()) => {},
                Err(ArtifactV2Error::Io(error)) if error.kind() == std::io::ErrorKind::NotFound => {
                },
                Err(error) => warn!(
                    task_id,
                    %error,
                    "stale planning recovery catalog marker retirement deferred"
                ),
            }
        }
        Ok(())
    }

