    /// Pin the execution's engine at launch. A pin already on disk stands — a
    /// re-prepared execution keeps the engine it first launched with —
    /// unless `named_engine` (a plane grant's engine) names another engine:
    /// the grant's choice is sealed authority and the pin must agree with it.
    async fn persist_execution_engine_pin(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        execution_id: &str,
        pin: &crate::magician_v2::execution::plane::RunEnginePin,
        named_engine: Option<&str>,
    ) -> Result<(), ArtifactV2Error> {
        let named_engine = named_engine
            .map(str::trim)
            .filter(|engine| !engine.is_empty());
        // Check-then-write under the task write guard, like every sibling
        // sidecar, so two launch paths racing on one execution (acceptance
        // and interrupted-launch recovery) cannot both see no pin and leave
        // the later writer's. No caller holds the guard here: each runs
        // right after a routing or attenuation write that takes it itself.
        let _task_guard = self.acquire_task_write_guard(scope, task_id).await?;
        let existing = self
            .load_execution_engine_pin(scope, task_id, execution_id)
            .await?;
        if existing
            .as_ref()
            .is_some_and(|existing| named_engine.is_none_or(|named| named == existing.engine))
        {
            return Ok(());
        }
        self.workspace
            .write_json_atomic_path(
                &self.execution_engine_pin_path(scope, task_id, execution_id),
                pin,
            )
            .await
    }

    /// The pin a task inherited from the chat turn or run that created it.
    /// Unreadable reads as absent: the pin is a preference, not authority.
    async fn load_task_launch_engine_pin(
        &self,
        scope: &ScopeRef,
        task_id: &str,
    ) -> Option<crate::magician_v2::execution::plane::RunEnginePin> {
        let path = self
            .workspace
            .task_dir(&scope.principal(), &scope.workspace(), task_id)
            .join(TASK_LAUNCH_ENGINE_PIN_FILE);
        match self
            .workspace
            .read_json_path::<crate::magician_v2::execution::plane::RunEnginePin, _>(&path)
            .await
        {
            Ok(pin) => Some(pin),
            Err(ArtifactV2Error::Io(error)) if error.kind() == std::io::ErrorKind::NotFound => None,
            Err(error) => {
                warn!(
                    task_id = %task_id,
                    error = %error,
                    "[ARTIFACT-V2] Task launch pin unreadable; the run takes the Settings engine"
                );
                None
            },
        }
    }

    /// Pin a run launched through the goal trigger (chat delegate, handover,
    /// sub-goal) as soon as its execution shell exists, from the launching
    /// pin on this task. Best effort: a failure leaves composition to pin the
    /// run, from Settings, and save that.
    pub async fn pin_launched_execution_engine(
        &self,
        principal: &str,
        workspace: &str,
        task_id: &str,
        execution_id: &str,
    ) {
        let scope = ScopeRef::system_internal_unauthenticated(principal, workspace);
        let pin = crate::magician_v2::execution::plane::resolve_launch_pin(None);
        if let Err(error) = self
            .persist_execution_engine_pin(&scope, task_id, execution_id, &pin, None)
            .await
        {
            warn!(
                task_id = %task_id,
                execution_id = %execution_id,
                error = %error,
                "[ARTIFACT-V2] Launched run's engine pin not saved; composition pins it from Settings"
            );
        }
    }

    /// Pin a delegated child to its parent's engine. The parent's durable pin
    /// is the source; a parent with none (launched before pins existed, or by
    /// a path that keeps none) passes the pin its run carries on this task,
    /// else Settings right now. A pin already on disk stands.
    pub async fn persist_inherited_execution_engine_pin(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        parent_execution_id: &str,
        child_execution_id: &str,
    ) -> Result<(), ArtifactV2Error> {
        let pin = match self
            .load_execution_engine_pin(scope, task_id, parent_execution_id)
            .await?
        {
            Some(pin) => pin,
            None => crate::magician_v2::execution::plane::resolve_launch_pin(None),
        };
        self.persist_execution_engine_pin(scope, task_id, child_execution_id, &pin, None)
            .await
    }

    /// The execution's launch pin, or `None` for one prepared before pins
    /// existed (it is pinned at composition instead).
    pub async fn load_execution_engine_pin(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        execution_id: &str,
    ) -> Result<Option<crate::magician_v2::execution::plane::RunEnginePin>, ArtifactV2Error> {
        let path = self.execution_engine_pin_path(scope, task_id, execution_id);
        match self
            .workspace
            .read_json_path::<crate::magician_v2::execution::plane::RunEnginePin, _>(&path)
            .await
        {
            Ok(pin) => Ok(Some(pin)),
            Err(ArtifactV2Error::Io(error)) if error.kind() == std::io::ErrorKind::NotFound => {
                Ok(None)
            },
            // The pin is a preference, not authority: an unreadable one must
            // not wedge resume or recovery. Reading it as absent re-pins the
            // run at composition, and the next launch write replaces it.
            Err(error @ (ArtifactV2Error::Serde(_) | ArtifactV2Error::InvalidRequest(_))) => {
                warn!(
                    task_id = %task_id,
                    execution_id = %execution_id,
                    error = %error,
                    "[ARTIFACT-V2] Engine pin unreadable; the run is re-pinned at composition"
                );
                Ok(None)
            },
            Err(error) => Err(error),
        }
    }

    async fn load_execution_explicit_delegation(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        execution_id: &str,
    ) -> Result<Option<String>, ArtifactV2Error> {
        let path = self.execution_explicit_delegation_path(scope, task_id, execution_id);
        match self.workspace.read_json_path::<Value, _>(&path).await {
            Ok(value) => Ok(value
                .get("target_agent_id")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(ToOwned::to_owned)),
            Err(ArtifactV2Error::Io(error)) if error.kind() == std::io::ErrorKind::NotFound => {
                Ok(None)
            },
            Err(error) => Err(error),
        }
    }

