    async fn seal_delegated_child_recovery_binding(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        execution_id: &str,
        binding: &crate::magician_v2::execution::agentic::delegation_dispatch::DelegatedChildRecoveryBinding,
    ) -> Result<DelegatedChildRecoveryIntegritySeal, ArtifactV2Error> {
        let workspace = self.workspace.clone();
        let principal = scope.principal().to_owned();
        let workspace_id = scope.workspace().to_owned();
        let task_id = task_id.to_owned();
        let execution_id = execution_id.to_owned();
        let binding = binding.clone();
        magician_core::blocking_admission::spawn_blocking_admitted(move || {
            Self::seal_delegated_child_recovery_binding_sync(
                &workspace,
                &principal,
                &workspace_id,
                &task_id,
                &execution_id,
                &binding,
            )
        })
        .await
        .map_err(|error| {
            ArtifactV2Error::Runtime(format!(
                "delegated child recovery seal worker failed to join: {error}"
            ))
        })?
    }

    fn seal_delegated_child_recovery_binding_sync(
        workspace: &ArtifactV2Workspace,
        principal: &str,
        workspace_id: &str,
        task_id: &str,
        execution_id: &str,
        binding: &crate::magician_v2::execution::agentic::delegation_dispatch::DelegatedChildRecoveryBinding,
    ) -> Result<DelegatedChildRecoveryIntegritySeal, ArtifactV2Error> {
        use crate::magician_v2::execution::agentic::delegation_dispatch::DELEGATED_CHILD_RECOVERY_BINDING_SCHEMA_VERSION;

        if binding.schema_version != DELEGATED_CHILD_RECOVERY_BINDING_SCHEMA_VERSION
            || binding.principal != principal
            || binding.workspace != workspace_id
            || binding.task_id != task_id
            || binding.execution_id != execution_id
            || binding.parent_execution_id.trim().is_empty()
            || binding.root_execution_id.trim().is_empty()
            || binding.source_agent_id.trim().is_empty()
            || binding.target_agent_id.trim().is_empty()
            || binding.source_definition_digest.trim().is_empty()
            || binding.target_definition_digest.trim().is_empty()
            || (binding.app_agent_tool && binding.ordinary_execution_goal.is_some())
            || (binding.app_agent_tool && binding.ordinary_child_title.is_some())
            || (binding.app_agent_tool && !binding.ordinary_expected_artifacts.is_empty())
            || (binding.app_agent_tool && !binding.ordinary_spend_token_ids.is_empty())
            || (!binding.app_agent_tool
                && (binding.ordinary_execution_goal.is_none()
                    || binding.ordinary_child_title.is_none()))
        {
            return Err(ArtifactV2Error::InvalidRequest(format!(
                "delegated_child_recovery_binding_invalid:{execution_id}"
            )));
        }
        let encoded = serde_json::to_vec(binding)?;
        if encoded.len() > DELEGATED_CHILD_RECOVERY_PAYLOAD_MAX_BYTES {
            return Err(ArtifactV2Error::InvalidRequest(format!(
                "delegated_child_recovery_binding_too_large:{execution_id}"
            )));
        }
        let proof = serde_json::to_vec(&(
            DELEGATED_CHILD_RECOVERY_SEAL_DOMAIN,
            DELEGATED_CHILD_RECOVERY_BINDING_SCHEMA_VERSION,
            principal,
            workspace_id,
            task_id,
            execution_id,
            binding,
        ))?;
        let llm_scope = magicllm::LlmScope::new(principal, workspace_id);
        let hmac_sha256 =
            crate::magician_v2::analytics::llm_trace_content::scoped_content_fingerprint(
                workspace, &llm_scope, &proof,
            )
            .map_err(|error| {
                ArtifactV2Error::Runtime(format!("delegated_child_recovery_seal_failed:{error}"))
            })?;
        let seal = DelegatedChildRecoveryIntegritySeal {
            schema_version: DELEGATED_CHILD_RECOVERY_BINDING_SCHEMA_VERSION,
            hmac_sha256,
            binding: binding.clone(),
        };
        if serde_json::to_vec(&seal)?.len() > DELEGATED_CHILD_RECOVERY_ENVELOPE_MAX_BYTES {
            return Err(ArtifactV2Error::InvalidRequest(format!(
                "delegated_child_recovery_envelope_too_large:{execution_id}"
            )));
        }
        Ok(seal)
    }

    /// Persist exact child composition before the first child model call.
    /// The protected copy is authoritative and is published first, so a crash
    /// can leave at most a missing diagnostic copy, never an unsealed runnable
    /// child.
    pub(crate) async fn persist_delegated_child_recovery_binding(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        execution_id: &str,
        binding: &crate::magician_v2::execution::agentic::delegation_dispatch::DelegatedChildRecoveryBinding,
    ) -> Result<(), ArtifactV2Error> {
        let execution = self.get_execution(scope, task_id, execution_id).await?;
        if execution.state.relationship_type != RELATIONSHIP_TYPE_DELEGATE
            || execution.state.parent_execution_id.as_deref()
                != Some(binding.parent_execution_id.as_str())
            || execution.state.root_execution_id.as_deref()
                != Some(binding.root_execution_id.as_str())
            || execution.state.agent_id != binding.target_agent_id
        {
            return Err(ArtifactV2Error::InvalidRequest(format!(
                "delegated_child_recovery_artifact_mismatch:{execution_id}"
            )));
        }
        let seal = self
            .seal_delegated_child_recovery_binding(scope, task_id, execution_id, binding)
            .await?;
        let _task_guard = self.acquire_task_write_guard(scope, task_id).await?;
        let seal_path = self.delegated_child_recovery_integrity_path(scope, task_id, execution_id);
        if let Some(parent) = seal_path.parent() {
            self.workspace.create_dir_all_path(parent).await?;
        }
        match self
            .workspace
            .read_json_bounded_stream_path::<DelegatedChildRecoveryIntegritySeal, _>(
                &seal_path,
                DELEGATED_CHILD_RECOVERY_ENVELOPE_MAX_BYTES as u64,
                64,
                DELEGATED_CHILD_RECOVERY_ENVELOPE_MAX_JSON_NODES,
            )
            .await
        {
            Ok(existing) if existing != seal => {
                return Err(ArtifactV2Error::InvalidRequest(format!(
                    "delegated_child_recovery_binding_conflict:{execution_id}"
                )));
            },
            Ok(_) => {},
            Err(ArtifactV2Error::Io(error)) if error.kind() == std::io::ErrorKind::NotFound => {
                self.workspace
                    .write_json_value_atomic_stream_path(
                        &seal_path,
                        seal.clone(),
                        DELEGATED_CHILD_RECOVERY_ENVELOPE_MAX_BYTES,
                    )
                    .await?;
            },
            Err(error) => return Err(error),
        }
        let public_path = self.delegated_child_recovery_binding_path(scope, task_id, execution_id);
        match self
            .workspace
            .read_json_bounded_stream_path::<
                crate::magician_v2::execution::agentic::delegation_dispatch::DelegatedChildRecoveryBinding,
                _,
            >(
                &public_path,
                DELEGATED_CHILD_RECOVERY_PAYLOAD_MAX_BYTES as u64,
                64,
                DELEGATED_CHILD_RECOVERY_MAX_JSON_NODES,
            )
            .await
        {
            Ok(existing) if existing != *binding => {
                return Err(ArtifactV2Error::InvalidRequest(format!(
                    "delegated_child_recovery_public_conflict:{execution_id}"
                )));
            },
            Ok(_) => {},
            Err(ArtifactV2Error::Io(error))
                if error.kind() == std::io::ErrorKind::NotFound =>
            {
                self.workspace
                    .write_json_value_atomic_stream_path(
                        &public_path,
                        binding.clone(),
                        DELEGATED_CHILD_RECOVERY_PAYLOAD_MAX_BYTES,
                    )
                    .await?;
            },
            Err(error) => return Err(error),
        }
        Ok(())
    }

    async fn load_delegated_child_recovery_binding(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        execution_id: &str,
    ) -> Result<Option<crate::magician_v2::execution::agentic::delegation_dispatch::DelegatedChildRecoveryBinding>, ArtifactV2Error>
    {
        let seal_path = self.delegated_child_recovery_integrity_path(scope, task_id, execution_id);
        let seal = match self
            .workspace
            .read_json_bounded_stream_path::<DelegatedChildRecoveryIntegritySeal, _>(
                &seal_path,
                DELEGATED_CHILD_RECOVERY_ENVELOPE_MAX_BYTES as u64,
                64,
                DELEGATED_CHILD_RECOVERY_ENVELOPE_MAX_JSON_NODES,
            )
            .await
        {
            Ok(seal) => seal,
            Err(ArtifactV2Error::Io(error)) if error.kind() == std::io::ErrorKind::NotFound => {
                return Ok(None)
            },
            Err(error) => return Err(error),
        };
        let expected = self
            .seal_delegated_child_recovery_binding(scope, task_id, execution_id, &seal.binding)
            .await?;
        if seal.schema_version != expected.schema_version
            || !constant_time_bytes_eq(seal.hmac_sha256.as_bytes(), expected.hmac_sha256.as_bytes())
        {
            return Err(ArtifactV2Error::InvalidRequest(format!(
                "delegated_child_recovery_seal_mismatch:{execution_id}"
            )));
        }
        let public_path = self.delegated_child_recovery_binding_path(scope, task_id, execution_id);
        match self
            .workspace
            .read_json_bounded_stream_path::<
                crate::magician_v2::execution::agentic::delegation_dispatch::DelegatedChildRecoveryBinding,
                _,
            >(
                &public_path,
                DELEGATED_CHILD_RECOVERY_PAYLOAD_MAX_BYTES as u64,
                64,
                DELEGATED_CHILD_RECOVERY_MAX_JSON_NODES,
            )
            .await
        {
            Ok(public) if public != seal.binding => {
                return Err(ArtifactV2Error::InvalidRequest(format!(
                    "delegated_child_recovery_public_copy_mismatch:{execution_id}"
                )));
            },
            Ok(_) => {},
            Err(ArtifactV2Error::Io(error))
                if error.kind() == std::io::ErrorKind::NotFound => {},
            Err(error) => return Err(error),
        }
        Ok(Some(seal.binding))
    }

