async fn grounded_task_user_fallback(
    dependencies: &SynthesisDependencies,
    bundle: &TaskUserOutputSynthesisBundle,
    review_predecessor: bool,
) -> Option<OutputDocument> {
    if review_predecessor {
        if let Some(predecessor) = task_user_predecessor_fallback_document(bundle) {
            match review_task_user_output_grounding(dependencies, bundle, &predecessor).await {
                Ok(Some(verdict)) if verdict.faithful => return Some(predecessor),
                Ok(Some(verdict)) if !verdict.faithful => {
                    warn!(
                        execution_id = %bundle.execution_state.execution_id,
                        reason = %verdict.reason,
                        "[ARTIFACT-V2] grounded fallback rejected synthesized predecessor; using verbatim direct evidence"
                    );
                },
                Ok(_) | Err(_) => {},
            }
        }
    }
    task_user_direct_evidence_fallback_document(bundle)
}

