    /// A behavior's reviewed operations are dispatched on the `app:` route
    /// BEFORE the workflow's own turn is handed back, and nothing between the
    /// two can put a reviewed operation on another route.
    ///
    /// Ordering is the structural defence, not exclusivity. By the time this
    /// function returns a turn, every step the recipe owed has already gone to
    /// `AppLlmOperationDispatcher` under the operator's live operation
    /// admission, and its output is durable and schema-checked — so there is no
    /// reviewed operation left for a later turn to take anywhere else. The turn
    /// that follows is the workflow's own, which a behavior-bound action still
    /// owes: its `may_mutate` rows and terminal commit have no recipe form.
    #[test]
    fn a_behavior_bound_turn_runs_its_reviewed_recipe_before_its_workflow_turn() {
        let source = include_str!("service.rs");
        let admission = source
            .split("    async fn admit_app_workflow_execution_context(")
            .nth(1)
            .and_then(|tail| {
                tail.split("    async fn dispatch_app_behavior_recipe_step(")
                    .next()
            })
            .expect("app workflow model admission source window");

        // Every admitted turn is built after the recipe fork, and only on the
        // two arms that owe one: the ordinary workflow with no recipe, and the
        // behavior whose recipe is finished.
        let fork = admission
            .find("input.recipe_admission()")
            .expect("the recipe admission decides what runs first");
        assert_eq!(
            admission.matches("AppWorkflowAdmittedModelTurn {").count(),
            2,
            "only the ordinary-workflow turn and the post-recipe turn may be built"
        );
        for construction in admission.match_indices("AppWorkflowAdmittedModelTurn {") {
            assert!(fork < construction.0);
        }

        // Every case of the fork is named. A wildcard here would let a
        // behavior-bound turn whose recipe is unfinished fall through to the
        // ordinary-workflow arm and take a reviewed operation onto the generic
        // lane — which is the one thing the ordering above exists to prevent.
        for arm in [
            "AppRecipeAdmission::NotBehaviorBound =>",
            "AppRecipeAdmission::Complete =>",
            "AppRecipeAdmission::Step(step) =>",
        ] {
            assert!(admission.contains(arm), "unhandled recipe admission: {arm}");
        }
        // The step is dispatched only from the arm that carries one.
        let dispatched = admission
            .find(".dispatch_app_behavior_recipe_step(")
            .expect("reviewed steps are dispatched on the app: route");
        let step_arm = admission
            .find("AppRecipeAdmission::Step(step) =>")
            .expect("the step arm must remain present");
        assert!(step_arm < dispatched);

        // A step's output is durable before the next admission reads it, so a
        // recipe that stops part-way cannot be replayed from the top.
        assert!(admission.contains("record_recipe_step_output"));
        // Settling an execution is the executor's job and is gated on a durable
        // terminal result. Admission must not be able to report an outcome.
        assert!(!admission.contains("ExecutionOutcomeSnapshot"));

        // The run's token ceiling is not a local of this frame. The frame is
        // rebuilt from nothing whenever an interrupted run is continued, so a
        // budget seeded here would be handed back in full to every
        // continuation — the reviewed per-run ceiling would be enforced per
        // continuation instead. The ceiling arrives on the admitted step, and
        // each step's spend goes back into durable progress.
        assert!(!admission.contains("let mut remaining_output_tokens"));
        assert!(admission.contains("spent_output_tokens,"));

        let dispatch = source
            .split("    async fn dispatch_app_behavior_recipe_step(")
            .nth(1)
            .and_then(|tail| {
                tail.split("    pub(crate) async fn admit_app_agent_tool_child_execution_context(")
                    .next()
            })
            .expect("behavior step dispatch source window");
        assert!(dispatch.contains("resolve_recipe_step_operation"));
        assert!(dispatch.contains("AppLlmDispatchBudget::from_behavior_authority"));
        assert!(dispatch.contains("step.remaining_output_tokens()"));
        assert!(dispatch.contains("step.verified_manifest()"));
        // No fallback: an unwired config authority, an unadmitted operation or
        // a denied dispatch all end in a refusal.
        assert!(dispatch.contains("AppWorkflowError::ProcessingContextUnavailable"));
        assert!(!dispatch.contains("execute_agentic_direct_with_outcome"));

        // Both executor entry points run the returned turn under the app
        // disclosure guard. That guard pins one attested profile and transport
        // cohort, so the workflow turn following a recipe is on the same
        // route-checked app context an ordinary app workflow runs on — the one
        // thing that must never become an unpinned core call.
        for (start, end) in [
            (
                "async fn execute_task_with_orchestrator",
                "async fn admit_app_workflow_execution_context",
            ),
            (
                "async fn continue_execution_with_orchestrator",
                "async fn verification_hold_decision",
            ),
        ] {
            let body = source
                .split(start)
                .nth(1)
                .and_then(|tail| tail.split(end).next())
                .expect("orchestrator execution source window");
            let admitted = body
                .find("Ok(Some(AppWorkflowAdmittedModelTurn {")
                .expect("admitted app workflow turn arm");
            let guarded = body[admitted..]
                .find("overrides.app_disclosure_guard = Some(disclosure_guard);")
                .expect("the admitted turn runs under its own disclosure guard");
            let goal = body[admitted..]
                .find("execution_goal = admitted_goal;")
                .expect("the admitted turn supplies the goal");
            assert!(goal < guarded);
        }
    }

    /// A behavior-bound run continued after its recipe already finished still
    /// reaches its workflow turn.
    ///
    /// The hole this pins shut: the workflow's own turn was a local of the
    /// admission frame, minted only while a step was being dispatched. That
    /// frame is rebuilt from nothing whenever an interrupted run is continued,
    /// so a run that paused — an approval, a tool-result hold — re-entered
    /// admission empty, found every step already recorded in durable progress,
    /// and had no turn to hand back. Admission refused, the executor's `Err`
    /// arm wrote a cleanup marker and failed the run, and the result was the
    /// worst shape available: the recipe's reviewed outputs durable and paid
    /// for, the behavior's `may_mutate` rows and terminal result never written,
    /// and every retry taking the same branch.
    ///
    /// The turn is re-admitted from the same durable recipe state instead, so
    /// the segment that dispatches the last step and a later continuation that
    /// finds the recipe already complete reach it by exactly one route.
    #[test]
    fn a_continued_behavior_run_still_reaches_its_workflow_turn() {
        let source = include_str!("service.rs");
        let admission = source
            .split("    async fn admit_app_workflow_execution_context(")
            .nth(1)
            .and_then(|tail| {
                tail.split("    async fn dispatch_app_behavior_recipe_step(")
                    .next()
            })
            .expect("app workflow model admission source window");

        // Nothing about the workflow's turn may survive in this frame: what is
        // held here is exactly what a pause loses.
        assert!(
            !admission.contains("admitted_continuation"),
            "the workflow turn must be re-admitted, not carried across steps"
        );
        // A finished recipe is a case of the fork now, never a refusal.
        assert!(
            !admission.contains("BackgroundBehaviorRecipeComplete"),
            "a completed recipe must not refuse the workflow turn it still owes"
        );

        let complete = admission
            .split("AppRecipeAdmission::Complete =>")
            .nth(1)
            .and_then(|tail| tail.split("AppRecipeAdmission::Step(").next())
            .expect("the completed-recipe arm must remain present");
        assert!(complete.contains("return Ok(Some(AppWorkflowAdmittedModelTurn {"));
        // Whether the last step landed in THIS segment or an earlier one is not
        // a property of the recipe. Gating the turn on the frame's own counter
        // is the same bug in a new shape.
        assert!(
            !complete.contains("steps_dispatched ==") && !complete.contains("steps_dispatched >"),
            "a recipe completed in an earlier segment is still a completed recipe"
        );

        // Why the refusal had to stop being the answer rather than the failure
        // being softened: both executor entry points still turn an admission
        // error into an abandoned execution.
        for (start, end) in [
            (
                "async fn execute_task_with_orchestrator",
                "async fn admit_app_workflow_execution_context",
            ),
            (
                "async fn continue_execution_with_orchestrator",
                "async fn verification_hold_decision",
            ),
        ] {
            let body = source
                .split(start)
                .nth(1)
                .and_then(|tail| tail.split(end).next())
                .expect("orchestrator execution source window");
            assert!(body.contains("abandon_resource_execution"));
        }
    }

    /// A behavior's recipe cannot settle an execution by itself.
    ///
    /// Reviewed model turns are not a commit: a behavior whose recipe ran but
    /// whose workflow never wrote a terminal result has done half its job, and
    /// reporting that as a completion is the silent failure. The helper that
    /// once turned a finished recipe straight into a terminal outcome is gone,
    /// and this pins the door shut — the only completion a behavior can reach
    /// now is the executor's, behind the durable `require_terminal_result`
    /// gate that every canonical app workflow passes.
    #[test]
    fn a_behavior_recipe_cannot_settle_an_execution_on_its_own() {
        let source = include_str!("service.rs");
        // Split literals: this oracle reads its own file, so spelling either
        // name in one piece would make the assertion find itself.
        assert!(
            !source.contains(concat!("fn settle_app_behavior_", "recipe_execution")),
            "a finished recipe must not have its own terminal settlement path"
        );
        assert!(
            !source.contains(concat!("fn app_behavior_", "recipe_completed")),
            "a finished recipe must not have its own completion projection"
        );

        for (start, end) in [
            (
                "async fn execute_task_with_orchestrator",
                "async fn admit_app_workflow_execution_context",
            ),
            (
                "async fn continue_execution_with_orchestrator",
                "async fn verification_hold_decision",
            ),
        ] {
            let body = source
                .split(start)
                .nth(1)
                .and_then(|tail| tail.split(end).next())
                .expect("orchestrator execution source window");
            // The one early completion an app execution may report is a replay
            // of a result that is already committed. Everything else reaches
            // the terminal-result gate at the end of the executor.
            assert_eq!(
                body.matches("ExecutionOutcomeSnapshot::completed_app_result()")
                    .count(),
                1,
                "only the already-committed replay may short-circuit to completed"
            );
            let gate = body
                .find("require_terminal_result")
                .expect("durable terminal result gate");
            let condition = body[..gate]
                .rfind("if is_app_workflow")
                .expect("canonical app workflow classification");
            assert!(condition < gate);
        }
    }

    /// The behavior LLM lane charges its causation budget at the ROOT depth,
    /// and nothing on the dispatch path proves that: the fire row's recorded
    /// depth is never read back, so the value is a constant standing in for two
    /// invariants held elsewhere. This oracle is those invariants.
    ///
    /// If either moves — a background-origin terminal becomes projectable, or
    /// the fire writer stops recording a literal 0 — a behavior fired deep in a
    /// chain would dispatch its model turn as if it were a root fire, and the
    /// grant's reviewed `max_causation_depth` would bound nothing at all.
    /// Failing here is the instruction to carry the recorded depth into
    /// `dispatch_app_behavior_recipe_step` instead of assuming it.
    #[test]
    fn behavior_model_turns_are_root_fires_until_multi_hop_is_wired() {
        let events = include_str!("../apps/event_behaviors.rs");

        // Premise 1: a behavior's own completion cannot become a canonical
        // event, so no fire can descend from another fire.
        let refusal = events
            .find("if background_origin {")
            .expect("background-origin terminals are refused");
        assert!(
            events[refusal..]
                .split('}')
                .next()
                .unwrap_or_default()
                .contains("InvalidCanonicalEvent"),
            "background-origin canonical terminals must still fail closed"
        );

        // Premise 2: the sole writer of a fire row writes the depth as a
        // literal, not as a bound parameter some caller supplies.
        let insert = events
            .split("INSERT OR IGNORE INTO app_event_behavior_fires (")
            .nth(1)
            .expect("the event-behavior fire writer");
        let (columns, values) = insert
            .split_once(") VALUES (")
            .expect("fire insert column and value lists");
        let depth_column = columns
            .split(',')
            .position(|column| column.trim() == "causation_depth")
            .expect("fires record a causation depth");
        let written = values
            .split(')')
            .next()
            .expect("fire insert value list")
            .split(',')
            .nth(depth_column)
            .map(str::trim);
        assert_eq!(
            written,
            Some("0"),
            "app_event_behavior_fires must still record a literal root depth"
        );

        // ...and no other site in the event lane reads or writes the column.
        // `max_causation_depth` is the reviewed ceiling, a different value, so
        // its mentions are discounted.
        let depth_mentions = events.matches("causation_depth").count()
            - events.matches("max_causation_depth").count();
        assert_eq!(
            depth_mentions, 1,
            "a new causation_depth reader or writer means the dispatch budget must carry it"
        );

        // The dispatch site keeps the assumption named rather than inlining a
        // bare literal, so grepping the constant finds every site that must
        // change when the depth becomes real.
        let source = include_str!("service.rs");
        let dispatch = source
            .split("    async fn dispatch_app_behavior_recipe_step(")
            .nth(1)
            .and_then(|tail| {
                tail.split("    pub(crate) async fn admit_app_agent_tool_child_execution_context(")
                    .next()
            })
            .expect("behavior step dispatch source window");
        assert!(dispatch.contains("const BEHAVIOR_ROOT_CAUSATION_DEPTH: u16 = 0;"));
        let budget_call = dispatch
            .split("AppLlmDispatchBudget::from_behavior_authority(")
            .nth(1)
            .expect("behavior dispatch budget call");
        assert!(
            budget_call
                .split(')')
                .next()
                .unwrap_or_default()
                .contains("BEHAVIOR_ROOT_CAUSATION_DEPTH"),
            "the causal depth this lane charges must stay named, not inlined"
        );
    }

    #[test]
    fn budget_outcome_snapshot_preserves_resumable_and_terminal_variants() {
        use crate::magician_v2::execution::agentic::{
            AgenticPauseState, BudgetDimension, EnvironmentState,
        };

        let pause_state = AgenticPauseState::new(
            3,
            "finish the task",
            "produce the result",
            EnvironmentState::Uninitialized,
            "partial progress",
            8,
            3,
        );
        let resumable = AgenticOutcome::BudgetExhausted {
            dimension: BudgetDimension::Tokens {
                used: 1_000,
                limit: 1_000,
            },
            last_state: EnvironmentState::Uninitialized,
            iterations_completed: 3,
            actions_completed: 2,
            pause_state: Some(pause_state),
        };
        let resumable_snapshot = ExecutionOutcomeSnapshot::from_agentic_outcome(&resumable);
        assert_eq!(
            resumable_snapshot.execution_status,
            "max_iterations_reached"
        );
        assert_eq!(resumable_snapshot.task_status, "paused");
        assert_eq!(resumable_snapshot.outcome_type, "budget_exhausted");
        assert!(!resumable_snapshot.is_terminal);

        let terminal = AgenticOutcome::BudgetExhausted {
            dimension: BudgetDimension::Tokens {
                used: 1_000,
                limit: 1_000,
            },
            last_state: EnvironmentState::Uninitialized,
            iterations_completed: 3,
            actions_completed: 2,
            pause_state: None,
        };
        let terminal_snapshot = ExecutionOutcomeSnapshot::from_agentic_outcome(&terminal);
        assert_eq!(terminal_snapshot.execution_status, "failed");
        assert_eq!(terminal_snapshot.task_status, "failed");
        assert_eq!(terminal_snapshot.outcome_type, "budget_exhausted");
        assert!(terminal_snapshot.is_terminal);
    }

