    #[tokio::test]
    async fn stateless_children_handoff_is_bounded_and_exact_identity_sealed() {
        let tmp = tempfile::tempdir().expect("temporary Artifact workspace");
        let service = crate::magician_v2::test_support::build_test_artifact_v2_service(tmp.path());
        let scope = ScopeRef::system_internal_unauthenticated("principal", "workspace");
        let task_id = "task-1";
        let parent_execution_id = "parent-1";
        let path = service.stateless_children_handoff_descriptor_path(
            &scope,
            task_id,
            parent_execution_id,
        );
        service
            .workspace
            .create_dir_all_path(path.parent().expect("handoff parent"))
            .await
            .expect("create handoff directory");
        let descriptor = ExecutionStatelessChildrenHandoff {
            schema_version: EXECUTION_STATELESS_CHILDREN_HANDOFF_SCHEMA_VERSION,
            principal: scope.principal().to_owned(),
            workspace: scope.workspace().to_owned(),
            task_id: task_id.to_owned(),
            parent_execution_id: parent_execution_id.to_owned(),
            source: crate::magician_v2::execution::agentic::run_loop::store::ExecutionKey::new(
                scope.principal(),
                scope.workspace(),
                "parent-1-segment-1",
            )
            .expect("source key"),
            resumes_as: "parent-1-segment-2".to_owned(),
            expected_child_execution_ids: vec!["child-1".to_owned(), "child-2".to_owned()],
            wake_token: Some("children:child-1,child-2".to_owned()),
            resolution_id: Some("delegation-ready:proof".to_owned()),
        };
        service
            .save_stateless_children_handoff_descriptor(
                &scope,
                task_id,
                parent_execution_id,
                &path,
                &descriptor,
            )
            .await
            .expect("save sealed handoff");
        assert_eq!(
            service
                .load_stateless_children_handoff_descriptor(&scope, task_id, parent_execution_id,)
                .await
                .expect("load sealed handoff"),
            Some(descriptor.clone())
        );

        let valid_seal = service
            .seal_stateless_children_handoff_descriptor(
                &scope,
                task_id,
                parent_execution_id,
                &descriptor,
            )
            .expect("seal handoff");
        let mut tampered = valid_seal.clone();
        tampered.descriptor.resumes_as = "attacker-selected-segment".to_owned();
        service
            .workspace
            .write_json_value_atomic_stream_path(
                &path,
                tampered,
                EXECUTION_STATELESS_CHILDREN_HANDOFF_MAX_BYTES,
            )
            .await
            .expect("write tampered handoff fixture");
        assert!(service
            .load_stateless_children_handoff_descriptor(&scope, task_id, parent_execution_id,)
            .await
            .is_err());

        let copied_path =
            service.stateless_children_handoff_descriptor_path(&scope, task_id, "parent-2");
        service
            .workspace
            .create_dir_all_path(copied_path.parent().expect("copied handoff parent"))
            .await
            .expect("create copied handoff directory");
        service
            .workspace
            .write_json_value_atomic_stream_path(
                &copied_path,
                valid_seal,
                EXECUTION_STATELESS_CHILDREN_HANDOFF_MAX_BYTES,
            )
            .await
            .expect("copy valid envelope to wrong execution");
        assert!(service
            .load_stateless_children_handoff_descriptor(&scope, task_id, "parent-2")
            .await
            .is_err());

        let mut oversized_roster = descriptor.clone();
        oversized_roster.expected_child_execution_ids = (0
            ..=EXECUTION_STATELESS_CHILDREN_HANDOFF_MAX_CHILDREN)
            .map(|index| format!("child-{index:03}"))
            .collect();
        assert!(service
            .seal_stateless_children_handoff_descriptor(
                &scope,
                task_id,
                parent_execution_id,
                &oversized_roster,
            )
            .is_err());

        let mut duplicate_roster = descriptor.clone();
        duplicate_roster.expected_child_execution_ids =
            vec!["child-1".to_owned(), "child-1".to_owned()];
        assert!(service
            .seal_stateless_children_handoff_descriptor(
                &scope,
                task_id,
                parent_execution_id,
                &duplicate_roster,
            )
            .is_err());

        service
            .workspace
            .write_string_atomic_path(
                &path,
                &" ".repeat(EXECUTION_STATELESS_CHILDREN_HANDOFF_MAX_BYTES + 1),
            )
            .await
            .expect("write oversized handoff fixture");
        assert!(service
            .load_stateless_children_handoff_descriptor(&scope, task_id, parent_execution_id,)
            .await
            .is_err());
    }

