    #[test]
    fn placement_retry_authority_is_checked_against_claimed_queue_before_activation() {
        let source = include_str!("service.rs");
        let retry = source
            .split("pub async fn retry_exact_sleeping_execution")
            .nth(1)
            .and_then(|tail| {
                tail.split("async fn persist_runtime_execution_outcome")
                    .next()
            })
            .expect("exact retry body");
        let body_hmac = retry
            .find("exact_placement_retry_checkpoint_body_matches")
            .expect("sealed placement body validation");
        let queue_generation = retry
            .find("execution_retry_wake(principal, workspace, task_id, execution_id)")
            .expect("current queue generation validation");
        let claimed_lease = retry
            .find("current_wake.wake_at != execution_retry_claimed_until")
            .expect("exact delivery lease validation");
        let claimed = retry
            .find("execution_retry_claim_attempt == 0")
            .expect("durable claim admission check");
        let terminal_debt = retry
            .find("A started exact retry deliberately retains its queue row")
            .expect("terminal queue-debt settlement");
        let activation = retry
            .find("activate_sleeping_root_execution")
            .expect("Artifact root activation");
        assert!(queue_generation < terminal_debt);
        assert!(queue_generation < claimed_lease && claimed_lease < terminal_debt);
        assert!(claimed < terminal_debt);
        assert!(terminal_debt < body_hmac);
        assert!(body_hmac < activation);
        assert!(queue_generation < activation);
        assert!(claimed < activation);
    }

    #[test]
    fn exact_artifact_activation_is_generation_fenced_but_lifecycle_reentry_is_not_self_locked() {
        let source = include_str!("service.rs");
        let retry = source
            .split("pub async fn retry_exact_sleeping_execution")
            .nth(1)
            .and_then(|tail| {
                tail.split("async fn persist_runtime_execution_outcome")
                    .next()
            })
            .expect("exact retry body");
        let activation_fence = retry
            .find("let activation_generation_guard = queue")
            .expect("activation reacquires exact generation fence");
        let revalidation = retry[activation_fence..]
            .find("execution_retry_claim_is_current")
            .map(|offset| activation_fence + offset)
            .expect("activation revalidates claimed_until under the fence");
        let child_activation = retry[revalidation..]
            .find("self.activate_sleeping_child_execution")
            .map(|offset| revalidation + offset)
            .expect("child Artifact activation");
        let root_activation = retry[revalidation..]
            .find("self.activate_sleeping_root_execution")
            .map(|offset| revalidation + offset)
            .expect("root Artifact activation");
        let release = retry[root_activation..]
            .find("drop(activation_generation_guard)")
            .map(|offset| root_activation + offset)
            .expect("activation fence release");
        let lifecycle_reentry = retry[release..]
            .find("let recovery =")
            .map(|offset| release + offset)
            .expect("lifecycle reentry");
        assert!(activation_fence < revalidation);
        assert!(revalidation < child_activation);
        assert!(revalidation < root_activation);
        assert!(child_activation < release && root_activation < release);
        assert!(release < lifecycle_reentry);
    }

    #[test]
    fn sleeping_projection_crash_repair_is_fenced_against_peer_runtime_admission() {
        let source = include_str!("service.rs");
        let retry = source
            .split("pub async fn retry_exact_sleeping_execution")
            .nth(1)
            .and_then(|tail| {
                tail.split("async fn persist_runtime_execution_outcome")
                    .next()
            })
            .expect("exact retry body");
        let convergence = retry
            .find("if !sleeping_projection && sleeping_runtime")
            .expect("Sleeping projection convergence");
        let generation_fence = retry[convergence..]
            .find("let sleeping_projection_generation_guard = queue")
            .map(|offset| convergence + offset)
            .expect("Sleeping projection generation fence");
        let revalidation = retry[generation_fence..]
            .find("execution_retry_claim_is_current")
            .map(|offset| generation_fence + offset)
            .expect("Sleeping projection claim revalidation");
        let projection = retry[revalidation..]
            .find("self.persist_runtime_execution_outcome")
            .map(|offset| revalidation + offset)
            .expect("runtime-to-Artifact convergence write");
        let release = retry[projection..]
            .find("drop(sleeping_projection_generation_guard)")
            .map(|offset| projection + offset)
            .expect("Sleeping projection generation release");
        assert!(convergence < generation_fence);
        assert!(generation_fence < revalidation);
        assert!(revalidation < projection);
        assert!(projection < release);
    }

