    #[test]
    fn startup_exact_retry_preserves_hydrated_runnable_timer_ownership() {
        for state in [
            WaitingState::Runnable,
            WaitingState::Executing,
            WaitingState::Sleeping,
        ] {
            assert!(
                exact_retry_runtime_state_is_startup_timer_owned(&state),
                "{state:?} may be the runtime half of an exact sealed placement timer"
            );
        }
        for state in [
            WaitingState::WaitingUser,
            WaitingState::WaitingChildren,
            WaitingState::Paused,
            WaitingState::Completed,
            WaitingState::Failed,
            WaitingState::Cancelled,
        ] {
            assert!(
                !exact_retry_runtime_state_is_startup_timer_owned(&state),
                "{state:?} must not be reopened by placement recovery"
            );
        }

        let source = include_str!("service.rs");
        let retry = source
            .split("pub async fn retry_exact_sleeping_execution")
            .nth(1)
            .and_then(|tail| {
                tail.split("async fn persist_runtime_execution_outcome")
                    .next()
            })
            .expect("exact retry body");
        let runnable_recovery = retry
            .find("WaitingState::Runnable")
            .expect("hydrated Runnable recovery branch");
        let durable_owner = retry[runnable_recovery..]
            .find("exact_retry_durable_owner_until")
            .expect("cross-process durable owner fence");
        let sleeping_cas = retry[runnable_recovery..]
            .find("restore_orphaned_exact_retry_to_sleeping")
            .expect("timer-owned status restoration");
        assert!(durable_owner < sleeping_cas);
        assert!(retry.contains("conversation_store()"));
        assert!(retry.contains("V2StorageError::ExecutionNotFound"));
        assert!(!retry.contains("get_execution(execution_id).await.ok()"));

        let startup = source
            .split("async fn ensure_exact_placement_retry_wake_for_startup")
            .nth(1)
            .and_then(|tail| {
                tail.split("async fn exact_retry_durable_owner_until")
                    .next()
            })
            .expect("startup exact retry helper");
        assert!(startup.contains("exact_retry_runtime_state_is_startup_timer_owned"));
        assert!(startup.contains("ensure_execution_retry_wake_for_segment"));
        assert!(startup.contains("conversation_store()"));
        assert!(startup.contains("V2StorageError::ExecutionNotFound"));
        assert!(!startup.contains("Err(_) => return Ok(false)"));

        let attached = source
            .split("async fn attached_child_exact_sleeping_recovery_is_owned")
            .nth(1)
            .and_then(|tail| {
                tail.split("async fn ensure_exact_placement_retry_wake_for_startup")
                    .next()
            })
            .expect("Attached-child timer recovery helper");
        assert!(attached.contains("exact_retry_runtime_state_is_startup_timer_owned"));
        assert!(attached.contains("ensure_execution_retry_wake_for_segment"));
        assert!(attached.contains("conversation_store()"));
        assert!(attached.contains("V2StorageError::ExecutionNotFound"));
        assert!(!attached.contains("Err(_) => return Ok(false)"));

        let canonical_recovery = source
            .split("pub(crate) async fn recover_interrupted_runtime_execution")
            .nth(1)
            .and_then(|tail| {
                tail.split("pub(crate) async fn wait_for_interrupted_runtime_recoveries")
                    .next()
            })
            .expect("canonical interrupted-runtime recovery");
        let timer_owner = canonical_recovery
            .find("ensure_exact_placement_retry_wake_for_startup")
            .expect("exact timer admission fence");
        let generic_composition = canonical_recovery
            .rfind("binding_for_existing_execution")
            .expect("generic Artifact composition");
        assert!(canonical_recovery.contains("if !exact_sleep_retry"));
        assert!(timer_owner < generic_composition);
        assert!(canonical_recovery.contains("exact_placement_retry_owned_by_timer"));

        let pipeline_binding = canonical_recovery
            .find("pipeline_continuation_binding_by_execution_id")
            .expect("durable pipeline recovery gate");
        let pipeline_reconciliation = canonical_recovery[..pipeline_binding]
            .find("acquire_resumable_pause_lifecycle_admission_scoped")
            .expect("pipeline terminal-preparation reconciliation");
        let committed_stage_probe = canonical_recovery[pipeline_binding..]
            .find("committed_pipeline_segment_terminal")
            .map(|offset| pipeline_binding + offset)
            .expect("committed pipeline stage probe");
        assert!(pipeline_reconciliation < pipeline_binding);
        assert!(pipeline_binding < committed_stage_probe);
    }

