    /// The launch-ready seal must accept the record the runtime projection
    /// actually writes, not a hand-typed fixture.
    ///
    /// This is the regression that shipped: the guard compared
    /// `relationship_type` against a spelling `execution_record_from_runtime`
    /// never produces, so the seal rejected every real delegated child and
    /// delegation failed at launch with
    /// `delegated_child_recovery_artifact_mismatch`. Nothing caught it because
    /// the only coverage asserted the *call ordering of string literals* in
    /// this file's source text — that the seal is invoked in the right place,
    /// never that it succeeds. So build the child the way the runtime does and
    /// seal it for real.
    #[tokio::test]
    async fn launch_ready_seal_accepts_the_child_the_runtime_projection_writes() {
        use crate::magician_v2::execution::agentic::delegation_dispatch::{
            DelegatedChildRecoveryBinding, DELEGATED_CHILD_RECOVERY_BINDING_SCHEMA_VERSION,
        };

        let tmp = tempfile::TempDir::new().expect("temp dir");
        let service = build_test_artifact_v2_service(tmp.path());
        let scope = ScopeRef::system_internal_unauthenticated(
            &"anonymous".to_string(),
            &"default".to_string(),
        );
        let mut task = sample_task_record();
        let task_id = task.manifest.task_id.clone();
        task.state.active_root_execution_id = Some("exec-parent".to_string());
        task.state.latest_root_execution_id = Some("exec-parent".to_string());
        service
            .reducer
            .reduce_task_created(&task)
            .await
            .expect("persist task");

        let runtime_child = ExecutionRun {
            id: "exec-deleg-projected".to_string(),
            principal: "anonymous".to_string(),
            workspace: "default".to_string(),
            task_id: Some(task_id.clone()),
            root_execution_id: Some("exec-parent".to_string()),
            title: Some("Projected delegated child".to_string()),
            waiting_state: WaitingState::Runnable,
            created_at: Utc::now().timestamp_millis(),
            updated_at: Utc::now().timestamp_millis(),
            processing_correlation_id: None,
            current_stage: None,
            current_provider: None,
            escalation_trigger: None,
            parent_execution_id: Some("exec-parent".to_string()),
            child_execution_ids: Vec::new(),
            active_owner_agent_id: "web-researcher".to_string(),
            owner_stack: Vec::new(),
            active_delegation_group: Vec::new(),
            timeout_secs: None,
            delegation_chain: Vec::new(),
            work_authority: None,
            paused_from_state: None,
            entry_mode: crate::magician_v2::storage::models::ExecutionEntryMode::Direct,
        };

        // A child is exactly "a run with a parent", and the projection is the
        // only writer of the vocabulary the guards read back.
        let child = execution_record_from_runtime(&task_id, &runtime_child, None);
        assert_eq!(
            child.state.relationship_type, RELATIONSHIP_TYPE_DELEGATE,
            "the projection is the sole writer; every lineage guard reads this back"
        );

        let mut runtime_root = runtime_child.clone();
        runtime_root.id = "exec-parent".to_string();
        runtime_root.parent_execution_id = None;
        assert_eq!(
            execution_record_from_runtime(&task_id, &runtime_root, None)
                .state
                .relationship_type,
            RELATIONSHIP_TYPE_ROOT
        );

        service
            .reducer
            .reduce_execution_discovered(&scope, &child)
            .await
            .expect("persist projected child");

        let binding = DelegatedChildRecoveryBinding {
            schema_version: DELEGATED_CHILD_RECOVERY_BINDING_SCHEMA_VERSION,
            principal: "anonymous".to_owned(),
            workspace: "default".to_owned(),
            task_id: task_id.clone(),
            execution_id: child.state.execution_id.clone(),
            parent_execution_id: "exec-parent".to_owned(),
            root_execution_id: "exec-parent".to_owned(),
            source_agent_id: "personal-assistant".to_owned(),
            source_definition_digest: "source-digest".to_owned(),
            target_agent_id: "web-researcher".to_owned(),
            target_definition_digest: "target-digest".to_owned(),
            ordinary_execution_goal: Some("compare official release dates".to_owned()),
            ordinary_child_title: Some("Projected delegated child".to_owned()),
            ordinary_expected_artifacts: Vec::new(),
            ordinary_spend_token_ids: Vec::new(),
            work_budget_secs: None,
            work_authority: None,
            llm_routing_overrides: None,
            app_agent_tool: false,
        };

        service
            .persist_delegated_child_recovery_binding(
                &scope,
                &task_id,
                &child.state.execution_id,
                &binding,
            )
            .await
            .expect("a child built by the runtime projection must seal at launch");
    }

