    #[test]
    fn stateless_handoff_refreshes_peer_checkpoint_under_execution_then_descriptor_fences() {
        let source = include_str!("service.rs");
        let prepare = source
            .split("async fn prepare_stateless_children_handoff(")
            .nth(1)
            .and_then(|tail| {
                tail.split("async fn consume_stateless_children_handoff")
                    .next()
            })
            .expect("stateless handoff preparer");
        let execution_fence = prepare
            .find("acquire_stateless_execution_lifecycle_exclusion_scoped")
            .expect("parent execution lifecycle fence");
        let descriptor_fence = prepare[execution_fence..]
            .find("acquire_file_lock_exclusive")
            .map(|offset| execution_fence + offset)
            .expect("descriptor file fence");
        let durable_checkpoint = prepare[descriptor_fence..]
            .find("internal_delegation_checkpoint_scoped")
            .map(|offset| descriptor_fence + offset)
            .expect("peer-visible durable delegation checkpoint");
        let descriptor_publish = prepare[durable_checkpoint..]
            .find("save_stateless_children_handoff_descriptor")
            .map(|offset| durable_checkpoint + offset)
            .expect("sealed descriptor publication");
        assert!(execution_fence < descriptor_fence);
        assert!(descriptor_fence < durable_checkpoint && durable_checkpoint < descriptor_publish);
    }

    #[test]
    fn terminal_recovery_uses_children_handoff_body_under_its_existing_lifecycle_fence() {
        let source = include_str!("service.rs");
        let recovery = source
            .split("pub(crate) async fn recover_interrupted_runtime_execution")
            .nth(1)
            .and_then(|tail| {
                tail.split("pub(crate) async fn wait_for_interrupted_runtime_recoveries")
                    .next()
            })
            .expect("interrupted recovery source");
        let terminal = recovery
            .find("if is_terminal_execution_status")
            .expect("terminal projection branch");
        let branch = &recovery[terminal..];
        let held = branch
            .find("prepare_stateless_children_handoff_with_lifecycle_held")
            .expect("already-held lifecycle handoff body");
        let fallback = branch
            .find("prepare_stateless_children_handoff(")
            .expect("unguarded exact-timer fallback wrapper");
        assert!(held < fallback);
        assert!(branch[..fallback].contains("_execution_lifecycle_exclusion.is_some()"));

        let wrapper = source
            .split("async fn prepare_stateless_children_handoff(")
            .nth(1)
            .and_then(|tail| {
                tail.split("async fn prepare_stateless_children_handoff_with_lifecycle_held")
                    .next()
            })
            .expect("handoff lifecycle wrapper");
        assert!(wrapper.contains("acquire_stateless_execution_lifecycle_exclusion_scoped"));
        assert!(wrapper.contains("prepare_stateless_children_handoff_with_lifecycle_held"));

        let body = source
            .split("async fn prepare_stateless_children_handoff_with_lifecycle_held")
            .nth(1)
            .and_then(|tail| {
                tail.split("async fn consume_stateless_children_handoff")
                    .next()
            })
            .expect("already-held lifecycle body");
        assert!(body.contains("acquire_file_lock_exclusive"));
        assert!(!body.contains("acquire_stateless_execution_lifecycle_exclusion_scoped"));
    }

    #[test]
    fn terminally_superseded_delegation_never_projects_waiting_children() {
        let source = include_str!("service.rs");
        let continuation = source
            .split("async fn continue_execution_with_orchestrator")
            .nth(1)
            .and_then(|tail| tail.split("async fn verification_hold_decision").next())
            .expect("orchestrator continuation source window");
        let superseded = continuation
            .find("DelegationCheckpointResume::Superseded")
            .expect("terminal supersession branch");
        let projection = continuation[superseded..]
            .find("persist_runtime_execution_outcome(")
            .map(|offset| superseded + offset)
            .expect("authoritative terminal projection");
        // The branch lives inside a lifted region whose early exits are
        // `return Ok(Err(<outcome>))` — the inner `Err` is the region's exit,
        // re-raised as the function's `Ok(outcome)` after the await — so the
        // contract matches the outcome, not the exact spelling of the return.
        let return_owned = continuation[projection..]
            .find("ContinuedExecutionOutcome::PipelineOwned)")
            .map(|offset| projection + offset)
            .expect("no retryable waiting projection");
        assert!(superseded < projection && projection < return_owned);
    }

    #[test]
    fn foreign_owned_delegation_preserves_handoff_without_projection_or_consume() {
        let source = include_str!("service.rs");
        let recovered = source
            .split("async fn run_recovered_stateless_parent_continuation")
            .nth(1)
            .and_then(|tail| tail.split("async fn run_explicit_delegation").next())
            .expect("recovered parent continuation");
        let deferred = recovered
            .find("ContinuedExecutionOutcome::Deferred")
            .expect("typed foreign-owner disposition");
        let early_return = recovered[deferred..]
            .find("return Ok(())")
            .map(|offset| deferred + offset)
            .expect("deferred recovery return");
        let consume = recovered
            .find("consume_stateless_children_handoff")
            .expect("ordinary descriptor retirement");
        assert!(deferred < early_return && early_return < consume);
        assert!(recovered[deferred..early_return].contains("schedule_parent_resume_wake_at"));

        let continuation = source
            .split("async fn continue_execution_with_orchestrator")
            .nth(1)
            .expect("delegation continuation mapping");
        assert!(continuation.contains("DelegationCheckpointResume::Deferred"));
        assert!(continuation.contains("ContinuedExecutionOutcome::Deferred"));
    }

