    #[test]
    fn agent_tool_restart_only_adopts_known_prestart_execution_states() {
        for status in ["pending", "ready", "queued"] {
            assert!(!app_agent_tool_restart_requires_uncertain_failure(status));
        }
        for status in [
            "running",
            "waiting_for_children",
            "waiting_for_user",
            "paused",
            "unknown_future_state",
        ] {
            assert!(app_agent_tool_restart_requires_uncertain_failure(status));
        }
        for status in ["completed", "failed", "cancelled", "canceled"] {
            assert!(!app_agent_tool_restart_requires_uncertain_failure(status));
        }
        assert!(app_agent_tool_startup_should_fail_attached_child(
            "running", false
        ));
        assert!(!app_agent_tool_startup_should_fail_attached_child(
            "running", true
        ));
    }

