    /// The child-terminal → parent-resume walk must terminate on its own, not
    /// because `parent_execution_id` chains happen to be short. Storage accepts
    /// a parent link that closes a cycle, and the child branch of
    /// `persist_execution_outcome` runs before every idempotency
    /// short-circuit, so nothing else in the cycle can stop it.
    #[test]
    fn a_parent_chain_that_closes_a_cycle_stops_the_walk() {
        // exec-a finalizes into exec-b ...
        let walk = ParentResumeWalk::default();
        assert_eq!(walk.stop_reason("exec-a", "exec-b"), None);

        // ... exec-b resumes, terminates, and points back at exec-a.
        let walk = walk.extended("exec-a");
        assert_eq!(
            walk.stop_reason("exec-b", "exec-a"),
            Some("parent execution is already on this walk"),
        );
    }

    #[test]
    fn an_execution_that_parents_itself_stops_the_walk() {
        assert_eq!(
            ParentResumeWalk::default().stop_reason("exec-a", "exec-a"),
            Some("execution is its own parent"),
        );
    }

    /// The bound must not fire on legitimate lineage: a real chain of four
    /// delegated executions resuming in order stays well inside it.
    #[test]
    fn a_real_four_deep_chain_walks_to_the_root() {
        let chain = ["exec-1", "exec-2", "exec-3", "exec-4", "exec-root"];
        let mut walk = ParentResumeWalk::default();
        for pair in chain.windows(2) {
            assert_eq!(
                walk.stop_reason(pair[0], pair[1]),
                None,
                "a straight parent chain must not trip the bound"
            );
            walk = walk.extended(pair[0]);
        }
        assert_eq!(walk.depth(), chain.len() - 1);
        assert_eq!(walk.trail(), "exec-1 -> exec-2 -> exec-3 -> exec-4");
    }

    #[test]
    fn an_over_long_chain_stops_at_the_depth_bound() {
        let mut walk = ParentResumeWalk::default();
        for index in 0..MAX_PARENT_RESUME_WALK_DEPTH {
            assert_eq!(
                walk.stop_reason(&format!("exec-{index}"), &format!("exec-{}", index + 1)),
                None
            );
            walk = walk.extended(&format!("exec-{index}"));
        }
        assert_eq!(
            walk.stop_reason("exec-tail", "exec-tail-parent"),
            Some("parent chain exceeded the walk depth bound"),
        );
    }

    #[test]
    fn raw_artifact_wire_moves_the_admitted_payload_without_a_recursive_clone() {
        std::thread::Builder::new()
            .name("artifact-wire-small-stack".to_string())
            .stack_size(256 * 1024)
            .spawn(|| {
                let mut payload = Value::String("stable-allocation".to_string());
                for _ in 0..MAX_RETAINED_JSON_DEPTH.saturating_sub(4) {
                    payload = Value::Array(vec![payload]);
                }
                let mut leaf = &payload;
                while let Some(array) = leaf.as_array() {
                    leaf = &array[0];
                }
                let before = leaf.as_str().expect("string leaf").as_ptr();

                let mut wire =
                    persisted_execution_artifact_into_value(PersistedExecutionArtifactRecord {
                        artifact_id: "artifact-1".to_string(),
                        artifact_type: "tool_output_file".to_string(),
                        content_type: "application/json".to_string(),
                        payload,
                        produced_at: "2026-08-05T00:00:00Z".to_string(),
                        source_execution_id: Some("exec-source".to_string()),
                        source_artifact_id: None,
                    });
                assert_eq!(wire["artifact_id"], "artifact-1");
                assert_eq!(wire["source_execution_id"], "exec-source");
                assert!(wire["source_artifact_id"].is_null());

                let mut moved_leaf = &wire["payload"];
                while let Some(array) = moved_leaf.as_array() {
                    moved_leaf = &array[0];
                }
                assert_eq!(
                    moved_leaf.as_str().expect("moved string leaf").as_ptr(),
                    before,
                    "the payload allocation must move into the compatibility wire",
                );
                discard_json_iteratively(std::mem::replace(&mut wire, Value::Null));
            })
            .expect("spawn small-stack artifact wire regression")
            .join()
            .expect("artifact wire regression completes");
    }

