    #[tokio::test]
    async fn auxiliary_sidecar_readers_fail_closed_on_oversized_or_deep_json() {
        let tmp = tempfile::tempdir().expect("temporary workspace");
        let workspace = ArtifactV2Workspace::new(tmp.path());
        let voice_path = tmp.path().join(VOICE_SPEECH_SIDECAR_FILE);
        let task_path = tmp.path().join(TASK_SUMMARY_SIDECAR_FILE);

        let voice = VoiceSpeechSummary {
            live: Some("The task is complete.".to_string()),
            tts: Some("The requested task completed successfully.".to_string()),
        };
        write_voice_speech_sidecar(&workspace, &voice_path, &voice)
            .await
            .expect("valid voice sidecar");
        assert_eq!(
            read_voice_speech_sidecar(&workspace, &voice_path)
                .await
                .and_then(|summary| summary.live),
            voice.live
        );

        let task = TaskSummarySidecar {
            text: "A bounded task summary.".to_string(),
            generated_by: "verbatim".to_string(),
            source_output_id: "out-1".to_string(),
            source_output_revision: Some("revision-1".to_string()),
        };
        write_task_summary_sidecar(&workspace, &task_path, &task)
            .await
            .expect("valid task sidecar");
        assert_eq!(
            read_task_summary_sidecar(&workspace, &task_path)
                .await
                .map(|summary| summary.text),
            Some(task.text)
        );

        workspace
            .write_atomic_path(
                &voice_path,
                &vec![b'x'; VOICE_SPEECH_SIDECAR_MAX_BYTES as usize + 1],
            )
            .await
            .expect("oversized voice fixture");
        assert!(read_voice_speech_sidecar(&workspace, &voice_path)
            .await
            .is_none());

        workspace
            .write_atomic_path(
                &task_path,
                &vec![b'x'; TASK_SUMMARY_SIDECAR_MAX_BYTES as usize + 1],
            )
            .await
            .expect("oversized task fixture");
        assert!(read_task_summary_sidecar(&workspace, &task_path)
            .await
            .is_none());

        let nested = format!(
            "{{\"live\":\"still valid without the extra field\",\"extra\":{}}}",
            format!(
                "{}\"too deep\"{}",
                "[".repeat(AUXILIARY_SIDECAR_MAX_DEPTH + 1),
                "]".repeat(AUXILIARY_SIDECAR_MAX_DEPTH + 1)
            )
        );
        workspace
            .write_atomic_path(&voice_path, nested.as_bytes())
            .await
            .expect("deep voice fixture");
        assert!(read_voice_speech_sidecar(&workspace, &voice_path)
            .await
            .is_none());

        let nested = format!(
            "{{\"text\":\"summary\",\"generated_by\":\"verbatim\",\"source_output_id\":\"out-1\",\"extra\":{}}}",
            format!(
                "{}null{}",
                "[".repeat(AUXILIARY_SIDECAR_MAX_DEPTH + 1),
                "]".repeat(AUXILIARY_SIDECAR_MAX_DEPTH + 1)
            )
        );
        workspace
            .write_atomic_path(&task_path, nested.as_bytes())
            .await
            .expect("deep task fixture");
        assert!(read_task_summary_sidecar(&workspace, &task_path)
            .await
            .is_none());

        let source = include_str!("service.rs");
        for (start, end, typed_reader) in [
            (
                "async fn read_voice_speech_sidecar(",
                "/// Sidecar file (next to the task user output) holding a cached",
                "read_json_bounded_stream_path::<VoiceSpeechSummary",
            ),
            (
                "pub async fn read_task_summary_sidecar(",
                "/// Decide whether a deliverable's readable text warrants an LLM summary.",
                "read_json_bounded_stream_path::<TaskSummarySidecar",
            ),
        ] {
            let reader = source
                .split_once(start)
                .expect("sidecar reader")
                .1
                .split_once(end)
                .expect("sidecar reader end")
                .0;
            assert!(reader.contains(typed_reader));
            assert!(!reader.contains("read_path("));
            assert!(!reader.contains("serde_json::from_slice"));
        }
    }

    fn write_coding_event_records(path: &Path, records: &[Value]) {
        use std::io::Write;

        let mut file = std::io::BufWriter::new(File::create(path).expect("create coding log"));
        for record in records {
            serde_json::to_writer(&mut file, record).expect("serialize coding event");
            file.write_all(b"\n").expect("coding event delimiter");
        }
        file.flush().expect("flush coding log");
    }

