    #[tokio::test]
    async fn coding_event_reader_skips_malformed_deep_and_oversized_records_then_continues() {
        use std::io::Write;

        let tmp = tempfile::tempdir().expect("temporary logs");
        let path = tmp.path().join("corrupt.jsonl");
        let mut file = std::io::BufWriter::new(File::create(&path).expect("create coding log"));
        file.write_all(b"{not-json}\n").expect("malformed record");
        let deep = format!(
            "{}null{}\n",
            "[".repeat(MAX_RETAINED_JSON_DEPTH + 1),
            "]".repeat(MAX_RETAINED_JSON_DEPTH + 1),
        );
        file.write_all(deep.as_bytes()).expect("deep record");
        file.write_all(&vec![b'x'; MAX_CODING_EVENT_RECORD_BYTES + 1])
            .expect("oversized record");
        file.write_all(b"\n").expect("oversized delimiter");
        file.write_all(b"{\"id\":1,\"timestamp_ms\":10}\n")
            .expect("first valid record");
        file.write_all(b"{\"id\":2,\"timestamp_ms\":5}\n")
            .expect("second valid record");
        file.flush().expect("flush coding log");

        let events = ArtifactV2Service::read_recent_coding_event_logs(vec![(0, path)], 8)
            .await
            .expect("bounded tolerant coding merge");
        assert_eq!(
            events
                .iter()
                .filter_map(|event| event.get("id").and_then(Value::as_i64))
                .collect::<Vec<_>>(),
            vec![1, 2],
        );
    }

    #[derive(Default)]
    struct TerminalBoundaryProbe {
        stages: std::sync::Mutex<Vec<&'static str>>,
        execution_context_addresses: std::sync::Mutex<Vec<usize>>,
        terminal_file_authority_addresses: std::sync::Mutex<Vec<usize>>,
        task_context_addresses: std::sync::Mutex<Vec<usize>>,
        task_output_addresses: std::sync::Mutex<Vec<usize>>,
    }

    impl TerminalBoundaryProbe {
        fn observe(&self, stage: &'static str, ctx: &ExecutionContext) -> OutputRef {
            assert!(
                TERMINAL_CALLER_POLL_CHAIN.try_with(|_| ()).is_err(),
                "{stage} finalizer inherited the terminal caller's poll chain"
            );
            self.stages
                .lock()
                .expect("terminal boundary stages")
                .push(stage);
            OutputRef {
                output_id: format!("out-{stage}"),
                scope: "execution".to_string(),
                audience: "agent".to_string(),
                role: stage.to_string(),
                relative_path: format!("outputs/{stage}.md"),
                media_type: "text/markdown".to_string(),
                created_at: "2026-08-05T00:00:00Z".to_string(),
                source_execution_id: Some(ctx.execution_id.clone()),
                source_plan_id: Some("plan-boundary".to_string()),
                source_output_ids: Vec::new(),
            }
        }
    }

    #[async_trait::async_trait]
    impl ExecutionFinalizer for TerminalBoundaryProbe {
        async fn finalize(
            &self,
            ctx: &ExecutionFinalizeContext,
        ) -> Result<OutputRef, ArtifactV2Error> {
            self.execution_context_addresses
                .lock()
                .expect("execution context addresses")
                .push(ctx as *const ExecutionFinalizeContext as usize);
            if let Some(projection) = ctx.verified_terminal_projection.as_ref() {
                self.terminal_file_authority_addresses
                    .lock()
                    .expect("terminal file authority addresses")
                    .push(Arc::as_ptr(&projection.source_path) as usize);
            }
            Ok(self.observe("execution", &ctx.execution))
        }
    }

    #[async_trait::async_trait]
    impl TaskAgentFinalizer for TerminalBoundaryProbe {
        async fn finalize(&self, ctx: &TaskFinalizeContext) -> Result<OutputRef, ArtifactV2Error> {
            self.task_context_addresses
                .lock()
                .expect("task context addresses")
                .push(ctx as *const TaskFinalizeContext as usize);
            Ok(self.observe("task-agent", &ctx.execution))
        }
    }

    #[async_trait::async_trait]
    impl TaskUserFinalizer for TerminalBoundaryProbe {
        async fn finalize(
            &self,
            ctx: &TaskFinalizeContext,
            task_agent_output: &OutputRef,
        ) -> Result<OutputRef, ArtifactV2Error> {
            self.task_context_addresses
                .lock()
                .expect("task context addresses")
                .push(ctx as *const TaskFinalizeContext as usize);
            self.task_output_addresses
                .lock()
                .expect("task output addresses")
                .push(task_agent_output as *const OutputRef as usize);
            Ok(self.observe("task-user", &ctx.execution))
        }

        async fn finalize_projection(
            &self,
            ctx: &TaskFinalizeContext,
            task_agent_output: &OutputRef,
            _verified_terminal_projection: bool,
        ) -> Result<OutputRef, ArtifactV2Error> {
            self.task_context_addresses
                .lock()
                .expect("task context addresses")
                .push(ctx as *const TaskFinalizeContext as usize);
            self.task_output_addresses
                .lock()
                .expect("task output addresses")
                .push(task_agent_output as *const OutputRef as usize);
            Ok(self.observe("task-user-projection", &ctx.execution))
        }
    }

