    #[tokio::test]
    async fn terminal_output_finalizers_leave_the_callers_poll_chain() {
        let probe = Arc::new(TerminalBoundaryProbe::default());
        let execution_ctx = Arc::new(terminal_boundary_execution_context());
        let seed_output = OutputRef {
            output_id: "out-seed".to_string(),
            scope: "execution".to_string(),
            audience: "agent".to_string(),
            role: "primary_execution".to_string(),
            relative_path: "outputs/out-seed.md".to_string(),
            media_type: "text/markdown".to_string(),
            created_at: "2026-08-05T00:00:00Z".to_string(),
            source_execution_id: Some(execution_ctx.execution.execution_id.clone()),
            source_plan_id: Some(execution_ctx.plan_ref.plan_id.clone()),
            source_output_ids: Vec::new(),
        };
        let task_ctx = Arc::new(TaskFinalizeContext {
            execution: execution_ctx.execution.clone(),
            task_dir: execution_ctx.task_dir.clone(),
            manifest: execution_ctx.manifest.clone(),
            task_output_mode: TaskOutputMode::Overwrite,
            task_projection_execution_id: execution_ctx.execution.execution_id.clone(),
            execution_output: seed_output.clone(),
            plan_ref: execution_ctx.plan_ref.clone(),
            execution_status: execution_ctx.execution_status.clone(),
            outcome_type: execution_ctx.outcome_type.clone(),
            outcome_summary: execution_ctx.outcome_summary.clone(),
            source_output_ids: Vec::new(),
            verified_terminal_projection: None,
            llm_routing_overrides: None,
            now: execution_ctx.now.clone(),
        });
        let seed_output = Arc::new(seed_output);
        let execution_ctx_address = Arc::as_ptr(&execution_ctx) as usize;
        let task_ctx_address = Arc::as_ptr(&task_ctx) as usize;
        let seed_output_address = Arc::as_ptr(&seed_output) as usize;

        TERMINAL_CALLER_POLL_CHAIN
            .scope((), async {
                let execution_finalizer: Arc<dyn ExecutionFinalizer> = probe.clone();
                run_execution_finalizer_on_execution_runtime(
                    execution_finalizer,
                    Arc::clone(&execution_ctx),
                )
                .await
                .expect("execution finalizer boundary");

                let task_agent_finalizer: Arc<dyn TaskAgentFinalizer> = probe.clone();
                run_task_agent_finalizer_on_execution_runtime(
                    task_agent_finalizer,
                    Arc::clone(&task_ctx),
                )
                .await
                .expect("task-agent finalizer boundary");

                let task_user_finalizer: Arc<dyn TaskUserFinalizer> = probe.clone();
                run_task_user_finalizer_on_execution_runtime(
                    Arc::clone(&task_user_finalizer),
                    Arc::clone(&task_ctx),
                    Arc::clone(&seed_output),
                )
                .await
                .expect("task-user finalizer boundary");
                run_task_user_projection_on_execution_runtime(
                    task_user_finalizer,
                    Arc::clone(&task_ctx),
                    Arc::clone(&seed_output),
                    false,
                )
                .await
                .expect("task-user projection boundary");
            })
            .await;

        assert_eq!(
            *probe.stages.lock().expect("terminal boundary stages"),
            vec![
                "execution",
                "task-agent",
                "task-user",
                "task-user-projection",
            ]
        );
        assert_eq!(
            *probe
                .execution_context_addresses
                .lock()
                .expect("execution context addresses"),
            vec![execution_ctx_address]
        );
        assert_eq!(
            *probe
                .task_context_addresses
                .lock()
                .expect("task context addresses"),
            vec![task_ctx_address; 3]
        );
        assert_eq!(
            *probe
                .task_output_addresses
                .lock()
                .expect("task output addresses"),
            vec![seed_output_address; 2]
        );
    }

    #[tokio::test]
    async fn terminal_finalizer_attempts_share_one_file_backed_projection_context() {
        let probe = Arc::new(TerminalBoundaryProbe::default());
        let mut context = terminal_boundary_execution_context();
        let source_path = Arc::new(PathBuf::from("accepted/large-terminal.md"));
        context.verified_terminal_projection = Some(VerifiedTerminalProjection {
            source_execution_id: context.execution.execution_id.clone(),
            media_type: "text/markdown".to_string(),
            source_path: Arc::clone(&source_path),
            content_sha256: Arc::<str>::from("a".repeat(64)),
            text_preview: Some(Arc::<str>::from("bounded preview")),
            byte_len: 4 * 1024 * 1024,
            companion_notes: Vec::new(),
        });
        let context = Arc::new(context);
        let context_address = Arc::as_ptr(&context) as usize;
        let source_address = Arc::as_ptr(&source_path) as usize;

        for _ in 0..3 {
            let finalizer: Arc<dyn ExecutionFinalizer> = probe.clone();
            run_execution_finalizer_on_execution_runtime(finalizer, Arc::clone(&context))
                .await
                .expect("simulated retry attempt");
        }

        assert_eq!(
            *probe
                .execution_context_addresses
                .lock()
                .expect("execution context addresses"),
            vec![context_address; 3]
        );
        assert_eq!(
            *probe
                .terminal_file_authority_addresses
                .lock()
                .expect("terminal file authority addresses"),
            vec![source_address; 3]
        );
    }

