    #[tokio::test]
    async fn terminal_projection_stream_verification_is_exact_and_preview_bounded() {
        use sha2::{Digest, Sha256};

        let temp = tempfile::TempDir::new().expect("temp dir");
        let path = temp.path().join("task_deliverable.md");
        let accepted = format!(
            "accepted child answer\n{}\nterminal marker",
            "detail ".repeat(MAX_TERMINAL_PROJECTION_PREVIEW_BYTES)
        );
        tokio::fs::write(&path, accepted.as_bytes())
            .await
            .expect("accepted terminal fixture");
        let mut artifact = terminal_artifact("task_deliverable", "exec-1");
        artifact.payload["content_sha256"] =
            Value::String(format!("{:x}", Sha256::digest(accepted.as_bytes())));

        let inspected = inspect_verified_terminal_artifact_file(&artifact, &path)
            .await
            .expect("stream inspection")
            .expect("accepted bytes");
        assert_eq!(inspected.byte_len, accepted.len() as u64);
        assert!(inspected
            .text_preview
            .as_ref()
            .is_some_and(|preview| preview.len() <= MAX_TERMINAL_PROJECTION_PREVIEW_BYTES));

        tokio::fs::write(&path, b"modified child answer")
            .await
            .expect("modified fixture");
        assert!(inspect_verified_terminal_artifact_file(&artifact, &path)
            .await
            .expect("modified inspection")
            .is_none());
    }

    #[tokio::test]
    async fn legacy_projection_text_read_is_exactly_bounded_and_utf8_strict() {
        let temp = tempfile::TempDir::new().expect("temp dir");
        let workspace = ArtifactV2Workspace::new(temp.path());
        let path = temp.path().join("legacy-output.md");

        let accepted = vec![b'x'; MAX_LEGACY_PROJECTION_TEXT_BYTES as usize];
        workspace
            .write_atomic_path(&path, &accepted)
            .await
            .expect("accepted fixture");
        assert_eq!(
            read_legacy_projection_text_bounded(&workspace, &path)
                .await
                .expect("exact ceiling accepted")
                .len(),
            accepted.len()
        );

        workspace
            .write_atomic_path(
                &path,
                &vec![b'x'; MAX_LEGACY_PROJECTION_TEXT_BYTES as usize + 1],
            )
            .await
            .expect("oversized fixture");
        assert!(matches!(
            read_legacy_projection_text_bounded(&workspace, &path).await,
            Err(ArtifactV2Error::InvalidRequest(message))
                if message.contains("legacy projection source exceeds")
        ));

        workspace
            .write_atomic_path(&path, &[0xff, 0xfe])
            .await
            .expect("invalid UTF-8 fixture");
        assert!(matches!(
            read_legacy_projection_text_bounded(&workspace, &path).await,
            Err(ArtifactV2Error::InvalidRequest(message))
                if message.contains("not valid UTF-8")
        ));
    }

    #[tokio::test]
    async fn auxiliary_output_metadata_reads_only_a_bounded_prefix() {
        let temp = tempfile::TempDir::new().expect("temp dir");
        let workspace = ArtifactV2Workspace::new(temp.path());
        let path = temp.path().join("large-output.md");
        let mut body = vec![b'x'; MAX_AUXILIARY_OUTPUT_PREFIX_BYTES as usize + 64 * 1024];
        body.extend_from_slice(b"terminal bytes must not enter metadata");
        workspace
            .write_atomic_path(&path, &body)
            .await
            .expect("large auxiliary fixture");

        let preview = read_auxiliary_output_prefix(&workspace, &path)
            .await
            .expect("bounded auxiliary prefix");
        assert!(!preview.contains("terminal bytes must not enter metadata"));
        assert!(preview.contains("Output preview truncated"));
        assert!(preview.len() < MAX_AUXILIARY_OUTPUT_PREFIX_BYTES as usize + 128);
    }

    #[tokio::test]
    async fn cancelled_synthesis_is_not_retried_or_marked_retryable() {
        let calls = std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let observed = std::sync::Arc::clone(&calls);
        let failure = retry_synthesis_step(
            crate::magician_v2::artifact_v2::models::SynthesisStage::ExecutionOutput,
            move || {
                observed.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                async {
                    Err::<(), _>(ArtifactV2Error::Runtime(
                        "LLM dispatch failed: call cancelled: task_cancelled_in_flight".to_string(),
                    ))
                }
            },
        )
        .await
        .expect_err("cancellation should stop synthesis");

        assert_eq!(calls.load(std::sync::atomic::Ordering::SeqCst), 1);
        assert_eq!(failure.attempts, 1);
        assert!(synthesis_cancellation_message(&failure.last_error));
        assert!(!synthesis_cancellation_message(
            "provider returned status 503"
        ));
    }

