    #[test]
    fn deferred_progress_projection_coalesces_bursts_without_losing_latest_generation() {
        let generations = Mutex::new(HashMap::new());
        let key = "principal\u{1f}workspace\u{1f}task-1";

        assert!(request_progress_projection(&generations, key));
        let first_generation =
            progress_projection_generation(&generations, key).expect("first generation");
        assert!(!request_progress_projection(&generations, key));
        assert!(!request_progress_projection(&generations, key));
        assert!(
            !complete_progress_projection_generation(&generations, key, first_generation),
            "the active worker must rerun after coalescing newer requests"
        );

        let latest_generation =
            progress_projection_generation(&generations, key).expect("latest generation");
        assert!(latest_generation > first_generation);
        assert!(complete_progress_projection_generation(
            &generations,
            key,
            latest_generation
        ));
        assert!(progress_projection_generation(&generations, key).is_none());
    }

