    #[test]
    fn shared_recovery_deadline_queue_replaces_stale_entries_without_duplicates() {
        let mut queue = DeadlineRecoveryQueue::default();
        queue.insert("same".to_string(), 50, "old");
        queue.insert("same".to_string(), 10, "new");
        queue.insert("later".to_string(), 25, "later");

        assert_eq!(queue.next_deadline_ms(), Some(10));
        assert_eq!(queue.pop_due(9), None);
        assert_eq!(queue.pop_due(10), Some(("same".to_string(), "new")));
        assert_eq!(queue.next_deadline_ms(), Some(25));
        assert_eq!(queue.pop_due(25), Some(("later".to_string(), "later")));
        assert_eq!(queue.pop_due(i64::MAX), None);
    }

