    /// A parent reconciles its delegated children only once every child in the
    /// active group has reached a terminal waiting state. Resuming earlier hands
    /// the parent a summary of work that has not happened — its children read as
    /// producing nothing — and the parent then reports its own delegation as
    /// having failed.
    #[test]
    fn a_delegation_group_is_settled_only_when_every_child_is_terminal() {
        assert!(delegated_children_are_settled(&[]));
        assert!(delegated_children_are_settled(&[WaitingState::Completed]));
        assert!(delegated_children_are_settled(&[
            WaitingState::Completed,
            WaitingState::Failed,
            WaitingState::Cancelled,
        ]));
        assert!(
            !delegated_children_are_settled(&[WaitingState::Executing]),
            "a running child is not a result"
        );
        assert!(
            !delegated_children_are_settled(&[WaitingState::Completed, WaitingState::Runnable]),
            "one unfinished child holds the whole group"
        );
        assert!(!delegated_children_are_settled(&[
            WaitingState::WaitingChildren
        ]));
    }

    /// The settled check must gate the summary and the resume, not follow them:
    /// the summary is what the parent reads as its children's results.
    #[test]
    fn the_v3_parent_resume_checks_its_children_before_summarizing_them() {
        let source = include_str!("service.rs");
        let resume = source
            .split("fn maybe_resume_parent_after_v3_child_results")
            .nth(1)
            .and_then(|tail| {
                tail.split("async fn complete_explicit_delegation_parent")
                    .next()
            })
            .expect("v3 parent resume reconciliation");
        let settled = resume
            .find("delegated_children_are_settled")
            .expect("the active group's children are checked for terminality");
        let summary = resume
            .find("persist_parent_delegation_summary_from_v3")
            .expect("the parent delegation summary");
        assert!(
            settled < summary,
            "the group must be settled before its results are summarized"
        );
    }

