    #[test]
    fn is_orphaned_user_pause_only_flags_unresumable_user_waits() {
        // Orphan: waiting on user, no pause file, no durable pause → finalize.
        assert!(ArtifactV2Service::is_orphaned_user_pause(
            "waiting_for_user",
            false,
            false
        ));
        assert!(ArtifactV2Service::is_orphaned_user_pause(
            "paused", false, false
        ));
        assert!(ArtifactV2Service::is_orphaned_user_pause(
            "paused_by_user",
            false,
            false
        ));
        // A live/resumable HITL pause (pause file present) is spared.
        assert!(!ArtifactV2Service::is_orphaned_user_pause(
            "waiting_for_user",
            true,
            false
        ));
        // A durable pause (paused_from_state, e.g. WaitingChildren) is spared.
        assert!(!ArtifactV2Service::is_orphaned_user_pause(
            "waiting_for_user",
            false,
            true
        ));
        // Non-user-wait statuses are never finalized by this guard.
        assert!(!ArtifactV2Service::is_orphaned_user_pause(
            "running", false, false
        ));
        assert!(!ArtifactV2Service::is_orphaned_user_pause(
            "waiting_for_children",
            false,
            false
        ));
        assert!(!ArtifactV2Service::is_orphaned_user_pause(
            "completed",
            false,
            false
        ));
    }

    /// The projection half of the `last_progress_at` contract. The reducer
    /// tests pin what moves the field; this pins that the wire carries THAT
    /// field and not `updated_at` under its name — the one substitution that
    /// would silently restore the defect while every reducer test still passed.
    ///
    /// The two instants differ by design: with a shared fixture timestamp this
    /// assertion would hold no matter which field the builder read.
    #[test]
    fn task_list_item_carries_the_progress_instant_not_updated_at() {
        const PROGRESSED_AT: &str = "2026-07-29T11:00:00Z";
        const UPDATED_AT: &str = "2026-07-29T11:26:00Z";

        let mut task = sample_task_record();
        task.state.last_progress_at = Some(PROGRESSED_AT.to_string());
        task.state.updated_at = UPDATED_AT.to_string();

        let item = ArtifactV2Service::build_task_list_item_lightweight(task, false);

        assert_eq!(item.last_progress_at.as_deref(), Some(PROGRESSED_AT));
        assert_eq!(item.updated_at, UPDATED_AT);
        assert_ne!(
            item.last_progress_at.as_deref(),
            Some(item.updated_at.as_str()),
            "a run that keeps writing while making no progress must still look \
             silent on the wire"
        );
    }

    /// Absence stays absence. Consumers compute `now - last_progress_at` and
    /// render the result, so a sentinel (`0`, `-1`, a magic never-value) would
    /// be turned into a duration and displayed as garbage; `None` is the only
    /// representation that degrades honestly to unknown.
    #[test]
    fn task_list_item_omits_the_progress_instant_when_there_is_none() {
        let mut task = sample_task_record();
        task.state.last_progress_at = None;

        let item = ArtifactV2Service::build_task_list_item_lightweight(task, false);
        assert!(item.last_progress_at.is_none());

        let wire = serde_json::to_value(&item).expect("list item should serialize");
        assert!(
            wire.get("last_progress_at").is_none(),
            "the key is omitted entirely rather than carrying a placeholder"
        );
    }

