    #[tokio::test]
    async fn app_workflow_shell_becomes_ready_only_through_private_activation() {
        let tmp = tempfile::TempDir::new().expect("temp dir");
        let service = build_test_artifact_v2_service(tmp.path());
        let task_id = format!("task_app_{}", "a".repeat(64));
        let scope = ScopeRef::system_internal_unauthenticated(
            &"anonymous".to_owned(),
            &"default".to_owned(),
        );
        let created = service
            .ensure_app_workflow_task_with_id(
                app_workflow_create_input_fixture(&scope),
                task_id.clone(),
            )
            .await
            .expect("create app task shell");
        assert_eq!(created.state.status, "pending");

        let ready = service
            .mark_app_workflow_task_ready(&scope, &task_id)
            .await
            .expect("activate sealed app task");
        assert_eq!(ready.state.status, "ready");
        assert!(ready.state.active_root_execution_id.is_none());
        assert!(ready.state.latest_root_execution_id.is_none());

        let mut contaminated = ready;
        contaminated.state.latest_root_execution_id = Some("exec_prior".to_owned());
        service
            .persist_task_record(&scope, &contaminated)
            .await
            .expect("persist impossible ready shell fixture");
        let error = service
            .mark_app_workflow_task_ready(&scope, &task_id)
            .await
            .expect_err("ready shell with execution evidence must fail closed");
        assert!(matches!(
            error,
            ArtifactV2Error::InvalidRequest(ref message)
                if message == "app_workflow_task_shell_not_pristine"
        ));
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn concurrent_deterministic_ensures_preserve_an_advanced_app_task() {
        let tmp = tempfile::TempDir::new().expect("temp dir");
        let service = build_test_artifact_v2_service(tmp.path());
        let task_id = format!("task_app_{}", "b".repeat(64));
        let scope = ScopeRef::system_internal_unauthenticated(
            &"anonymous".to_owned(),
            &"default".to_owned(),
        );
        service
            .ensure_app_workflow_task_with_id(
                app_workflow_create_input_fixture(&scope),
                task_id.clone(),
            )
            .await
            .expect("create app task");
        service
            .mark_app_workflow_task_ready(&scope, &task_id)
            .await
            .expect("advance task before retries");

        let barrier = Arc::new(tokio::sync::Barrier::new(3));
        let mut peers = Vec::new();
        for _ in 0..2 {
            let peer_service = Arc::clone(&service);
            let peer_scope = scope.clone();
            let peer_task_id = task_id.clone();
            let peer_barrier = Arc::clone(&barrier);
            peers.push(tokio::spawn(async move {
                peer_barrier.wait().await;
                peer_service
                    .ensure_app_workflow_task_with_id(
                        app_workflow_create_input_fixture(&peer_scope),
                        peer_task_id,
                    )
                    .await
            }));
        }
        barrier.wait().await;
        for peer in peers {
            let recovered = peer
                .await
                .expect("ensure peer did not panic")
                .expect("same-key ensure succeeds");
            assert_eq!(recovered.state.status, "ready");
        }
        let retained = service
            .get_task(&scope, &task_id)
            .await
            .expect("read retained task");
        assert_eq!(retained.state.status, "ready");
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn concurrent_app_root_prepares_commit_exactly_one_winner() {
        let tmp = tempfile::TempDir::new().expect("temp dir");
        let service = build_test_artifact_v2_service(tmp.path());
        let task_id = format!("task_app_{}", "c".repeat(64));
        let scope = ScopeRef::system_internal_unauthenticated(
            &"anonymous".to_owned(),
            &"default".to_owned(),
        );
        service
            .ensure_app_workflow_task_with_id(
                app_workflow_create_input_fixture(&scope),
                task_id.clone(),
            )
            .await
            .expect("create app task");
        service
            .mark_app_workflow_task_ready(&scope, &task_id)
            .await
            .expect("make app task startable");

        let barrier = Arc::new(tokio::sync::Barrier::new(3));
        let mut peers = Vec::new();
        for _ in 0..2 {
            let peer_service = Arc::clone(&service);
            let peer_scope = scope.clone();
            let peer_task_id = task_id.clone();
            let peer_barrier = Arc::clone(&barrier);
            peers.push(tokio::spawn(async move {
                peer_barrier.wait().await;
                let admission = peer_service
                    .acquire_app_workflow_start_admission(&peer_scope, &peer_task_id)
                    .await?;
                peer_service
                    .prepare_execution_start_internal(
                        &peer_scope,
                        &peer_task_id,
                        None,
                        false,
                        None,
                        false,
                        None,
                        None,
                        None,
                        Some(&admission),
                        None,
                    )
                    .await
            }));
        }
        barrier.wait().await;
        let mut winner_execution_id = None;
        let mut loser_error = None;
        for peer in peers {
            match peer.await.expect("prepare peer did not panic") {
                Ok((_, execution, _)) => {
                    assert!(winner_execution_id
                        .replace(execution.state.execution_id)
                        .is_none());
                },
                Err(error) => {
                    assert!(loser_error.replace(error).is_none());
                },
            }
        }
        let winner_execution_id = winner_execution_id.expect("one prepare wins");
        assert!(matches!(
            loser_error.expect("one prepare loses"),
            ArtifactV2Error::InvalidRequest(ref message)
                if message == &format!("task_execution_in_progress:{winner_execution_id}")
        ));
        let retained = service
            .get_task(&scope, &task_id)
            .await
            .expect("read retained winner");
        assert_eq!(
            retained.state.active_root_execution_id.as_deref(),
            Some(winner_execution_id.as_str())
        );
        let executions = service
            .list_executions(&scope, &task_id)
            .await
            .expect("list initialized roots");
        assert_eq!(executions.len(), 1);
        assert_eq!(executions[0].execution_id, winner_execution_id);
    }

