    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn deterministic_create_and_root_start_share_one_cross_process_admission_lock() {
        let tmp = tempfile::TempDir::new().expect("temp dir");
        let service = build_test_artifact_v2_service(tmp.path());
        let scope = ScopeRef::system_internal_unauthenticated(
            &"anonymous".to_owned(),
            &"default".to_owned(),
        );
        let task_id = "task_admission_lock_fixture".to_owned();
        let first = service
            .acquire_task_start_admission_guard(&scope, &task_id)
            .await
            .expect("first admission guard");

        let barrier = Arc::new(tokio::sync::Barrier::new(2));
        let peer_service = Arc::clone(&service);
        let peer_scope = scope.clone();
        let peer_task_id = task_id.clone();
        let peer_barrier = Arc::clone(&barrier);
        let mut peer = tokio::spawn(async move {
            peer_barrier.wait().await;
            peer_service
                .acquire_task_start_admission_guard(&peer_scope, &peer_task_id)
                .await
        });
        barrier.wait().await;

        assert!(
            tokio::time::timeout(std::time::Duration::from_millis(50), &mut peer)
                .await
                .is_err(),
            "same-task peer must remain behind the shared admission fence"
        );
        drop(first);
        let peer_guard = tokio::time::timeout(std::time::Duration::from_secs(1), peer)
            .await
            .expect("peer proceeds after winner releases")
            .expect("peer task did not panic")
            .expect("peer acquires admission guard");
        drop(peer_guard);

        assert_ne!(
            service
                .workspace()
                .task_lock_path(&scope.principal(), &scope.workspace(), &task_id,),
            service.workspace().task_start_admission_lock_path(
                &scope.principal(),
                &scope.workspace(),
                &task_id,
            ),
            "admission and reducer locks must remain distinct to avoid nested-flock deadlock"
        );
    }

    #[cfg(unix)]
    #[tokio::test]
    async fn pipeline_task_transaction_fence_rejects_a_symlinked_lock_file() {
        use std::os::unix::fs::symlink;

        let tmp = tempfile::TempDir::new().expect("temp dir");
        let workspace = ArtifactV2Workspace::new(tmp.path());
        let principal = "anonymous";
        let workspace_id = "default";
        let task_id = "task_pipeline_lock_symlink";
        let lock_path = workspace.task_lock_path(principal, workspace_id, task_id);
        std::fs::create_dir_all(lock_path.parent().expect("lock parent")).expect("lock parent");
        let outside = tmp.path().join("outside-task-lock");
        std::fs::write(&outside, b"outside").expect("outside fixture");
        symlink(&outside, &lock_path).expect("symlink lock");

        let error =
            acquire_pipeline_task_transaction_guard(&workspace, principal, workspace_id, task_id)
                .await
                .expect_err("transaction fence must not follow a symlink");
        assert!(matches!(
            error,
            ArtifactV2Error::Io(_) | ArtifactV2Error::Runtime(_)
        ));
        assert_eq!(
            std::fs::read(&outside).expect("outside remains"),
            b"outside"
        );
    }

