    #[test]
    fn task_authority_locks_revalidate_the_published_inode_after_flock() {
        let source = include_str!("service.rs");
        let transaction = source
            .split("pub(crate) async fn acquire_pipeline_task_transaction_guard")
            .nth(1)
            .and_then(|tail| {
                tail.split("pub(crate) struct AppWorkflowStartAdmission")
                    .next()
            })
            .expect("task transaction guard source");
        assert!(transaction.contains("validate_locked_file_path_identity"));

        let start = source
            .split("async fn acquire_task_start_admission_guard")
            .nth(1)
            .and_then(|tail| {
                tail.split("pub(crate) async fn acquire_app_workflow_start_admission")
                    .next()
            })
            .expect("task start admission guard source");
        assert!(start.contains("validate_locked_file_path_identity"));
    }

    #[tokio::test]
    async fn task_backed_pause_projects_v3_status_across_fresh_task_boundary() {
        let tmp = tempfile::TempDir::new().expect("temp dir");
        let (service, orchestrator) = build_test_artifact_v2_harness(tmp.path());
        let (task_id, projected_execution_id, execution_id) =
            crate::magician_v2::task_run_factory::create_task_backed_direct_root_run(
                service.as_ref(),
                &orchestrator,
                "user",
                "workspace",
                &crate::magician_v2::storage::task_models::default_ui_thread_id(),
                Some("Pause projection stack boundary"),
                "Project a normal clarification pause into task state.",
                crate::magician_v2::chat::DEFAULT_AGENT_ID,
                crate::magician_v2::storage::TaskCreatedBy::User,
                false,
                false,
            )
            .await
            .expect("bootstrap task-backed root execution");
        let scope = ScopeRef::system_internal_unauthenticated(
            &"user".to_string(),
            &"workspace".to_string(),
        );
        assert_eq!(projected_execution_id, execution_id);

        let status = orchestrator
            .transition_status(
                &execution_id,
                crate::magician_v2::orchestrator::WorkflowEvent::UserPaused,
            )
            .await
            .expect("task-backed pause transition should complete");
        assert_eq!(status, crate::magician_v2::storage::WaitingState::Paused);

        let runtime_execution = orchestrator
            .get_execution(&execution_id)
            .await
            .expect("runtime execution after pause");
        assert_eq!(
            runtime_execution.waiting_state,
            crate::magician_v2::storage::WaitingState::Paused
        );

        let projected_execution = service
            .get_execution(&scope, &task_id, &projected_execution_id)
            .await
            .expect("projected execution after pause");
        assert_eq!(projected_execution.state.status, "paused");

        let projected_task = service
            .get_task(&scope, &task_id)
            .await
            .expect("projected task after pause");
        assert_eq!(projected_task.state.status, "paused");
        assert_eq!(
            projected_task.state.active_root_execution_id.as_deref(),
            Some(execution_id.as_str()),
            "a pause keeps the root active for exact resume"
        );
    }

