    #[tokio::test]
    async fn stale_task_summary_cannot_overwrite_current_rerun_revision() {
        let tmp = tempfile::TempDir::new().expect("temp dir");
        let service = build_test_artifact_v2_service(tmp.path());
        let scope = ScopeRef::system_internal_unauthenticated(
            &"principal".to_string(),
            &"workspace".to_string(),
        );
        let (task, current_output) = completed_task_summary_fixture(service.as_ref(), &scope).await;
        let current_revision = task_summary_output_revision(&current_output);
        let current_sidecar = TaskSummarySidecar {
            text: "Current revision summary".to_string(),
            generated_by: "llm".to_string(),
            source_output_id: current_output.output_id.clone(),
            source_output_revision: Some(current_revision),
        };
        let sidecar_path = service
            .workspace
            .task_outputs_dir(
                &scope.principal(),
                &scope.workspace(),
                &task.manifest.task_id,
            )
            .join(TASK_SUMMARY_SIDECAR_FILE);
        write_task_summary_sidecar(&service.workspace, &sidecar_path, &current_sidecar)
            .await
            .expect("current sidecar persisted");

        let stale_output = OutputRef {
            created_at: "2026-08-02T09:00:00Z".to_string(),
            source_execution_id: Some("exec-summary-stale".to_string()),
            source_plan_id: Some("plan-summary-stale".to_string()),
            source_output_ids: vec!["out-exec-stale".to_string()],
            ..current_output
        };
        let stale_revision = task_summary_output_revision(&stale_output);
        let stale_sidecar = TaskSummarySidecar {
            text: "Stale revision summary".to_string(),
            generated_by: "llm".to_string(),
            source_output_id: stale_output.output_id.clone(),
            source_output_revision: Some(stale_revision.clone()),
        };

        assert!(!service
            .commit_task_summary_sidecar_if_current(
                &scope,
                &task.manifest.task_id,
                &stale_output,
                &stale_revision,
                &stale_sidecar,
            )
            .await
            .expect("stale commit is rejected"));
        let persisted = read_task_summary_sidecar(&service.workspace, &sidecar_path)
            .await
            .expect("current sidecar remains");
        assert_eq!(persisted.text, "Current revision summary");
    }

