    #[tokio::test]
    async fn pipeline_documents_use_aligned_streaming_byte_bounds() {
        use crate::magician_v2::execution::execution_summary::PipelineStage;

        let tmp = tempfile::TempDir::new().expect("temp dir");
        let service = build_test_artifact_v2_service(tmp.path());
        let scope = ScopeRef::system_internal_unauthenticated(
            &"anonymous".to_string(),
            &"default".to_string(),
        );
        let task_id = "task-pipeline-bounds";
        let execution_id = "exec-pipeline-bounds";
        let mut task = sample_task_record();
        task.manifest.task_id = task_id.to_owned();
        task.state.task_id = task_id.to_owned();
        task.refs.task_id = task_id.to_owned();
        task.state.active_root_execution_id = Some(execution_id.to_owned());
        task.state.latest_root_execution_id = Some(execution_id.to_owned());
        service
            .reducer
            .reduce_task_created(&task)
            .await
            .expect("task shell");
        service
            .workspace
            .ensure_execution_workspace(scope.principal(), scope.workspace(), task_id, execution_id)
            .await
            .expect("execution workspace");

        let near_limit = ExecutionPipelineRoster {
            schema_version: EXECUTION_PIPELINE_ROSTER_SCHEMA_VERSION,
            stages: vec![PipelineStage {
                agent_id: "bounded-agent".to_string(),
                context: "x".repeat(EXECUTION_PIPELINE_ROSTER_MAX_BYTES - 1024),
                success_criteria: None,
                timeout_secs: None,
            }],
        };
        ArtifactV2Service::validate_pipeline_document_size(
            &near_limit,
            EXECUTION_PIPELINE_ROSTER_MAX_BYTES,
            "execution_pipeline_roster",
        )
        .expect("near-limit compact roster accounts for its JSON envelope");
        let seal = service
            .seal_execution_pipeline_roster(&scope, task_id, execution_id, &near_limit)
            .expect("seal near-limit roster");
        ArtifactV2Service::validate_pipeline_document_size(
            &seal,
            EXECUTION_PIPELINE_ROSTER_SEAL_MAX_BYTES,
            "execution_pipeline_roster_seal",
        )
        .expect("seal bound accounts for embedded-roster and HMAC envelope overhead");

        // Existing pretty-encoded v1 records remain readable; new writers use
        // compact JSON so the pre-write byte calculation equals on-disk bytes.
        let roster_path = service.execution_pipeline_roster_path(&scope, task_id, execution_id);
        service
            .workspace
            .write_json_atomic_path(&roster_path, &near_limit)
            .await
            .expect("write legacy pretty roster");
        assert_eq!(
            service
                .read_pipeline_roster_path(&roster_path)
                .await
                .expect("bounded reader accepts legacy formatting"),
            near_limit
        );

        let oversized = ExecutionPipelineRoster {
            schema_version: EXECUTION_PIPELINE_ROSTER_SCHEMA_VERSION,
            stages: vec![PipelineStage {
                agent_id: "oversized-agent".to_string(),
                context: "x".repeat(EXECUTION_PIPELINE_ROSTER_MAX_BYTES),
                success_criteria: None,
                timeout_secs: None,
            }],
        };
        assert!(ArtifactV2Service::validate_pipeline_document_size(
            &oversized,
            EXECUTION_PIPELINE_ROSTER_MAX_BYTES,
            "execution_pipeline_roster",
        )
        .is_err());

        let progress_path = service.execution_pipeline_progress_path(&scope, task_id, execution_id);
        service
            .workspace
            .create_dir_all_path(progress_path.parent().expect("progress parent"))
            .await
            .expect("restricted progress directory");
        service
            .workspace
            .write_string_atomic_path(
                &progress_path,
                &" ".repeat(EXECUTION_PIPELINE_PROGRESS_MAX_BYTES + 1),
            )
            .await
            .expect("write oversized malformed progress fixture");
        let error = service
            .read_pipeline_progress_path(&progress_path)
            .await
            .expect_err("stream reader rejects bytes before typed deserialize");
        assert!(error.to_string().contains("exceeds its byte limit"));
    }

    /// Once the exact handoff descriptor exists, it is the authoritative child
    /// set and receipt even if Artifact lineage refs were pruned after parent
    /// activation. Crash repair must therefore prepare/consume it with an empty
    /// reconstructed set rather than requiring stale refs to remain present.
    #[test]
    fn stateless_child_handoff_crash_repair_trusts_the_execution_descriptor() {
        let source = include_str!("service.rs");
        let reducer = source
            .split("fn maybe_resume_parent_after_v3_child_results")
            .nth(1)
            .and_then(|tail| tail.split("async fn resolve_scope_for_execution_id").next())
            .expect("parent reducer source window");
        let descriptor = reducer
            .find("has_pending_stateless_children_handoff")
            .expect("durable descriptor check");
        let prepare = reducer[descriptor..]
            .find("prepare_stateless_children_handoff")
            .map(|offset| descriptor + offset)
            .expect("idempotent prepare");
        let empty_children = reducer[prepare..]
            .find("&[]")
            .map(|offset| prepare + offset)
            .expect("descriptor-authoritative empty reconstruction");
        let consume = reducer[empty_children..]
            .find("consume_stateless_children_handoff")
            .map(|offset| empty_children + offset)
            .expect("receipt consumption");
        assert!(descriptor < prepare && prepare < empty_children && empty_children < consume);

        let pipeline_owned = reducer
            .find("ContinuedExecutionOutcome::PipelineOwned")
            .expect("exact checkpoint transferred outcome to outer pipeline");
        let ordinary_root = reducer[pipeline_owned..]
            .find("if let Some(outcome) = outcome {")
            .map(|offset| pipeline_owned + offset)
            .expect("ordinary non-pipeline parent settlement gate");
        let receipt = reducer[pipeline_owned..]
            .find("consume_stateless_children_handoff")
            .map(|offset| pipeline_owned + offset)
            .expect("old child receipt consumption");
        assert!(pipeline_owned < ordinary_root && ordinary_root < receipt);
        assert!(reducer[pipeline_owned..ordinary_root].contains("=> None"));
    }

    /// Recovery classification must ignore orphan journal suffixes. Only the
    /// terminal replayed through the committed state's journal watermark can
    /// authorize an outer pipeline CAS.
    #[test]
    fn pipeline_terminal_adoption_uses_the_committed_journal_watermark() {
        let source = include_str!("service.rs");
        let method = source
            .split("async fn committed_pipeline_segment_terminal")
            .nth(1)
            .and_then(|tail| {
                tail.split("async fn continue_committed_pipeline_execution")
                    .next()
            })
            .expect("terminal adoption source window");
        assert!(method.contains("read_journal_verified"));
        assert!(method.contains("journal.authoritative(committed.state.journal_seq)"));
        assert!(!method.contains("replay(journal.records"));
    }

    /// Once the outer CAS consumes a retired exact segment, a transient root
    /// activation failure must not create a live-process hole: a subsequent
    /// projector pass sees only an advanced cursor and is allowed to receipt
    /// the stale terminal. Install the bounded repair owner before the eager
    /// activation, and have that owner retry activation itself before recovery.
    #[test]
    fn reconciler_pipeline_adoption_closes_post_cas_activation_failure_window() {
        let source = include_str!("service.rs");
        let method = source
            .split("pub(crate) async fn accept_terminal_loop_settlement")
            .nth(1)
            .and_then(|tail| tail.split("async fn resolve_scope_for_execution_id").next())
            .expect("terminal settlement source window");
        let commit = method
            .find("self.commit_pipeline_stage")
            .expect("durable outer CAS");
        let repair = method[commit..]
            .find("schedule_pipeline_continuation_recovery")
            .map(|offset| commit + offset)
            .expect("bounded repair owner");
        let eager_activation = method[repair..]
            .rfind("activate_execution_internal")
            .map(|offset| repair + offset)
            .expect("eager activation after repair installation");
        assert!(commit < repair && repair < eager_activation);
        let coordinator = source
            .split("fn schedule_pipeline_continuation_recovery")
            .nth(1)
            .and_then(|tail| tail.split("fn seal_terminal_settlement_descriptor").next())
            .expect("bounded pipeline repair coordinator");
        assert!(coordinator.contains("spawn_execution_job"));
        assert!(coordinator.contains("activate_execution_internal"));
        assert!(coordinator.contains("recover_interrupted_runtime_execution"));
    }

    /// Cancellation and an already-advanced outer cursor both supersede the
    /// inner terminal's remaining publication work. Either path must retire an
    /// exact protected deliverable sidecar before acknowledging the receipt.
    #[test]
    fn pipeline_terminal_sidecar_is_retired_on_cancellation_and_stale_outer_cursor() {
        let source = include_str!("service.rs");
        let method = source
            .split("pub(crate) async fn accept_terminal_loop_settlement")
            .nth(1)
            .and_then(|tail| tail.split("async fn resolve_scope_for_execution_id").next())
            .expect("terminal settlement source window");

        let cancelled = method
            .find("WaitingState::Cancelled")
            .expect("cancellation supersession");
        let cancellation_retire = method[cancelled..]
            .find("retire_pipeline_terminal_settlement")
            .map(|offset| cancelled + offset)
            .expect("cancellation sidecar retirement");
        let cancellation_ack = method[cancellation_retire..]
            .find("SupersededByCancellation")
            .map(|offset| cancellation_retire + offset)
            .expect("cancellation disposition");
        assert!(cancelled < cancellation_retire && cancellation_retire < cancellation_ack);

        let stale = method
            .find("cursor no longer names this terminal segment")
            .expect("stale outer-cursor branch");
        let stale_retire = method[stale..]
            .find("retire_pipeline_terminal_settlement")
            .map(|offset| stale + offset)
            .expect("stale sidecar retirement");
        let stale_ack = method[stale_retire..]
            .find("TerminalLoopSettlementAcceptance::Publish")
            .map(|offset| stale_retire + offset)
            .expect("stale debt acknowledgement");
        assert!(stale < stale_retire && stale_retire < stale_ack);
    }

