    #[test]
    fn only_the_canonical_root_execution_owns_tree_learning_reflection() {
        let root = sample_execution_record();
        let mut task = sample_task_record();
        task.state.latest_root_execution_id = Some("exec-1".to_string());
        assert!(ArtifactV2Service::terminal_execution_owns_task_learning(
            &task, &root
        ));

        let mut child = root.clone();
        child.state.execution_id = "exec-child".to_string();
        child.state.parent_execution_id = Some("exec-1".to_string());
        child.state.relationship_type = RELATIONSHIP_TYPE_DELEGATE.to_string();
        assert!(!ArtifactV2Service::terminal_execution_owns_task_learning(
            &task, &child
        ));

        let mut corrupted_root = root.clone();
        corrupted_root.state.root_execution_id = Some("exec-other".to_string());
        assert!(!ArtifactV2Service::terminal_execution_owns_task_learning(
            &task,
            &corrupted_root
        ));

        let mut superseded_root = root.clone();
        superseded_root.state.execution_id = "exec-old-root".to_string();
        superseded_root.state.root_execution_id = Some("exec-old-root".to_string());
        assert!(!ArtifactV2Service::terminal_execution_owns_task_learning(
            &task,
            &superseded_root
        ));

        let mut legacy_root = root;
        legacy_root.state.root_execution_id = None;
        assert!(ArtifactV2Service::terminal_execution_owns_task_learning(
            &task,
            &legacy_root
        ));

        task.state.latest_root_execution_id = None;
        task.state.last_completed_root_execution_id = Some("exec-1".to_string());
        assert!(ArtifactV2Service::terminal_execution_owns_task_learning(
            &task,
            &legacy_root
        ));
    }

    #[tokio::test]
    async fn filesystem_event_writer_reuses_sequence_cache_and_resumes_from_disk() {
        let tmp = tempfile::TempDir::new().expect("temp dir");
        let workspace = ArtifactV2Workspace::new(tmp.path().join("magician_data_v3"));
        let ctx = ExecutionContext {
            principal: "anonymous".to_string(),
            workspace: "default".to_string(),
            task_id: "task-seq".to_string(),
            execution_id: "exec-seq".to_string(),
        };

        let writer = FilesystemEventWriter::new(workspace.clone());
        let first = writer
            .append(
                &ctx,
                ArtifactV2EventType::ExecutionProgress,
                json!({"message": "first"}),
            )
            .await
            .expect("first event append");
        let second = writer
            .append(
                &ctx,
                ArtifactV2EventType::ExecutionProgress,
                json!({"message": "second"}),
            )
            .await
            .expect("second event append");

        assert_eq!(first.seq, 1);
        assert_eq!(second.seq, 2);

        let restarted_writer = FilesystemEventWriter::new(workspace.clone());
        let third = restarted_writer
            .append(
                &ctx,
                ArtifactV2EventType::ExecutionProgress,
                json!({"message": "third"}),
            )
            .await
            .expect("third event append after restart");

        assert_eq!(third.seq, 3);

        let events_path = workspace.execution_events_path(
            &ctx.principal,
            &ctx.workspace,
            &ctx.task_id,
            &ctx.execution_id,
        );
        let commit_path = workspace.execution_events_commit_path(
            &ctx.principal,
            &ctx.workspace,
            &ctx.task_id,
            &ctx.execution_id,
        );
        let events = workspace
            .read_committed_jsonl_tail_adaptive_path::<CanonicalEvent, _, _>(
                &events_path,
                &commit_path,
                16,
                EVENT_SEQUENCE_TAIL_MAX_BYTES,
                EVENT_SEQUENCE_RECOVERY_MAX_BYTES,
            )
            .await
            .expect("events should parse")
            .records;
        let seqs = events.iter().map(|event| event.seq).collect::<Vec<_>>();
        assert_eq!(seqs, vec![1, 2, 3]);
    }

    #[test]
    fn event_sequence_cache_is_bounded_across_lifetime_execution_paths() {
        let tmp = tempfile::TempDir::new().expect("temp dir");
        let writer = FilesystemEventWriter::new(ArtifactV2Workspace::new(tmp.path()));
        for index in 0..EVENT_SEQUENCE_CACHE_ENTRY_CAP + 32 {
            writer.cache_seq_cursor(
                &tmp.path().join(format!("exec-{index}.events.jsonl")),
                EventSequenceCursor {
                    next_seq: 2,
                    observed_file_len: 128,
                },
            );
        }
        let cursors = writer
            .next_seq_by_path
            .lock()
            .expect("sequence cursor cache");
        assert!(cursors.len() <= EVENT_SEQUENCE_CACHE_ENTRY_CAP);
        assert!(cursors.contains_key(&tmp.path().join(format!(
            "exec-{}.events.jsonl",
            EVENT_SEQUENCE_CACHE_ENTRY_CAP + 31
        ))));
    }

    struct GatedEventAppendProvider {
        inner: crate::magician_v2::artifact_v2::workspace::LocalFileWorkspaceProvider,
        blocked_task_segment: String,
        block_once: std::sync::atomic::AtomicBool,
        entered: tokio::sync::Notify,
        release: tokio::sync::Notify,
    }

    impl std::fmt::Debug for GatedEventAppendProvider {
        fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            formatter
                .debug_struct("GatedEventAppendProvider")
                .field("root", &self.inner.root())
                .field("blocked_task_segment", &self.blocked_task_segment)
                .finish_non_exhaustive()
        }
    }

    impl GatedEventAppendProvider {
        fn new(root: &Path, blocked_task_id: &str) -> Self {
            Self {
                inner: crate::magician_v2::artifact_v2::workspace::LocalFileWorkspaceProvider::new(
                    root,
                ),
                blocked_task_segment: format!("/{blocked_task_id}/"),
                block_once: std::sync::atomic::AtomicBool::new(true),
                entered: tokio::sync::Notify::new(),
                release: tokio::sync::Notify::new(),
            }
        }

        async fn wait_until_blocked(&self) {
            self.entered.notified().await;
        }

        fn release_blocked_append(&self) {
            self.release.notify_one();
        }
    }

    #[async_trait]
    impl crate::magician_v2::artifact_v2::workspace::WorkspaceFileProvider
        for GatedEventAppendProvider
    {
        fn id(&self) -> &'static str {
            "gated_event_append_test"
        }

        fn root(&self) -> &Path {
            self.inner.root()
        }

        fn resolve_path(&self, relative_path: &Path) -> PathBuf {
            self.inner.resolve_path(relative_path)
        }

        async fn append(&self, relative_path: &Path, bytes: &[u8]) -> Result<(), ArtifactV2Error> {
            let normalized = format!("/{}", relative_path.to_string_lossy());
            if normalized.contains(&self.blocked_task_segment)
                && self
                    .block_once
                    .swap(false, std::sync::atomic::Ordering::AcqRel)
            {
                self.entered.notify_one();
                self.release.notified().await;
            }
            self.inner.append(relative_path, bytes).await
        }
    }

    #[derive(Clone, Copy, Debug)]
    enum InjectedEventAppendFailure {
        Write,
        Flush,
        Fsync,
    }

    struct FailingEventAppendProvider {
        inner: crate::magician_v2::artifact_v2::workspace::LocalFileWorkspaceProvider,
        failure: InjectedEventAppendFailure,
        fail_once: std::sync::atomic::AtomicBool,
    }

    impl std::fmt::Debug for FailingEventAppendProvider {
        fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            formatter
                .debug_struct("FailingEventAppendProvider")
                .field("root", &self.inner.root())
                .field("failure", &self.failure)
                .finish_non_exhaustive()
        }
    }

    impl FailingEventAppendProvider {
        fn new(root: &Path, failure: InjectedEventAppendFailure) -> Self {
            Self {
                inner: crate::magician_v2::artifact_v2::workspace::LocalFileWorkspaceProvider::new(
                    root,
                ),
                failure,
                fail_once: std::sync::atomic::AtomicBool::new(true),
            }
        }

        fn injected_error(&self) -> ArtifactV2Error {
            ArtifactV2Error::Io(std::io::Error::new(
                std::io::ErrorKind::Other,
                format!("injected {:?} failure", self.failure),
            ))
        }
    }

    #[async_trait]
    impl crate::magician_v2::artifact_v2::workspace::WorkspaceFileProvider
        for FailingEventAppendProvider
    {
        fn id(&self) -> &'static str {
            "failing_event_append_test"
        }

        fn root(&self) -> &Path {
            self.inner.root()
        }

        fn resolve_path(&self, relative_path: &Path) -> PathBuf {
            self.inner.resolve_path(relative_path)
        }

        async fn append(&self, relative_path: &Path, bytes: &[u8]) -> Result<(), ArtifactV2Error> {
            if !self
                .fail_once
                .swap(false, std::sync::atomic::Ordering::AcqRel)
            {
                return self.inner.append(relative_path, bytes).await;
            }
            match self.failure {
                InjectedEventAppendFailure::Write => {
                    let partial_len = bytes.len().saturating_sub(1).max(1);
                    self.inner
                        .append(relative_path, &bytes[..partial_len])
                        .await?;
                },
                InjectedEventAppendFailure::Flush => {
                    use tokio::io::AsyncWriteExt;
                    let path = self.resolve_path(relative_path);
                    if let Some(parent) = path.parent() {
                        tokio::fs::create_dir_all(parent).await?;
                    }
                    let mut file = tokio::fs::OpenOptions::new()
                        .create(true)
                        .append(true)
                        .open(path)
                        .await?;
                    file.write_all(bytes).await?;
                    // Drop without an explicit flush or fsync, then report the
                    // injected flush failure after the newline was visible.
                },
                InjectedEventAppendFailure::Fsync => {
                    use tokio::io::AsyncWriteExt;
                    let path = self.resolve_path(relative_path);
                    if let Some(parent) = path.parent() {
                        tokio::fs::create_dir_all(parent).await?;
                    }
                    let mut file = tokio::fs::OpenOptions::new()
                        .create(true)
                        .append(true)
                        .open(path)
                        .await?;
                    file.write_all(bytes).await?;
                    file.flush().await?;
                    // Report failure at the fsync boundary with a complete
                    // newline-terminated record still in the physical file.
                },
            }
            Err(self.injected_error())
        }
    }

    struct UncertainCommitMarkerProvider {
        inner: crate::magician_v2::artifact_v2::workspace::LocalFileWorkspaceProvider,
        atomic_writes: std::sync::atomic::AtomicUsize,
        fail_publish_read: bool,
    }

    impl std::fmt::Debug for UncertainCommitMarkerProvider {
        fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            formatter
                .debug_struct("UncertainCommitMarkerProvider")
                .field("root", &self.inner.root())
                .finish_non_exhaustive()
        }
    }

    #[async_trait]
    impl crate::magician_v2::artifact_v2::workspace::WorkspaceFileProvider
        for UncertainCommitMarkerProvider
    {
        fn id(&self) -> &'static str {
            "uncertain_commit_marker_test"
        }

        fn root(&self) -> &Path {
            self.inner.root()
        }

        fn resolve_path(&self, relative_path: &Path) -> PathBuf {
            self.inner.resolve_path(relative_path)
        }

        async fn read_prefix(
            &self,
            relative_path: &Path,
            max_bytes: u64,
        ) -> Result<Vec<u8>, ArtifactV2Error> {
            if self.fail_publish_read {
                return Err(ArtifactV2Error::Io(std::io::Error::other(
                    "injected post-marker-rename read failure",
                )));
            }
            self.inner.read_prefix(relative_path, max_bytes).await
        }

        async fn write_atomic(
            &self,
            relative_path: &Path,
            bytes: &[u8],
        ) -> Result<(), ArtifactV2Error> {
            self.inner.write_atomic(relative_path, bytes).await?;
            let write_index = self
                .atomic_writes
                .fetch_add(1, std::sync::atomic::Ordering::AcqRel);
            if write_index == 0 {
                return Ok(());
            }
            Err(ArtifactV2Error::Io(std::io::Error::other(
                "injected post-marker-rename parent sync failure",
            )))
        }

        async fn sync_file_and_parent(&self, _relative_path: &Path) -> Result<(), ArtifactV2Error> {
            Err(ArtifactV2Error::Io(std::io::Error::other(
                "injected repeated parent sync failure",
            )))
        }
    }

    #[tokio::test]
    async fn uncertain_event_append_failures_remain_uncommitted_and_retry_once_after_reopen() {
        for failure in [
            InjectedEventAppendFailure::Write,
            InjectedEventAppendFailure::Flush,
            InjectedEventAppendFailure::Fsync,
        ] {
            let tmp = tempfile::TempDir::new().expect("temp dir");
            let provider = Arc::new(FailingEventAppendProvider::new(tmp.path(), failure));
            let workspace = ArtifactV2Workspace::with_file_provider(provider);
            let ctx = ExecutionContext {
                principal: "anonymous".to_string(),
                workspace: "default".to_string(),
                task_id: "task-uncertain-append".to_string(),
                execution_id: "exec-uncertain-append".to_string(),
            };
            let writer = FilesystemEventWriter::new(workspace.clone());
            writer
                .append(
                    &ctx,
                    ArtifactV2EventType::ExecutionProgress,
                    json!({"attempt": "logical-once"}),
                )
                .await
                .expect_err("injected append stage must remain unacknowledged");

            let events_path = workspace.execution_events_path(
                &ctx.principal,
                &ctx.workspace,
                &ctx.task_id,
                &ctx.execution_id,
            );
            let commit_path = workspace.execution_events_commit_path(
                &ctx.principal,
                &ctx.workspace,
                &ctx.task_id,
                &ctx.execution_id,
            );
            let before_retry = workspace
                .read_committed_jsonl_tail_adaptive_path::<CanonicalEvent, _, _>(
                    &events_path,
                    &commit_path,
                    4,
                    EVENT_SEQUENCE_TAIL_MAX_BYTES,
                    EVENT_SEQUENCE_RECOVERY_MAX_BYTES,
                )
                .await
                .expect("uncertain physical suffix is hidden by commit authority");
            assert!(before_retry.records.is_empty(), "failure={failure:?}");

            let reopened_workspace = ArtifactV2Workspace::new(tmp.path());
            let reopened_writer = FilesystemEventWriter::new(reopened_workspace.clone());
            let retried = reopened_writer
                .append(
                    &ctx,
                    ArtifactV2EventType::ExecutionProgress,
                    json!({"attempt": "logical-once"}),
                )
                .await
                .expect("reopen truncates uncertain suffix and retry commits");
            assert_eq!(retried.seq, 1, "failure={failure:?}");

            let committed = reopened_workspace
                .read_committed_jsonl_tail_adaptive_path::<CanonicalEvent, _, _>(
                    &events_path,
                    &commit_path,
                    4,
                    EVENT_SEQUENCE_TAIL_MAX_BYTES,
                    EVENT_SEQUENCE_RECOVERY_MAX_BYTES,
                )
                .await
                .expect("committed retry history");
            assert_eq!(committed.records.len(), 1, "failure={failure:?}");
            assert_eq!(committed.records[0].seq, 1, "failure={failure:?}");
            assert_eq!(
                committed.records[0].payload["attempt"], "logical-once",
                "failure={failure:?}"
            );
        }
    }

    #[tokio::test]
    async fn advanced_marker_with_repeated_sync_failure_is_typed_commit_uncertain_after_reopen() {
        let tmp = tempfile::TempDir::new().expect("temp dir");
        let provider = Arc::new(UncertainCommitMarkerProvider {
            inner: crate::magician_v2::artifact_v2::workspace::LocalFileWorkspaceProvider::new(
                tmp.path(),
            ),
            atomic_writes: std::sync::atomic::AtomicUsize::new(0),
            fail_publish_read: false,
        });
        let workspace = ArtifactV2Workspace::with_file_provider(provider);
        let ctx = ExecutionContext {
            principal: "anonymous".to_string(),
            workspace: "default".to_string(),
            task_id: "task-uncertain-marker".to_string(),
            execution_id: "exec-uncertain-marker".to_string(),
        };
        let writer = FilesystemEventWriter::new(workspace.clone());
        let error = writer
            .append(
                &ctx,
                ArtifactV2EventType::ExecutionProgress,
                json!({"attempt": "logical-once"}),
            )
            .await
            .expect_err("advanced but not durably confirmed marker is not an ordinary failure");
        assert!(matches!(
            error,
            ArtifactV2Error::CommitUncertain { committed_len, .. } if committed_len > 0
        ));

        // The typed result tells callers not to retry. Reopening with the
        // normal provider must expose exactly the already-authorized record.
        let reopened = ArtifactV2Workspace::new(tmp.path());
        let events_path = reopened.execution_events_path(
            &ctx.principal,
            &ctx.workspace,
            &ctx.task_id,
            &ctx.execution_id,
        );
        let commit_path = reopened.execution_events_commit_path(
            &ctx.principal,
            &ctx.workspace,
            &ctx.task_id,
            &ctx.execution_id,
        );
        let committed = reopened
            .read_committed_jsonl_tail_adaptive_path::<CanonicalEvent, _, _>(
                &events_path,
                &commit_path,
                4,
                EVENT_SEQUENCE_TAIL_MAX_BYTES,
                EVENT_SEQUENCE_RECOVERY_MAX_BYTES,
            )
            .await
            .expect("reopened committed history");
        assert_eq!(committed.records.len(), 1);
        assert_eq!(committed.records[0].seq, 1);
        assert_eq!(committed.records[0].payload["attempt"], "logical-once");
    }

