    #[tokio::test]
    async fn durable_append_for_one_task_does_not_block_an_unrelated_task() {
        let tmp = tempfile::TempDir::new().expect("temp dir");
        let provider = Arc::new(GatedEventAppendProvider::new(tmp.path(), "task-a"));
        let workspace = ArtifactV2Workspace::with_file_provider(provider.clone());
        let writer = Arc::new(FilesystemEventWriter::new(workspace));
        let context = |task_id: &str| ExecutionContext {
            principal: "anonymous".to_string(),
            workspace: "default".to_string(),
            task_id: task_id.to_string(),
            execution_id: format!("exec-{task_id}"),
        };

        let writer_a = Arc::clone(&writer);
        let ctx_a = context("task-a");
        let blocked = tokio::spawn(async move {
            writer_a
                .append(
                    &ctx_a,
                    ArtifactV2EventType::ExecutionProgress,
                    json!({"task": "a"}),
                )
                .await
        });
        provider.wait_until_blocked().await;

        let unrelated = tokio::time::timeout(
            Duration::from_millis(250),
            writer.append(
                &context("task-b"),
                ArtifactV2EventType::ExecutionProgress,
                json!({"task": "b"}),
            ),
        )
        .await
        .expect("task B must not wait behind task A fsync")
        .expect("task B durable append");
        assert_eq!(unrelated.seq, 1);

        provider.release_blocked_append();
        let blocked = blocked
            .await
            .expect("task A append task")
            .expect("task A append");
        assert_eq!(blocked.seq, 1);
    }

    #[tokio::test]
    async fn runtime_event_sink_does_not_reintroduce_cross_task_fsync_blocking() {
        let tmp = tempfile::TempDir::new().expect("temp dir");
        let provider = Arc::new(GatedEventAppendProvider::new(tmp.path(), "task-a"));
        let workspace = ArtifactV2Workspace::with_file_provider(provider.clone());
        let writer: Arc<dyn CanonicalEventWriter> =
            Arc::new(FilesystemEventWriter::new(workspace.clone()));
        let sink = FilesystemRuntimeEventSink::new(writer);
        let scope = |task_id: &str| CanonicalEventScope {
            principal: "anonymous".to_string(),
            workspace: "default".to_string(),
            task_id: task_id.to_string(),
            execution_id: format!("exec-{task_id}"),
            ui_thread_id: "general".to_string(),
        };

        sink.emit(
            scope("task-a"),
            ArtifactV2EventType::ExecutionProgress,
            json!({"task": "a"}),
        );
        provider.wait_until_blocked().await;
        sink.emit(
            scope("task-b"),
            ArtifactV2EventType::ExecutionProgress,
            json!({"task": "b"}),
        );

        let task_b_events =
            workspace.execution_events_path("anonymous", "default", "task-b", "exec-task-b");
        tokio::time::timeout(Duration::from_secs(1), async {
            loop {
                if workspace
                    .symlink_metadata_path(&task_b_events)
                    .await
                    .expect("task B event metadata")
                    .is_some()
                {
                    break;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("task B runtime event must not wait behind task A fsync");
        provider.release_blocked_append();
        let task_a_events =
            workspace.execution_events_path("anonymous", "default", "task-a", "exec-task-a");
        tokio::time::timeout(Duration::from_secs(1), async {
            loop {
                if workspace
                    .symlink_metadata_path(&task_a_events)
                    .await
                    .expect("task A event metadata")
                    .is_some()
                {
                    break;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("task A runtime event drains after its fsync gate opens");
    }

    #[tokio::test]
    async fn cancelled_pre_durable_append_does_not_advance_sequence_cache() {
        let tmp = tempfile::TempDir::new().expect("temp dir");
        let provider = Arc::new(GatedEventAppendProvider::new(tmp.path(), "task-cancel"));
        let workspace = ArtifactV2Workspace::with_file_provider(provider.clone());
        let writer = Arc::new(FilesystemEventWriter::new(workspace));
        let ctx = ExecutionContext {
            principal: "anonymous".to_string(),
            workspace: "default".to_string(),
            task_id: "task-cancel".to_string(),
            execution_id: "exec-cancel".to_string(),
        };
        let first_writer = Arc::clone(&writer);
        let first_ctx = ctx.clone();
        let first = tokio::spawn(async move {
            first_writer
                .append(
                    &first_ctx,
                    ArtifactV2EventType::ExecutionProgress,
                    json!({"attempt": 1}),
                )
                .await
        });
        provider.wait_until_blocked().await;
        first.abort();
        assert!(first
            .await
            .expect_err("first append is cancelled")
            .is_cancelled());

        let retried = writer
            .append(
                &ctx,
                ArtifactV2EventType::ExecutionProgress,
                json!({"attempt": 2}),
            )
            .await
            .expect("retry append");
        assert_eq!(retried.seq, 1);
    }

    #[tokio::test]
    async fn canonical_event_writer_repairs_unterminated_fragment_before_retry_append() {
        let tmp = tempfile::TempDir::new().expect("temp dir");
        let workspace = ArtifactV2Workspace::new(tmp.path());
        let writer = FilesystemEventWriter::new(workspace.clone());
        let ctx = ExecutionContext {
            principal: "anonymous".to_string(),
            workspace: "default".to_string(),
            task_id: "task-fragment-repair".to_string(),
            execution_id: "exec-fragment-repair".to_string(),
        };
        let first = writer
            .append(
                &ctx,
                ArtifactV2EventType::ExecutionProgress,
                json!({"attempt": 1}),
            )
            .await
            .expect("first durable event");
        assert_eq!(first.seq, 1);

        let events_path = workspace.execution_events_path(
            &ctx.principal,
            &ctx.workspace,
            &ctx.task_id,
            &ctx.execution_id,
        );
        workspace
            .append_path(&events_path, br#"{"partial":"#)
            .await
            .expect("simulate cancelled partial append");

        let retried = writer
            .append(
                &ctx,
                ArtifactV2EventType::ExecutionProgress,
                json!({"attempt": 2}),
            )
            .await
            .expect("retry repairs fragment then appends");
        assert_eq!(retried.seq, 2);

        let events = workspace
            .read_jsonl_path::<CanonicalEvent, _>(&events_path)
            .await
            .expect("history remains valid JSONL after repair");
        assert_eq!(events.len(), 2);
        assert_eq!(
            events.iter().map(|event| event.seq).collect::<Vec<_>>(),
            vec![1, 2]
        );
        assert_eq!(events[1].payload["attempt"], 2);
    }

