    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn runtime_event_sink_applies_bounded_backpressure_without_dropping_events() {
        let tmp = tempfile::TempDir::new().expect("temp dir");
        let provider = Arc::new(GatedEventAppendProvider::new(tmp.path(), "task-bounded"));
        let workspace = ArtifactV2Workspace::with_file_provider(provider.clone());
        let writer: Arc<dyn CanonicalEventWriter> =
            Arc::new(FilesystemEventWriter::new(workspace.clone()));
        let sink = Arc::new(FilesystemRuntimeEventSink::new_with_limits(
            writer,
            2,
            1024 * 1024,
            1,
        ));
        let scope = CanonicalEventScope {
            principal: "anonymous".to_string(),
            workspace: "default".to_string(),
            task_id: "task-bounded".to_string(),
            execution_id: "exec-bounded".to_string(),
            ui_thread_id: "general".to_string(),
        };
        sink.emit(
            scope.clone(),
            ArtifactV2EventType::ExecutionProgress,
            json!({"index": 0}),
        );
        provider.wait_until_blocked().await;
        sink.emit(
            scope.clone(),
            ArtifactV2EventType::ExecutionProgress,
            json!({"index": 1}),
        );

        let third_finished = Arc::new(std::sync::atomic::AtomicBool::new(false));
        let thread_sink = Arc::clone(&sink);
        let thread_scope = scope.clone();
        let thread_finished = Arc::clone(&third_finished);
        let third = std::thread::spawn(move || {
            thread_sink.emit(
                thread_scope,
                ArtifactV2EventType::ExecutionProgress,
                json!({"index": 2}),
            );
            thread_finished.store(true, Ordering::Release);
        });
        tokio::time::sleep(Duration::from_millis(25)).await;
        assert!(!third_finished.load(Ordering::Acquire));

        provider.release_blocked_append();
        tokio::task::spawn_blocking(move || third.join().expect("third emitter"))
            .await
            .expect("join bounded emitter");

        let events_path = workspace.execution_events_path(
            &scope.principal,
            &scope.workspace,
            &scope.task_id,
            &scope.execution_id,
        );
        let events = tokio::time::timeout(Duration::from_secs(2), async {
            loop {
                if let Ok(events) = workspace
                    .read_jsonl_path::<CanonicalEvent, _>(&events_path)
                    .await
                {
                    if events.len() == 3 {
                        break events;
                    }
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("all saturated events remain durable");
        assert_eq!(
            events
                .iter()
                .filter_map(|event| event.payload["index"].as_u64())
                .collect::<Vec<_>>(),
            vec![0, 1, 2]
        );
    }

    #[test]
    fn runtime_event_worker_exit_closes_ingress_and_unblocks_waiting_emitters() {
        let ingress = Arc::new(RuntimeEventIngress::new(1, 1024));
        let event = |index| QueuedRuntimeEvent {
            scope: CanonicalEventScope {
                principal: "anonymous".to_string(),
                workspace: "default".to_string(),
                task_id: "task-worker-exit".to_string(),
                execution_id: "exec-worker-exit".to_string(),
                ui_thread_id: "general".to_string(),
            },
            event_type: ArtifactV2EventType::ExecutionProgress,
            payload: json!({"index": index}),
            retained_bytes: 128,
            completion: None,
        };
        assert!(ingress.push(event(0)).is_ok(), "fill bounded ingress");

        let (started_tx, started_rx) = std::sync::mpsc::sync_channel(0);
        let (finished_tx, finished_rx) = std::sync::mpsc::sync_channel(0);
        let blocked_ingress = Arc::clone(&ingress);
        let blocked = std::thread::spawn(move || {
            started_tx.send(()).expect("announce blocked emitter");
            let rejected = blocked_ingress.push(event(1)).is_err();
            finished_tx
                .send(rejected)
                .expect("report blocked emitter result");
        });
        started_rx.recv().expect("blocked emitter started");

        drop(RuntimeEventWorkerLifetimeGuard {
            ingress: Arc::clone(&ingress),
            drained_cleanly: false,
        });

        assert!(finished_rx
            .recv_timeout(Duration::from_secs(1))
            .expect("worker exit must wake blocked emitter"));
        blocked.join().expect("blocked emitter exits cleanly");
    }

