        let record = json!({
            "artifact_id": "downloaded_file:rows",
            "artifact_type": "downloaded_file",
            "content_type": "application/json",
            "produced_at": "2026-05-22T00:00:00Z",
            "payload": {
                "artifact_kind": "downloaded_file",
                "file_name": "rows.csv",
                "absolute_path": csv_path.to_string_lossy(),
                "relative_path": "chain/rows.csv",
                "mime_type": "text/csv",
                "size_bytes": 24
            }
        });

        let index = build_continuation_artifact_index(&[record]).await;
        assert_eq!(index.len(), 1);
        let entry = &index[0];
        assert_eq!(entry["content_type"], "text/csv");
        assert_eq!(
            entry["paths"]["absolute_path"].as_str(),
            Some(csv_path.to_string_lossy().as_ref())
        );
        assert_eq!(entry["paths"]["relative_path"], "chain/rows.csv");
