    #[test]
    fn scheduled_task_routine_result_payload_requires_terminal_scheduled_task() {
        let scope = ScopeRef::system_internal_unauthenticated(
            &"anonymous".to_string(),
            &"default".to_string(),
        );
        let mut task = sample_task_record();
        let execution = sample_execution_record();
        let outcome = ExecutionOutcomeSnapshot {
            execution_status: "completed".to_string(),
            task_status: "completed".to_string(),
            outcome_type: "goal_reached".to_string(),
            outcome_summary: "Morning briefing published.".to_string(),
            iterations_used: Some(7),
            is_terminal: true,
            completion_kind: None,
            open_items: Vec::new(),
        };

        assert!(
            scheduled_task_routine_result_payload(&scope, &task, &execution, &outcome, None)
                .is_none(),
            "unscheduled terminal tasks should remain ordinary task outcomes"
        );

        task.manifest.schedule = Some(json!({
            "kind": "cron",
            "cron": "0 8 * * *",
        }));
        task.state.status = "completed".to_string();
        task.state.schedule_fire_count = 3;

        let payload = scheduled_task_routine_result_payload(
            &scope,
            &task,
            &execution,
            &outcome,
            Some("Final user-facing summary."),
        )
        .expect("scheduled terminal task should publish a routine result payload");
        assert_eq!(payload["source"], json!("scheduled_task"));
        assert_eq!(payload["routine_id"], json!("task-1"));
        assert_eq!(payload["task_id"], json!("task-1"));
        assert_eq!(payload["principal"], json!("anonymous"));
        assert_eq!(payload["workspace"], json!("default"));
        assert_eq!(payload["ui_thread_id"], json!("general"));
        assert_eq!(payload["title"], json!("Task"));
        assert_eq!(payload["summary"], json!("Final user-facing summary."));
        assert_eq!(payload["feed_status"], json!("done"));
        assert_eq!(payload["outcome"], json!("goal_reached"));
        assert_eq!(payload["execution_id"], json!("exec-1"));
        assert_eq!(payload["root_execution_id"], json!("exec-1"));
        assert_eq!(payload["completed_at"], json!(1_775_347_500_000i64));
        assert_eq!(payload["schedule_fire_count"], json!(3));
        assert_eq!(payload["schedule"]["cron"], json!("0 8 * * *"));
    }

