    async fn persist_task_plan_fixture(
        service: &ArtifactV2Service,
        scope: &ScopeRef,
        task: &TaskRecord,
        plan_id: &str,
        status: TaskPlanStatus,
        plan_graph: &PlanGraph,
    ) -> TaskPlanRecord {
        let now = "2026-04-10T00:00:00Z".to_string();
        let plan = TaskPlanRecord {
            plan_id: plan_id.to_string(),
            task_id: task.manifest.task_id.clone(),
            agent_id: task.manifest.agent_id.clone(),
            status: status.clone(),
            planning_execution_id: None,
            planning_recovery: None,
            plan_graph: Some(plan_graph.clone()),
            query_analysis: None,
            slot_graph_snapshot: None,
            strategy_attempts: Vec::new(),
            clarification_history: Vec::new(),
            pending_questions: Vec::new(),
            error: None,
            created_at: now.clone(),
            updated_at: now.clone(),
        };
        service
            .persist_task_plan_record(scope, &task.manifest.task_id, &plan)
            .await
            .expect("task plan fixture should persist");

        let mut index = ArtifactV2Service::default_task_plan_index(&task.manifest.task_id);
        index.latest_plan_id = Some(plan.plan_id.clone());
        index.approved_plan_id =
            matches!(status, TaskPlanStatus::Approved).then(|| plan.plan_id.clone());
        index.plans.push(TaskPlanIndexEntry {
            plan_id: plan.plan_id.clone(),
            status,
            created_at: now.clone(),
            updated_at: now.clone(),
        });
        index.updated_at = Some(now);
        service
            .persist_task_plan_index(scope, &task.manifest.task_id, &index)
            .await
            .expect("task plan index fixture should persist");

        plan
    }

