    fn scheduled_task_input(scope: &ScopeRef, at: DateTime<Utc>) -> CreateTaskInput {
        let schedule = TaskSchedule {
            kind: TaskScheduleKind::Once { at },
            timezone: None,
            missed_fire_policy: Default::default(),
            concurrent_execution_policy: Default::default(),
            execution_history_retention: None,
            max_runs: Some(1),
            paused: None,
        };
        CreateTaskInput {
            principal: scope.principal().to_string(),
            workspace: scope.workspace().to_string(),
            title: "Scheduled acceptance fixture".to_string(),
            description: "Verifies durable schedule fire acceptance".to_string(),
            agent_id: "personal-assistant".to_string(),
            goal_id: None,
            ui_thread_id: "general".to_string(),
            priority: None,
            due_date: None,
            tags: Vec::new(),
            created_by: "user".to_string(),
            depends_on: Vec::new(),
            approved: true,
            schedule: Some(serde_json::to_value(schedule).expect("schedule serializes")),
            output_mode: TaskOutputMode::Accumulate,
            chat_session_id: None,
            lifecycle: crate::magician_v2::artifact_v2::models::TaskLifecycle::default(),
            sync_mode: crate::magician_v2::artifact_v2::models::TaskSyncMode::default(),
        }
    }

    #[tokio::test]
    async fn scheduled_fire_count_changes_only_with_durable_acceptance_and_deduplicates() {
        let tmp = tempfile::TempDir::new().expect("temp dir");
        let service = build_test_artifact_v2_service_with_router(tmp.path());
        let scope = ScopeRef::system_internal_unauthenticated(
            &"principal".to_string(),
            &"workspace".to_string(),
        );
        let at = Utc::now();
        let task = service
            .create_task(scheduled_task_input(&scope, at))
            .await
            .expect("task created");

        // A pre-acceptance gate failure leaves both count and execution absent.
        assert!(service
            .accept_scheduled_execution(&scope, &task.manifest.task_id, at)
            .await
            .expect("ineligible fire check")
            .is_none());
        assert_eq!(
            service
                .get_task(&scope, &task.manifest.task_id)
                .await
                .unwrap()
                .state
                .schedule_fire_count,
            0
        );

        service
            .update_task_status(&scope, &task.manifest.task_id, "ready")
            .await
            .expect("task ready");
        let accepted = service
            .accept_scheduled_execution(&scope, &task.manifest.task_id, at)
            .await
            .expect("fire acceptance")
            .expect("fire accepted");
        assert_eq!(accepted.fire_count, 1);
        assert!(accepted.newly_accepted);

        let duplicate = service
            .accept_scheduled_execution(&scope, &task.manifest.task_id, at)
            .await
            .expect("duplicate acceptance")
            .expect("existing acceptance returned");
        assert_eq!(duplicate.execution_id, accepted.execution_id);
        assert_eq!(duplicate.fire_count, 1);
        assert!(!duplicate.newly_accepted);
        assert_eq!(
            service
                .list_executions(&scope, &task.manifest.task_id)
                .await
                .unwrap()
                .len(),
            1
        );
    }

    #[tokio::test]
    async fn schedule_pause_after_acceptance_prevents_launch() {
        let tmp = tempfile::TempDir::new().expect("temp dir");
        let service = build_test_artifact_v2_service_with_router(tmp.path());
        let scope = ScopeRef::system_internal_unauthenticated(
            &"principal".to_string(),
            &"workspace".to_string(),
        );
        let at = Utc::now();
        let task = service
            .create_task(scheduled_task_input(&scope, at))
            .await
            .expect("task created");
        service
            .update_task_status(&scope, &task.manifest.task_id, "ready")
            .await
            .expect("task ready");
        let accepted = service
            .accept_scheduled_execution(&scope, &task.manifest.task_id, at)
            .await
            .unwrap()
            .unwrap();

        let mut paused_schedule: TaskSchedule = serde_json::from_value(
            service
                .get_task(&scope, &task.manifest.task_id)
                .await
                .unwrap()
                .manifest
                .schedule
                .unwrap(),
        )
        .unwrap();
        paused_schedule.paused = Some(true);
        service
            .update_task(
                &scope,
                &task.manifest.task_id,
                UpdateTaskInput {
                    schedule: Some(Some(serde_json::to_value(paused_schedule).unwrap())),
                    ..Default::default()
                },
            )
            .await
            .expect("schedule paused");

        assert!(!service
            .launch_accepted_scheduled_execution(
                &scope,
                &task.manifest.task_id,
                &accepted.execution_id,
            )
            .await
            .expect("launch gate"));
    }

