    #[tokio::test]
    async fn plan_only_progress_projection_tracks_authoritative_hitl_lifecycle() {
        let tmp = tempfile::TempDir::new().expect("temp dir");
        let service = build_test_artifact_v2_service(tmp.path());
        let scope = ScopeRef::system_internal_unauthenticated(
            &"principal".to_string(),
            &"workspace".to_string(),
        );
        let task = service
            .create_task(CreateTaskInput {
                principal: scope.principal().to_string(),
                workspace: scope.workspace().to_string(),
                title: "Plan-only Attention task".to_string(),
                description: "No normal execution tree exists yet".to_string(),
                agent_id: "personal-assistant".to_string(),
                goal_id: None,
                ui_thread_id: "planning-thread".to_string(),
                priority: None,
                due_date: None,
                tags: Vec::new(),
                created_by: "user".to_string(),
                depends_on: Vec::new(),
                approved: true,
                schedule: None,
                output_mode: TaskOutputMode::Accumulate,
                chat_session_id: None,
                lifecycle: crate::magician_v2::artifact_v2::models::TaskLifecycle::default(),
                sync_mode: crate::magician_v2::artifact_v2::models::TaskSyncMode::default(),
            })
            .await
            .expect("task created");
        let mut plan = persist_task_plan_fixture(
            service.as_ref(),
            &scope,
            &task,
            "plan-attention-lifecycle",
            TaskPlanStatus::Eliciting,
            &sample_plan_graph(&task.manifest.title),
        )
        .await;
        plan.planning_execution_id = Some("planexec-attention-lifecycle".to_string());
        plan.pending_questions = vec![sample_recommended_question(
            "question-attention-lifecycle",
            "Which audience should this target?",
            0.9,
        )];
        service
            .persist_task_plan_record(&scope, &task.manifest.task_id, &plan)
            .await
            .expect("elicitation persists");

        let eliciting = service
            .get_task_progress_projection(&scope, &task.manifest.task_id)
            .await
            .expect("plan-only elicitation projects");
        assert!(eliciting.execution.is_none());
        let clarification = eliciting
            .attention
            .iter()
            .find(|summary| summary.source.as_deref() == Some("clarification"))
            .expect("clarification appears without an execution-tree node");
        assert_eq!(
            clarification.pause_state_id.as_deref(),
            Some("question-attention-lifecycle")
        );
        assert_eq!(clarification.execution_id, "planexec-attention-lifecycle");

        plan.status = TaskPlanStatus::Draft;
        plan.pending_questions.clear();
        plan.updated_at = "2026-04-10T00:01:00Z".to_string();
        service
            .persist_task_plan_record(&scope, &task.manifest.task_id, &plan)
            .await
            .expect("draft persists");
        let draft = service
            .get_task_progress_projection(&scope, &task.manifest.task_id)
            .await
            .expect("draft projects");
        assert!(draft
            .attention
            .iter()
            .any(|summary| summary.source.as_deref() == Some("plan_approval")));
        assert!(!draft
            .attention
            .iter()
            .any(|summary| summary.source.as_deref() == Some("clarification")));

        plan.status = TaskPlanStatus::Approved;
        plan.updated_at = "2026-04-10T00:02:00Z".to_string();
        service
            .persist_task_plan_record(&scope, &task.manifest.task_id, &plan)
            .await
            .expect("approval persists");
        let approved = service
            .get_task_progress_projection(&scope, &task.manifest.task_id)
            .await
            .expect("approved plan projects");
        assert!(!approved.attention.iter().any(|summary| matches!(
            summary.source.as_deref(),
            Some("clarification") | Some("plan_approval")
        )));
    }

