    #[tokio::test]
    async fn start_task_planning_returns_without_reentrant_task_lock_deadlock() {
        let tmp = tempfile::TempDir::new().expect("temp dir");
        let service = build_test_artifact_v2_service(tmp.path());
        let scope = ScopeRef::system_internal_unauthenticated(
            &"principal".to_string(),
            &"workspace".to_string(),
        );
        let task = service
            .create_task(CreateTaskInput {
                principal: scope.principal().to_string(),
                workspace: scope.workspace().to_string(),
                title: "Pre-plan without freezing".to_string(),
                description: "Starting a plan should not re-enter the task file lock".to_string(),
                agent_id: "personal-assistant".to_string(),
                goal_id: None,
                ui_thread_id: "general".to_string(),
                priority: None,
                due_date: None,
                tags: Vec::new(),
                created_by: "user".to_string(),
                depends_on: Vec::new(),
                approved: true,
                schedule: None,
                output_mode: TaskOutputMode::Accumulate,
                chat_session_id: None,
                lifecycle: crate::magician_v2::artifact_v2::models::TaskLifecycle::default(),
                sync_mode: crate::magician_v2::artifact_v2::models::TaskSyncMode::default(),
            })
            .await
            .expect("task created");
        // The harness already activated this scope (test_support::
        // activate_conventional_test_scopes_sync). Sealing again under a
        // different deployment id is refused by design -- the cutover is
        // irreversible and single-owner -- so this test no longer seals.

        let plan = tokio::time::timeout(
            std::time::Duration::from_secs(2),
            service.start_task_planning(scope.clone(), task.manifest.task_id.clone()),
        )
        .await
        .expect("start_task_planning should not deadlock on its own task lock")
        .expect("planning should start");

        assert_eq!(plan.status, TaskPlanStatus::Planning);
        assert_eq!(plan.task_id, task.manifest.task_id);

        let task_after = service
            .get_task(&scope, &task.manifest.task_id)
            .await
            .expect("task should remain readable after planning admission");
        assert_eq!(task_after.state.status, "planning");
    }

    #[tokio::test]
    async fn run_task_planning_uses_requested_plan_id_and_ignores_terminal_plan() {
        let tmp = tempfile::TempDir::new().expect("temp dir");
        let service = build_test_artifact_v2_service(tmp.path());
        let scope = ScopeRef::system_internal_unauthenticated(
            &"principal".to_string(),
            &"workspace".to_string(),
        );
        let task = service
            .create_task(CreateTaskInput {
                principal: scope.principal().to_string(),
                workspace: scope.workspace().to_string(),
                title: "Replan race guard".to_string(),
                description: "Old rejected plans should not drive the latest planning execution"
                    .to_string(),
                agent_id: "personal-assistant".to_string(),
                goal_id: None,
                ui_thread_id: "general".to_string(),
                priority: None,
                due_date: None,
                tags: Vec::new(),
                created_by: "user".to_string(),
                depends_on: Vec::new(),
                approved: true,
                schedule: None,
                output_mode: TaskOutputMode::Accumulate,
                chat_session_id: None,
                lifecycle: crate::magician_v2::artifact_v2::models::TaskLifecycle::default(),
                sync_mode: crate::magician_v2::artifact_v2::models::TaskSyncMode::default(),
            })
            .await
            .expect("task created");

        let mut rejected_plan = persist_task_plan_fixture(
            service.as_ref(),
            &scope,
            &task,
            "plan-rejected",
            TaskPlanStatus::Rejected,
            &sample_plan_graph("Rejected"),
        )
        .await;
        rejected_plan.planning_execution_id = Some("planexec-old".to_string());
        service
            .persist_task_plan_record(&scope, &task.manifest.task_id, &rejected_plan)
            .await
            .expect("rejected plan should persist");

        let planning_plan = TaskPlanRecord {
            plan_id: "plan-new".to_string(),
            task_id: task.manifest.task_id.clone(),
            agent_id: task.manifest.agent_id.clone(),
            status: TaskPlanStatus::Planning,
            planning_execution_id: Some("planexec-new".to_string()),
            planning_recovery: None,
            plan_graph: None,
            query_analysis: None,
            slot_graph_snapshot: None,
            strategy_attempts: Vec::new(),
            clarification_history: Vec::new(),
            pending_questions: Vec::new(),
            error: None,
            created_at: "2026-04-10T01:00:00Z".to_string(),
            updated_at: "2026-04-10T01:00:00Z".to_string(),
        };
        service
            .persist_task_plan_record(&scope, &task.manifest.task_id, &planning_plan)
            .await
            .expect("planning plan should persist");
        service
            .persist_task_plan_index(
                &scope,
                &task.manifest.task_id,
                &TaskPlanIndexRecord {
                    task_id: task.manifest.task_id.clone(),
                    latest_plan_id: Some(planning_plan.plan_id.clone()),
                    approved_plan_id: None,
                    plans: vec![
                        TaskPlanIndexEntry {
                            plan_id: rejected_plan.plan_id.clone(),
                            status: rejected_plan.status.clone(),
                            created_at: rejected_plan.created_at.clone(),
                            updated_at: rejected_plan.updated_at.clone(),
                        },
                        TaskPlanIndexEntry {
                            plan_id: planning_plan.plan_id.clone(),
                            status: planning_plan.status.clone(),
                            created_at: planning_plan.created_at.clone(),
                            updated_at: planning_plan.updated_at.clone(),
                        },
                    ],
                    updated_at: Some(planning_plan.updated_at.clone()),
                },
            )
            .await
            .expect("task plan index should persist");

        let terminal_receipt = service
            .seal_task_planning_recovery_receipt(
                &scope,
                &task.manifest.task_id,
                &rejected_plan.plan_id,
                &task.manifest.agent_id,
                "planexec-old",
                "terminal-plan-turn",
                "terminal plan must short-circuit",
            )
            .expect("terminal-plan recovery fixture should seal");
        let terminal_lease = TaskPlanningRecoveryLease {
            owner: "terminal-plan-test".to_owned(),
            revision: 1,
        };

        Arc::clone(&service)
            .run_task_planning(
                scope.clone(),
                task.manifest.task_id.clone(),
                rejected_plan.plan_id.clone(),
                terminal_receipt,
                terminal_lease,
            )
            .await
            .expect("terminal requested plan should short-circuit");

        let latest_after = service
            .load_task_plan_record(&scope, &task.manifest.task_id, &planning_plan.plan_id)
            .await
            .expect("latest planning plan should still load");
        assert_eq!(latest_after.status, TaskPlanStatus::Planning);
        assert_eq!(
            latest_after.planning_execution_id.as_deref(),
            Some("planexec-new")
        );
    }

