    #[test]
    fn build_attention_summaries_preserves_typed_input_schema_metadata() {
        let task = sample_task_record();
        let execution = sample_execution_tree_node();
        let recent_events = HashMap::from([(
            execution.execution_id.clone(),
            vec![CanonicalEvent {
                event_id: "evt-1".to_string(),
                seq: 1,
                timestamp: "2026-04-05T00:00:10Z".to_string(),
                principal: "anonymous".to_string(),
                workspace: "default".to_string(),
                task_id: task.manifest.task_id.clone(),
                execution_id: execution.execution_id.clone(),
                plan_id: Some("plan-1".to_string()),
                step_id: Some("step-1".to_string()),
                event_type: ArtifactV2EventType::InputRequested.as_str().to_string(),
                ref_ids: EventRefIds::default(),
                payload: json!({
                    "question": "Pick one tool",
                    "pause_state_id": "pause-1",
                    "input_type": "tool_authorization",
                    "hint": "Allow only if needed",
                    "options": r#"[{"id":"allow","label":"Allow","description":"Run it"},{"id":"deny","label":"Deny","description":"Skip it"}]"#,
                    "input_schema": r#"{"type":"tool_authorization","context":"The tool wants network access","allow_other":false,"options":[{"id":"allow","label":"Allow","description":"Run it"},{"id":"deny","label":"Deny","description":"Skip it"}]}"#
                }),
            }],
        )]);

        let summaries = build_attention_summaries(&task, &[execution], &recent_events, None, None);
        assert_eq!(summaries.len(), 1);

        let summary = &summaries[0];
        assert_eq!(summary.attention_kind, "input.requested");
        assert_eq!(summary.pause_state_id.as_deref(), Some("pause-1"));
        assert_eq!(summary.input_type.as_deref(), Some("tool_authorization"));
        assert_eq!(summary.hint.as_deref(), Some("Allow only if needed"));
        assert_eq!(
            summary
                .options
                .as_ref()
                .and_then(|value| value.as_array())
                .map(Vec::len),
            Some(2)
        );
        assert_eq!(
            summary
                .input_schema
                .as_ref()
                .and_then(|value| value.get("type"))
                .and_then(|value| value.as_str()),
            Some("tool_authorization")
        );
        assert_eq!(
            summary
                .input_schema
                .as_ref()
                .and_then(|value| value.get("context"))
                .and_then(|value| value.as_str()),
            Some("The tool wants network access")
        );

        let mut grouped_summary = summary.clone();
        grouped_summary
            .entries
            .insert(0, "Earlier request".to_string());
        grouped_summary.item_count = 2;
        let feed_item = build_attention_feed_item(
            &V3TaskProgressSummary {
                task_id: task.manifest.task_id.clone(),
                principal: task.manifest.principal.clone(),
                workspace: task.manifest.workspace.clone(),
                ui_thread_id: task.manifest.ui_thread_id.clone(),
                agent_id: task.manifest.agent_id.clone(),
                status: task.state.status.clone(),
                summary: Some(task.manifest.title.clone()),
                active_root_execution_id: task.state.active_root_execution_id.clone(),
                latest_root_execution_id: task.state.latest_root_execution_id.clone(),
                last_completed_root_execution_id: task
                    .state
                    .last_completed_root_execution_id
                    .clone(),
                updated_at: task.manifest.updated_at.clone(),
                synthesis_pending: task.state.synthesis_pending(),
            },
            &grouped_summary,
        );
        let metadata = feed_item.metadata;
        assert_eq!(
            metadata
                .get("pause_state_id")
                .and_then(|value| value.as_str()),
            Some("pause-1")
        );
        assert_eq!(
            metadata
                .get("input_schema")
                .and_then(|value| value.get("type"))
                .and_then(|value| value.as_str()),
            Some("tool_authorization")
        );
        assert_eq!(
            metadata
                .get("hitl_request")
                .and_then(|value| value.get("id"))
                .and_then(|value| value.as_str()),
            Some("pause-1")
        );
        assert_eq!(
            metadata
                .get("hitl_request")
                .and_then(|value| value.get("source"))
                .and_then(|value| value.as_str()),
            Some("agentic")
        );
        assert_eq!(
            metadata
                .get("hitl_request")
                .and_then(|value| value.get("prompt"))
                .and_then(|value| value.as_str()),
            Some("Pick one tool")
        );
        assert_eq!(
            metadata
                .get("hitl_request")
                .and_then(|value| value.get("input_schema"))
                .and_then(|value| value.get("options"))
                .and_then(|value| value.as_array())
                .map(Vec::len),
            Some(2)
        );
    }

