    /// Every pause of one run shares its pause key, so a run's second
    /// question carries the correlation id its first was resolved under. A
    /// resolution settles only the requests before it: the first card is
    /// gone, the second surfaces with the later question, and a resolution
    /// after the second hides both.
    #[test]
    fn build_attention_summaries_surfaces_a_later_question_under_a_resolved_id() {
        let first = attention_event(
            "exec-hitl",
            "evt-ask-1",
            "2026-04-05T00:00:10Z",
            "hitl.requested",
            json!({
                "source": "agentic",
                "correlation_id": "agent:android-operator:goal:cycle",
                "input_type": "text",
                "prompt": "Which account?",
            }),
        );
        let resolved_first = attention_event(
            "exec-hitl",
            "evt-res-1",
            "2026-04-05T00:00:20Z",
            "hitl.resolved",
            json!({
                "source": "agentic",
                "correlation_id": "agent:android-operator:goal:cycle",
            }),
        );
        let second = attention_event(
            "exec-hitl",
            "evt-ask-2",
            "2026-04-05T00:00:30Z",
            "hitl.requested",
            json!({
                "source": "agentic",
                "correlation_id": "agent:android-operator:goal:cycle",
                "input_type": "password",
                "prompt": "Password?",
            }),
        );

        let summaries = attention_summaries_for(
            "waiting_for_user",
            vec![first.clone(), resolved_first.clone(), second.clone()],
        );
        let card = summaries
            .iter()
            .find(|s| s.attention_kind == "input.requested")
            .expect("the run's second question surfaces under the resolved id");
        assert_eq!(card.item_count, 1);
        assert_eq!(card.entries, vec!["Password?".to_string()]);
        assert_eq!(card.input_type.as_deref(), Some("password"));

        let resolved_second = attention_event(
            "exec-hitl",
            "evt-res-2",
            "2026-04-05T00:00:40Z",
            "hitl.resolved",
            json!({
                "source": "agentic",
                "correlation_id": "agent:android-operator:goal:cycle",
            }),
        );
        let summaries = attention_summaries_for(
            "waiting_for_user",
            vec![first, resolved_first, second, resolved_second],
        );
        assert!(
            summaries
                .iter()
                .all(|s| s.attention_kind != "input.requested"),
            "a resolution after the second question settles it"
        );
    }

