    #[test]
    fn build_attention_summaries_drops_resolved_diff_approval() {
        // Both request halves are present (as in production) and the single
        // `hitl.resolved { correlation_id }` must drop the WHOLE card. Pre
        // FIX-A the `input.requested` half carried only its `pause_state_id`
        // (never the ccp correlation), so it leaked past the resolution and
        // the card stayed stuck; with the unified `correlation_id` both halves
        // pair against the one resolution and the card disappears.
        let summaries = attention_summaries_for(
            "waiting_for_user",
            vec![
                attention_event(
                    "exec-hitl",
                    "evt-input",
                    "2026-04-05T00:00:09Z",
                    "input.requested",
                    json!({
                        "pause_state_id": "agent:je:goal:cycle",
                        "correlation_id": "corr-diff-1",
                    }),
                ),
                attention_event(
                    "exec-hitl",
                    "evt-req",
                    "2026-04-05T00:00:10Z",
                    "hitl.requested",
                    json!({
                        "source": "diff_approval",
                        "correlation_id": "corr-diff-1",
                        "prompt": "Apply this code change?",
                    }),
                ),
                attention_event(
                    "exec-hitl",
                    "evt-res",
                    "2026-04-05T00:00:20Z",
                    "hitl.resolved",
                    json!({
                        "source": "diff_approval",
                        "correlation_id": "corr-diff-1",
                    }),
                ),
            ],
        );
        assert!(!summaries
            .iter()
            .any(|s| s.attention_kind == "input.requested"));
    }

    #[test]
    fn build_attention_summaries_drops_user_request_not_in_pending_store() {
        // State-driven self-heal: a `user_request` card whose request id is NOT
        // in the authoritative pending set must drop EVEN WITH NO
        // `hitl.resolved` event (the resolution event was dropped/lost, but the
        // store says the request is no longer pending).
        let stale = attention_event(
            "exec-hitl",
            "evt-req-stale",
            "2026-04-05T00:00:10Z",
            "hitl.requested",
            json!({
                "source": "user_request",
                "correlation_id": "corr-user-stale",
                "prompt": "Owner briefing?",
            }),
        );
        // Only a DIFFERENT id is pending → the stale card is authoritatively
        // resolved and must not surface.
        let pending: std::collections::HashSet<String> =
            std::iter::once("corr-user-still-live".to_string()).collect();
        let summaries = attention_summaries_for_state(
            "waiting_for_user",
            vec![stale],
            Some(&pending),
            Some(&std::collections::HashSet::new()),
        );
        assert!(
            !summaries
                .iter()
                .any(|s| s.attention_kind == "user_request.pending"),
            "a user_request whose id is not in the pending store must drop with no hitl.resolved"
        );

        // Sibling check: the genuinely-pending one DOES still surface.
        let live = attention_event(
            "exec-hitl",
            "evt-req-live",
            "2026-04-05T00:00:10Z",
            "hitl.requested",
            json!({
                "source": "user_request",
                "correlation_id": "corr-user-still-live",
                "prompt": "Owner briefing?",
            }),
        );
        let summaries_live = attention_summaries_for_state(
            "waiting_for_user",
            vec![live],
            Some(&pending),
            Some(&std::collections::HashSet::new()),
        );
        assert!(
            summaries_live
                .iter()
                .any(|s| s.attention_kind == "user_request.pending"),
            "a user_request whose id IS in the pending store must still surface"
        );
    }

    #[test]
    fn build_attention_summaries_drops_diff_approval_not_in_pending_proposals() {
        // State-driven self-heal: a `diff_approval` ("code apply") card whose
        // proposal id is NOT in the authoritative pending-proposal set (its
        // proposal is Applied/Rejected) must drop EVEN WITH NO `hitl.resolved`
        // event. Production emits BOTH the `input.requested` sibling and the
        // owning `hitl.requested { source: diff_approval }`; the state gate on
        // the `hitl.requested` half plus the shared `correlation_id` collapses
        // the whole card once the proposal is no longer pending.
        let events_stale = vec![
            attention_event(
                "exec-hitl",
                "evt-input",
                "2026-04-05T00:00:09Z",
                "input.requested",
                json!({
                    "pause_state_id": "agent:je:goal:cycle",
                    "correlation_id": "ccp-stale",
                }),
            ),
            attention_event(
                "exec-hitl",
                "evt-req",
                "2026-04-05T00:00:10Z",
                "hitl.requested",
                json!({
                    "source": "diff_approval",
                    "correlation_id": "ccp-stale",
                    "prompt": "Apply this code change?",
                }),
            ),
        ];
        // Only a different proposal is pending → the stale card must not surface.
        let pending_proposals: std::collections::HashSet<String> =
            std::iter::once("ccp-still-pending".to_string()).collect();
        let summaries = attention_summaries_for_state(
            "waiting_for_user",
            events_stale,
            Some(&std::collections::HashSet::new()),
            Some(&pending_proposals),
        );
        assert!(
            !summaries
                .iter()
                .any(|s| s.source.as_deref() == Some("diff_approval")),
            "a diff_approval whose proposal id is not Pending must drop with no hitl.resolved"
        );

        // Sibling check: the genuinely-pending proposal DOES still surface.
        let events_live = vec![
            attention_event(
                "exec-hitl",
                "evt-input",
                "2026-04-05T00:00:09Z",
                "input.requested",
                json!({
                    "pause_state_id": "agent:je:goal:cycle",
                    "correlation_id": "ccp-still-pending",
                }),
            ),
            attention_event(
                "exec-hitl",
                "evt-req",
                "2026-04-05T00:00:10Z",
                "hitl.requested",
                json!({
                    "source": "diff_approval",
                    "correlation_id": "ccp-still-pending",
                    "prompt": "Apply this code change?",
                }),
            ),
        ];
        let summaries_live = attention_summaries_for_state(
            "waiting_for_user",
            events_live,
            Some(&std::collections::HashSet::new()),
            Some(&pending_proposals),
        );
        assert!(
            summaries_live
                .iter()
                .any(|s| s.source.as_deref() == Some("diff_approval")),
            "a diff_approval whose proposal id IS Pending must still surface"
        );
    }

    /// Minimal `V3AttentionSummary` for the serve-path gate tests. Older cached
    /// snapshots predate the `source` field, so `source` defaults to `None`
    /// here — the helper must key off `attention_kind` + the `"ccp-"` id prefix.
    fn attention_summary_fixture(
        attention_kind: &str,
        pause_state_id: Option<&str>,
    ) -> V3AttentionSummary {
        V3AttentionSummary {
            attention_id: format!("attention:{attention_kind}:task:exec"),
            attention_kind: attention_kind.to_string(),
            task_id: "task".to_string(),
            execution_id: "exec".to_string(),
            summary: "summary".to_string(),
            detail: None,
            entries: Vec::new(),
            item_count: 1,
            updated_at: "2026-04-05T00:00:10Z".to_string(),
            pause_state_id: pause_state_id.map(str::to_string),
            input_type: None,
            hint: None,
            options: None,
            input_schema: None,
            source: None,
        }
    }

    #[test]
    fn attention_is_still_actionable_gates_user_request_on_pending_store() {
        // Owner-briefing shape: attention_kind == "user_request.pending",
        // pause_state_id == the request uuid, no `source` (cached snapshot).
        let card = attention_summary_fixture(
            "user_request.pending",
            Some("1104ef19-edac-480d-8d17-84b0b3d8a694"),
        );

        // Authoritative set does NOT contain the id → drop.
        let others: std::collections::HashSet<String> =
            std::iter::once("some-other-request".to_string()).collect();
        assert!(
            !attention_is_still_actionable(
                &card,
                Some(&others),
                Some(&std::collections::HashSet::new()),
                false
            ),
            "a user_request card whose id is not in the pending set must drop"
        );

        // Authoritative set DOES contain the id → keep. (Owner-briefings are
        // NOT gated on task-terminal status — a briefing execution finishes
        // while the request stays genuinely pending — so a terminal task must
        // not hide it.)
        let pending: std::collections::HashSet<String> =
            std::iter::once("1104ef19-edac-480d-8d17-84b0b3d8a694".to_string()).collect();
        assert!(
            attention_is_still_actionable(
                &card,
                Some(&pending),
                Some(&std::collections::HashSet::new()),
                true
            ),
            "a user_request card whose id IS in the pending set must be kept even on a terminal task"
        );

        // Fail-open: user_request service not consulted (None) → keep, never
        // hide, even though the (unused) empty proposal set is authoritative.
        assert!(
            attention_is_still_actionable(
                &card,
                None,
                Some(&std::collections::HashSet::new()),
                false
            ),
            "a user_request card must be kept when the pending-request store was not consulted"
        );
    }

    #[test]
    fn attention_is_still_actionable_gates_diff_approval_and_keeps_generic() {
        // Diff-approval shape: attention_kind == "input.requested",
        // pause_state_id starts "ccp-", no `source` (cached snapshot).
        let card = attention_summary_fixture(
            "input.requested",
            Some("ccp-501d70dc-bb94-4e73-8129-de0fd2d8471b"),
        );

        // Proposal set does NOT contain the id → drop (empty set is
        // authoritative for proposals: the proposal is Applied/Rejected/absent).
        assert!(
            !attention_is_still_actionable(
                &card,
                Some(&std::collections::HashSet::new()),
                Some(&std::collections::HashSet::new()),
                false,
            ),
            "a diff_approval card whose proposal id is not Pending must drop"
        );

        // Proposal set DOES contain the id (still Pending) on a NON-terminal
        // task → keep.
        let pending: std::collections::HashSet<String> =
            std::iter::once("ccp-501d70dc-bb94-4e73-8129-de0fd2d8471b".to_string()).collect();
        assert!(
            attention_is_still_actionable(&card, None, Some(&pending), false),
            "a diff_approval card whose proposal id IS Pending must be kept on an active task"
        );

        let mut legacy_transaction =
            attention_summary_fixture("input.requested", Some("txn-legacy-1"));
        legacy_transaction.input_type = Some("diff_approval".to_string());
        let pending_transaction: std::collections::HashSet<String> =
            std::iter::once("txn-legacy-1".to_string()).collect();
        assert!(attention_is_still_actionable(
            &legacy_transaction,
            None,
            Some(&pending_transaction),
            false,
        ));
        assert!(!attention_is_still_actionable(
            &legacy_transaction,
            None,
            Some(&std::collections::HashSet::new()),
            false,
        ));

        let task = sample_task_record();
        let task_summary = V3TaskProgressSummary {
            task_id: task.manifest.task_id.clone(),
            principal: task.manifest.principal.clone(),
            workspace: task.manifest.workspace.clone(),
            ui_thread_id: task.manifest.ui_thread_id.clone(),
            agent_id: task.manifest.agent_id.clone(),
            status: task.state.status.clone(),
            summary: Some(task.manifest.title.clone()),
            active_root_execution_id: task.state.active_root_execution_id.clone(),
            latest_root_execution_id: task.state.latest_root_execution_id.clone(),
            last_completed_root_execution_id: task.state.last_completed_root_execution_id.clone(),
            updated_at: task.manifest.updated_at.clone(),
            synthesis_pending: task.state.synthesis_pending(),
        };
        let target = build_attention_hitl_open_target(&task_summary, &legacy_transaction)
            .expect("legacy transaction should reconstruct as diff approval");
        assert_eq!(target.source, "diff_approval");
        assert_eq!(target.scope.principal.as_deref(), Some("anonymous"));
        assert_eq!(target.scope.workspace.as_deref(), Some("default"));

        // Proposal still Pending BUT the owning task is terminal
        // (cancelled/failed/completed) → the proposal is orphaned, drop it.
        assert!(
            !attention_is_still_actionable(&card, None, Some(&pending), true),
            "a Pending diff_approval on a terminal (e.g. cancelled) task is orphaned and must drop"
        );

        // Terminal failures are not actionable and must be dropped even from
        // cached snapshots written by older builds.
        let failed = attention_summary_fixture("execution.failed", None);
        assert!(
            !attention_is_still_actionable(&failed, None, None, true),
            "a terminal execution failure must not surface in Attention"
        );
        assert!(
            attention_is_still_actionable(
                &attention_summary_fixture("agent.circuit.opened", None),
                None,
                None,
                true,
            ),
            "non-task operational attention remains visible"
        );
        assert!(
            attention_is_still_actionable(
                &attention_summary_fixture("agent.circuit.opened", None),
                Some(&std::collections::HashSet::new()),
                Some(&std::collections::HashSet::new()),
                false,
            ),
            "a generic non-HITL card must always be kept (empty authoritative sets)"
        );
    }

    #[test]
    fn agentic_attention_reconciles_cached_cards_with_pause_store_and_terminal_state() {
        let mut card = attention_summary_fixture("input.requested", Some("pause-123"));
        card.source = Some("agentic".to_string());

        assert!(agentic_attention_is_still_actionable(
            &card,
            false,
            Some(true),
        ));
        assert!(
            !agentic_attention_is_still_actionable(&card, false, Some(false)),
            "a cached agentic card absent from the authoritative pause store must drop"
        );
        assert!(
            !agentic_attention_is_still_actionable(&card, true, Some(true)),
            "a terminal task cannot retain an execution-bound HITL card"
        );
        assert!(
            agentic_attention_is_still_actionable(&card, false, None),
            "missing pause-store authority must fail open for an active task"
        );

        let legacy = attention_summary_fixture("waiting_for_confirmation", Some("legacy-pause"));
        assert!(!agentic_attention_is_still_actionable(
            &legacy,
            false,
            Some(false),
        ));

        let operational = attention_summary_fixture("agent.circuit.opened", None);
        assert!(agentic_attention_is_still_actionable(
            &operational,
            true,
            Some(false),
        ));
    }

    #[test]
    fn attention_feed_refreshes_exact_pause_authority_in_authenticated_scope() {
        let source = include_str!("service.rs");
        let feed = source
            .split("pub async fn list_attention_items")
            .nth(1)
            .and_then(|tail| tail.split("pub async fn").next())
            .expect("attention feed implementation");
        let refresh = feed
            .find("resumable_pause_is_pending_scoped")
            .expect("peer-visible exact pause refresh");
        let actionable = feed[refresh..]
            .find("agentic_attention_is_still_actionable")
            .map(|offset| refresh + offset)
            .expect("actionability gate after refresh");
        assert!(feed[refresh..actionable].contains("scope.principal()"));
        assert!(feed[refresh..actionable].contains("scope.workspace()"));
        assert!(feed[refresh..actionable].contains(".await"));
        assert!(refresh < actionable);
    }

