    #[tokio::test]
    async fn recurring_startup_recovers_terminal_app_and_schedule_gap_on_default_stack() {
        tokio::time::timeout(
            std::time::Duration::from_secs(30),
            Box::pin(async {
                for schedule_gap in [false, true] {
                    let root = tempfile::TempDir::new().unwrap();
                    let canonical_root = root.path().canonicalize().unwrap();
                    let service = Arc::new(build_test_artifact_v2_service(&canonical_root));
                    let scope = ScopeRef::system_internal_unauthenticated("anonymous", "default");
                    let task_id = format!("task_app_{}", "e".repeat(64));
                    let mut input = app_workflow_create_input_fixture(&scope);
                    input.lifecycle = TaskLifecycle::Internal;
                    service
                        .ensure_app_workflow_task_with_id(input, task_id.clone())
                        .await
                        .unwrap();
                    service
                        .mark_app_workflow_task_ready(&scope, &task_id)
                        .await
                        .unwrap();
                    let admission = service
                        .acquire_app_workflow_start_admission(&scope, &task_id)
                        .await
                        .unwrap();
                    // This is a retained legacy App root. Canonical recipe IDs
                    // require a full launch reservation; recovery of this older
                    // root uses the same terminal outcome/resource poll path.
                    let (mut task, mut execution, _) =
                        Box::pin(service.prepare_execution_start_internal(
                            &scope,
                            &task_id,
                            None,
                            false,
                            Some("exec_legacy_recovery_fixture".into()),
                            false,
                            None,
                            None,
                            None,
                            Some(&admission),
                            None,
                        ))
                        .await
                        .unwrap();
                    drop(admission);
                    execution.state.status = if schedule_gap { "running" } else { "failed" }.into();
                    execution.state.completed_at = (!schedule_gap).then(now_rfc3339);
                    service
                        .workspace
                        .write_json_atomic_path(
                            &service.workspace.execution_state_path(
                                &scope.principal(),
                                &scope.workspace(),
                                &task_id,
                                "exec_legacy_recovery_fixture",
                            ),
                            &execution.state,
                        )
                        .await
                        .unwrap();
                    task.state.status = execution.state.status.clone();
                    task.state.active_root_execution_id =
                        schedule_gap.then(|| "exec_legacy_recovery_fixture".to_owned());
                    service.persist_task_record(&scope, &task).await.unwrap();
                    let state_path = service
                        .app_workflow_service()
                        .seed_terminal_recovery_test_state(
                            &scope,
                            &task_id,
                            "exec_legacy_recovery_fixture",
                        )
                        .await
                        .unwrap();
                    if schedule_gap {
                        // The schedule settled before shutdown, but the root's terminal
                        // write did not. This reaches the full outcome/resource path.
                        let schedule = ExecutionScheduleRecord {
                            execution_id: execution.state.execution_id.clone(),
                            task_id: task_id.clone(),
                            plan_id: execution.state.plan_id.clone(),
                            source_plan_relative_path: None,
                            source_kind: "app_recipe_v1".to_owned(),
                            updated_at: now_rfc3339(),
                            steps: vec![ExecutionScheduleStep {
                                step_id: "step_failed".to_owned(),
                                title: "Failed recipe root".to_owned(),
                                order: 0,
                                depends_on_step_ids: Vec::new(),
                                capability: None,
                                delegate_agent_id: None,
                                taskplan_status: "failed".to_owned(),
                                taskplan_progress: "0/1".to_owned(),
                                sub_step_labels: Vec::new(),
                                recipe: Some(AppRecipeScheduleStepState {
                                    node_execution_id: "node_failed".to_owned(),
                                    parent_node_execution_id: execution.state.execution_id.clone(),
                                    binding_digest: "blake3:fixture".to_owned(),
                                    input_schema_ref: "schema:input".to_owned(),
                                    output_schema_ref: "schema:output".to_owned(),
                                    uncertainty: "impossible".to_owned(),
                                    max_active_millis: 60_000,
                                    cancellation_acknowledgement_timeout_millis: 1_000,
                                    aggregate_deadline_at_ms: 90_000,
                                    phase: AppRecipeScheduleNodePhase::Failed,
                                    attempt: 1,
                                    claim_epoch: 1,
                                    claim_owner_id: None,
                                    claim_lease_expires_at_ms: None,
                                    active_deadline_at_ms: None,
                                    input_digest: None,
                                    input_encoded_len: None,
                                    retry_identity_digest: None,
                                    output: None,
                                    cancellation_requested_at: None,
                                    cancellation_ack_deadline_at_ms: None,
                                }),
                            }],
                        };
                        service
                            .workspace
                            .write_json_atomic_path(
                                &service.workspace.execution_schedule_path(
                                    &scope.principal(),
                                    &scope.workspace(),
                                    &task_id,
                                    &execution.state.execution_id,
                                ),
                                &schedule,
                            )
                            .await
                            .unwrap();
                    }
                    let recovered = Box::pin(service.try_recover_task_synthesis(&scope, &task_id))
                        .await
                        .unwrap();
                    if schedule_gap {
                        assert_eq!(recovered, 1, "the missing terminal write must be recovered");
                    }
                    // This fixture deliberately has no live resource authority. Recovery
                    // must durably request another cleanup attempt without aborting the
                    // process or reopening the terminal execution.
                    let sealed: Value =
                        serde_json::from_slice(&std::fs::read(state_path).unwrap()).unwrap();
                    let payload = &sealed["payload"];
                    let state: Value = if let Some(text) = payload.as_str() {
                        serde_json::from_str(text).unwrap()
                    } else {
                        payload.clone()
                    };
                    assert_eq!(state["resource_cleanup_pending"], json!(true));
                    let settled_task = service.get_task(&scope, &task_id).await.unwrap();
                    assert_eq!(settled_task.state.status, "failed");
                    assert!(settled_task.state.active_root_execution_id.is_none());
                    assert_eq!(
                        service
                            .get_execution(&scope, &task_id, "exec_legacy_recovery_fixture")
                            .await
                            .unwrap()
                            .state
                            .status,
                        "failed"
                    );
                }
            }),
        )
        .await
        .expect("old App terminal recovery must finish without deadlocking");
    }

    #[tokio::test]
    async fn recurring_task_reuses_one_shell_preserves_history_and_fences_overlap() {
        tokio::time::timeout(
            std::time::Duration::from_secs(30),
            Box::pin(async {
                let root = crate::magician_v2::apps::registry::tests::canonical_tempdir();
                let service = build_test_artifact_v2_service(root.path());
                let scope = ScopeRef::system_internal_unauthenticated("anonymous", "default");
                let task_id = format!("task_app_{}", "c".repeat(64));
                let mut input = app_workflow_create_input_fixture(&scope);
                input.lifecycle = TaskLifecycle::Internal;
                input.tags.push(TaskTagRecord {
                    id: "app_recurring".into(),
                    name: "Recurring app behavior".into(),
                    color: None,
                });
                service
                    .ensure_app_workflow_task_with_id(input, task_id.clone())
                    .await
                    .unwrap();
                for round in 1..=4 {
                    service
                        .mark_recurring_app_workflow_task_ready(
                            &scope,
                            &task_id,
                            "personal-assistant",
                        )
                        .await
                        .unwrap();
                    let admission = service
                        .acquire_app_workflow_start_admission(&scope, &task_id)
                        .await
                        .unwrap();
                    let (mut task, mut execution, _) =
                        Box::pin(service.prepare_execution_start_internal(
                            &scope,
                            &task_id,
                            None,
                            false,
                            Some(format!("exec_app_round_{round}")),
                            false,
                            None,
                            None,
                            None,
                            Some(&admission),
                            None,
                        ))
                        .await
                        .unwrap();
                    drop(admission);
                    assert!(service
                        .mark_recurring_app_workflow_task_ready(
                            &scope,
                            &task_id,
                            "personal-assistant"
                        )
                        .await
                        .is_err());
                    // Simulate the terminal owner committing both canonical records.
                    execution.state.status = "completed".into();
                    execution.state.completed_at = Some(now_rfc3339());
                    execution.state.started_at = format!("2026-09-11T10:0{round}:00Z");
                    service
                        .workspace
                        .write_json_atomic_path(
                            &service.workspace.execution_state_path(
                                &scope.principal(),
                                &scope.workspace(),
                                &task_id,
                                &execution.state.execution_id,
                            ),
                            &execution.state,
                        )
                        .await
                        .unwrap();
                    task.state.active_root_execution_id = None;
                    task.state.status = "completed".into();
                    service.persist_task_record(&scope, &task).await.unwrap();
                }
                let restarted = build_test_artifact_v2_service(root.path());
                let history = restarted.list_executions(&scope, &task_id).await.unwrap();
                assert_eq!(history.len(), 4);
                let first = restarted
                    .get_task_with_executions_page(&scope, &task_id, 2, None)
                    .await
                    .unwrap();
                assert_eq!(first.executions.len(), 2);
                let next = restarted
                    .get_task_with_executions_page(
                        &scope,
                        &task_id,
                        2,
                        first.next_execution_cursor.as_deref(),
                    )
                    .await
                    .unwrap();
                assert_eq!(next.executions.len(), 2);
                assert!(next.next_execution_cursor.is_none());
                let ids = first
                    .executions
                    .iter()
                    .chain(&next.executions)
                    .map(|execution| &execution.state.execution_id)
                    .collect::<std::collections::HashSet<_>>();
                assert_eq!(ids.len(), 4);
                assert_eq!(
                    restarted.list_internal_tasks(&scope).await.unwrap().len(),
                    1
                );
                assert!(restarted
                    .delete_internal_task(&scope, &task_id)
                    .await
                    .is_err());
            }),
        )
        .await
        .expect("recurring task admission and history must not deadlock");
    }

