    /// `cleanup_task_external_artifacts` (invoked by every delete path)
    /// must remove published-surface records whose `task_id` matches the
    /// deleted task, rewrite the surfaces index, and drop the
    /// materialized layout. Before this test existed, deleting a task
    /// left orphan surface JSONs that re-appeared in `/published-surfaces`
    /// listings on the next reload.
    #[tokio::test]
    async fn delete_task_cascades_to_published_surfaces() {
        let tmp = tempfile::TempDir::new().expect("temp dir");
        let service = build_test_artifact_v2_service(tmp.path());
        let scope =
            ScopeRef::system_internal_unauthenticated(&"alpha".to_string(), &"prod".to_string());
        let task = service
            .create_task(make_create_input(
                &scope.principal(),
                &scope.workspace(),
                "Surface owner",
                "user",
            ))
            .await
            .expect("create task");
        let task_id = task.manifest.task_id.clone();
        let output_ref = service
            .write_user_output_direct(
                &scope,
                &task_id,
                WriteUserOutputDirectInput {
                    media_type: "text/markdown".to_string(),
                    body: WriteUserOutputBody::Text("# Surface body".to_string()),
                    dashboard_theme: None,
                },
            )
            .await
            .expect("write output");
        let surface = service
            .publish_surface_record(
                &scope,
                PublishSurfaceInput {
                    task_id: task_id.clone(),
                    source_output_id: Some(output_ref.output_id.clone()),
                    materialize_as: None,
                    logical_surface_id: Some("cascade-fixture".to_string()),
                    surface_kind: Some("dashboard".to_string()),
                    route: Some("/briefing/cascade-fixture".to_string()),
                    title: Some("Cascade fixture".to_string()),
                    summary: None,
                    placement: Some(PublishedSurfacePlacement {
                        placement_kind: "workspace".to_string(),
                        placement_id: Some(scope.workspace().to_string()),
                        pinned: true,
                    }),
                },
            )
            .await
            .expect("publish surface");

        // Mark terminal so archive_task accepts the call.
        service
            .update_task_status(&scope, &task_id, "completed")
            .await
            .expect("mark completed");

        let surface_path = service.workspace.published_surface_path(
            &scope.principal(),
            &scope.workspace(),
            &surface.surface_id,
        );
        assert!(
            tokio::fs::try_exists(&surface_path).await.unwrap_or(false),
            "surface JSON should exist before delete"
        );

        service
            .archive_task_with_options(&scope, &task_id, true)
            .await
            .expect("delete with files");

        let task_dir = service
            .workspace
            .task_dir(&scope.principal(), &scope.workspace(), &task_id);
        assert!(
            !tokio::fs::try_exists(&task_dir).await.unwrap_or(true),
            "task dir should be removed"
        );
        assert!(
            !tokio::fs::try_exists(&surface_path).await.unwrap_or(true),
            "cascade should remove orphan surface JSON"
        );
        let store = FilesystemPublishedSurfaceStore::new(service.workspace.clone());
        let remaining = store
            .load_surface_records_from_files(&scope.principal(), &scope.workspace())
            .await
            .expect("load surfaces");
        assert!(
            remaining
                .records
                .iter()
                .all(|r| r.surface_id != surface.surface_id),
            "cascade should drop the surface from the index"
        );
    }

