    #[tokio::test]
    async fn app_runtime_concurrency_regression_deleted_task_output_residue_keeps_no_live_authority(
    ) {
        let tmp = tempfile::TempDir::new().unwrap();
        let service = build_test_artifact_v2_service(tmp.path());
        let scope = ScopeRef::system_internal_unauthenticated("alpha", "prod");
        let task_id = "task_deleted_residue";
        let root =
            service
                .workspace
                .user_visible_task_dir(scope.principal(), scope.workspace(), task_id);
        let output = root.join("executions/exec_old/outputs/out_exec_exec_old.md");
        service
            .workspace
            .create_dir_all_path(output.parent().unwrap())
            .await
            .unwrap();
        service
            .workspace
            .write_atomic_path(&output, b"Retained historical output")
            .await
            .unwrap();
        // Missing deletion evidence cannot suppress terminal settlement.
        assert!(service
            .acquire_deleted_task_terminal_exclusion(&scope, task_id)
            .await
            .unwrap()
            .is_none());
        let marker = service.workspace.task_deletion_marker_path(
            scope.principal(),
            scope.workspace(),
            task_id,
        );
        service
            .workspace
            .create_dir_all_path(marker.parent().unwrap())
            .await
            .unwrap();
        service
            .workspace
            .write_atomic_path(&marker, Utc::now().to_rfc3339().as_bytes())
            .await
            .unwrap();
        let guard = service
            .acquire_deleted_task_terminal_exclusion(&scope, task_id)
            .await
            .unwrap();
        assert!(guard.is_some());
        drop(guard);
        assert_eq!(
            service
                .workspace
                .read_to_string_bounded_path(&output, 128)
                .await
                .unwrap(),
            "Retained historical output"
        );
        // A partial deletion with authoritative bytes is still unresolved.
        service
            .workspace
            .write_atomic_path(root.join("executions/exec_old/state.json"), b"{}")
            .await
            .unwrap();
        assert!(service
            .acquire_deleted_task_terminal_exclusion(&scope, task_id)
            .await
            .unwrap()
            .is_none());
    }

