    /// The `/tasks` list must hide `Internal` tasks; the
    /// `/internal-tasks` list (`list_internal_tasks`) must show them.
    /// `lifecycle` is the canonical signal — `created_by` alone is
    /// insufficient because the LLM `create_task` chat tool keeps
    /// `Persistent` lifecycle even when called with
    /// `created_by="chat_inline"` (the user asked for a tracked task).
    #[tokio::test]
    async fn list_internal_tasks_separates_persistent_and_ephemeral() {
        let tmp = tempfile::TempDir::new().expect("temp dir");
        let service = build_test_artifact_v2_service(tmp.path());
        let scope =
            ScopeRef::system_internal_unauthenticated(&"alpha".to_string(), &"prod".to_string());
        let user_task = service
            .create_task(make_create_input(
                &scope.principal(),
                &scope.workspace(),
                "User task",
                "user",
            ))
            .await
            .expect("user task");
        let ephemeral_task = service
            .create_task(make_create_input_with_lifecycle(
                &scope.principal(),
                &scope.workspace(),
                "Ephemeral chat task",
                "chat_inline",
                crate::magician_v2::artifact_v2::models::TaskLifecycle::Internal,
            ))
            .await
            .expect("ephemeral task");

        let visible = service.list_tasks(&scope).await.expect("list visible");
        let visible_ids: Vec<_> = visible.iter().map(|t| t.id.clone()).collect();
        assert!(
            visible_ids.contains(&user_task.manifest.task_id),
            "user task should be on /tasks"
        );
        assert!(
            !visible_ids.contains(&ephemeral_task.manifest.task_id),
            "ephemeral task must not appear on /tasks (got {visible_ids:?})"
        );

        let internal = service
            .list_internal_tasks(&scope)
            .await
            .expect("list internal");
        let internal_ids: Vec<_> = internal.iter().map(|t| t.id.clone()).collect();
        assert!(
            internal_ids.contains(&ephemeral_task.manifest.task_id),
            "ephemeral task should appear on /internal-tasks (got {internal_ids:?})"
        );
        assert!(
            !internal_ids.contains(&user_task.manifest.task_id),
            "user-visible task must not appear on /internal-tasks (got {internal_ids:?})"
        );
    }

    /// Creating an `Internal` task must land in
    /// `internal_tasks/<id>/`, not the user-visible `tasks/<id>/`.
    /// This is the write-time invariant the `task_dir` probe relies on
    /// to route reads correctly afterward.
    #[tokio::test]
    async fn create_task_routes_ephemeral_to_internal_folder() {
        let tmp = tempfile::TempDir::new().expect("temp dir");
        let service = build_test_artifact_v2_service(tmp.path());
        let scope =
            ScopeRef::system_internal_unauthenticated(&"alpha".to_string(), &"prod".to_string());
        let persistent = service
            .create_task(make_create_input(
                &scope.principal(),
                &scope.workspace(),
                "Persistent",
                "user",
            ))
            .await
            .expect("persistent");
        let ephemeral = service
            .create_task(make_create_input_with_lifecycle(
                &scope.principal(),
                &scope.workspace(),
                "Ephemeral",
                "chat_inline",
                crate::magician_v2::artifact_v2::models::TaskLifecycle::Internal,
            ))
            .await
            .expect("ephemeral");

        let user_visible_dir = service.workspace.user_visible_task_dir(
            &scope.principal(),
            &scope.workspace(),
            &persistent.manifest.task_id,
        );
        let internal_dir = service.workspace.internal_task_dir(
            &scope.principal(),
            &scope.workspace(),
            &ephemeral.manifest.task_id,
        );
        let ephemeral_in_user_visible_dir = service.workspace.user_visible_task_dir(
            &scope.principal(),
            &scope.workspace(),
            &ephemeral.manifest.task_id,
        );

        assert!(
            tokio::fs::try_exists(&user_visible_dir)
                .await
                .unwrap_or(false),
            "persistent task should land in tasks/<id>/"
        );
        assert!(
            tokio::fs::try_exists(&internal_dir).await.unwrap_or(false),
            "ephemeral task should land in internal_tasks/<id>/"
        );
        assert!(
            !tokio::fs::try_exists(&ephemeral_in_user_visible_dir)
                .await
                .unwrap_or(true),
            "ephemeral task must NOT also exist in tasks/<id>/ (got both — write routing is broken)"
        );
    }

    #[tokio::test]
    async fn find_execution_scope_resolves_internal_task_execution() {
        let tmp = tempfile::TempDir::new().expect("temp dir");
        let service = build_test_artifact_v2_service(tmp.path());
        let scope =
            ScopeRef::system_internal_unauthenticated(&"alpha".to_string(), &"prod".to_string());
        let (task, execution) = service
            .create_task_with_execution_shell(make_create_input_with_lifecycle(
                &scope.principal(),
                &scope.workspace(),
                "Ephemeral with execution",
                "chat_inline",
                crate::magician_v2::artifact_v2::models::TaskLifecycle::Internal,
            ))
            .await
            .expect("ephemeral task with execution");
        let task_id = task.manifest.task_id.clone();
        let execution_id = execution.state.execution_id.clone();

        let resolved = service
            .find_execution_scope(&execution_id)
            .await
            .expect("find execution scope")
            .expect("execution should resolve");
        assert_eq!(resolved.0.principal(), scope.principal());
        assert_eq!(resolved.0.workspace(), scope.workspace());
        assert_eq!(resolved.1, task_id);
        assert_eq!(resolved.2, execution_id);

        let stale_user_visible_dir = service.workspace.user_visible_task_dir(
            &scope.principal(),
            &scope.workspace(),
            &task_id,
        );
        tokio::fs::create_dir_all(&stale_user_visible_dir)
            .await
            .expect("stale duplicate dir");

        let resolved = service
            .find_execution_scope(&execution_id)
            .await
            .expect("find execution scope with duplicate root")
            .expect("execution should still resolve");
        assert_eq!(resolved.0.principal(), scope.principal());
        assert_eq!(resolved.0.workspace(), scope.workspace());
        assert_eq!(resolved.1, task_id);
        assert_eq!(resolved.2, execution_id);
    }

