    #[tokio::test]
    async fn generic_lifecycle_surfaces_cannot_mutate_or_delete_app_workflow_tasks() {
        let tmp = tempfile::TempDir::new().expect("temp dir");
        let service = build_test_artifact_v2_service(tmp.path());
        let scope =
            ScopeRef::system_internal_unauthenticated(&"alpha".to_string(), &"prod".to_string());

        // The guard is deliberately independent of the current task state:
        // queued, waiting, running, and terminal app runs all remain owned by
        // the workflow protocol. Persist representative source states
        // directly because generic status writes are exactly what this test
        // proves callers can no longer use to manufacture them.
        for (digest_byte, source_status) in [
            ('a', "pending"),
            ('b', "waiting_for_user"),
            ('c', "running"),
            ('d', "completed"),
        ] {
            let task_id = format!("task_app_{}", digest_byte.to_string().repeat(64));
            let mut task = service
                .ensure_app_workflow_task_with_id(
                    make_create_input(
                        &scope.principal(),
                        &scope.workspace(),
                        source_status,
                        "app_action",
                    ),
                    task_id.clone(),
                )
                .await
                .expect("create canonical app task fixture");
            task.state.status = source_status.to_string();
            service
                .persist_task_record(&scope, &task)
                .await
                .expect("persist representative source state");

            if digest_byte == 'a' {
                let error = Arc::clone(&service)
                    .run_chat_pack_inline(
                        scope.clone(),
                        task_id.clone(),
                        "exec_generic_chat_app_fence".to_string(),
                        "must not launch".to_string(),
                        "chat_inline".to_string(),
                        None,
                        Vec::new(),
                        None,
                        None,
                        None,
                        false,
                        None,
                        Vec::new(),
                    )
                    .await
                    .expect_err("generic chat-pack launch must reject app namespace preflight");
                assert!(matches!(
                    error,
                    ArtifactV2Error::InvalidRequest(ref message)
                        if message == &format!(
                            "{APP_WORKFLOW_GENERIC_LIFECYCLE_DENIED}:{task_id}"
                        )
                ));
            }

            for requested_status in [
                "pending",
                "ready",
                "completed",
                "failed",
                "cancelled",
                "archived",
            ] {
                let error = service
                    .update_task_status(&scope, &task_id, requested_status)
                    .await
                    .expect_err("generic status mutation must fail closed");
                assert!(matches!(
                    error,
                    ArtifactV2Error::InvalidRequest(ref message)
                        if message == &format!(
                            "{APP_WORKFLOW_GENERIC_LIFECYCLE_DENIED}:{task_id}"
                        )
                ));
            }

            for remove_files in [false, true] {
                let error = service
                    .archive_task_with_options(&scope, &task_id, remove_files)
                    .await
                    .expect_err("generic archive/delete must fail closed");
                assert!(matches!(
                    error,
                    ArtifactV2Error::InvalidRequest(ref message)
                        if message == &format!(
                            "{APP_WORKFLOW_GENERIC_LIFECYCLE_DENIED}:{task_id}"
                        )
                ));
            }

            let error = service
                .archive_task(&scope, &task_id)
                .await
                .expect_err("direct generic archive must fail closed");
            assert!(matches!(
                error,
                ArtifactV2Error::InvalidRequest(ref message)
                    if message == &format!(
                        "{APP_WORKFLOW_GENERIC_LIFECYCLE_DENIED}:{task_id}"
                    )
            ));

            let error = service
                .delete_internal_task(&scope, &task_id)
                .await
                .expect_err("internal-task deletion must share the app namespace fence");
            assert!(matches!(
                error,
                ArtifactV2Error::InvalidRequest(ref message)
                    if message == &format!(
                        "{APP_WORKFLOW_GENERIC_LIFECYCLE_DENIED}:{task_id}"
                    )
            ));

            let retained = service
                .get_task(&scope, &task_id)
                .await
                .expect("guarded app task must remain present");
            assert_eq!(retained.state.status, source_status);
        }
    }

