    /// Records what the controller asked delegation to do, so a test can
    /// assert on the *arguments* rather than only on the effect.
    ///
    /// The arguments are the point: dispatch validates targets against the
    /// **source** agent's roster, so naming the engineer as its own source is
    /// a self-delegation that never reaches an engineer. Nothing about the
    /// gate's own state reveals that — only the call does.
    #[derive(Debug, Default)]
    struct RecordingDelegationDispatcher {
        calls: Mutex<Vec<(String, String, Vec<String>, String)>>,
    }

    #[async_trait::async_trait]
    impl crate::magician_v2::execution::agentic::delegation_dispatch::DelegationDispatcher
        for RecordingDelegationDispatcher
    {
        async fn available_targets(
            &self,
            _source_agent_id: &str,
            _principal: Option<&str>,
            _workspace: Option<&str>,
        ) -> Vec<crate::magician_v2::execution::agentic::delegation_dispatch::DelegationTarget>
        {
            Vec::new()
        }

        async fn spawn_children(
            &self,
            source_agent_id: &str,
            source_execution_id: &str,
            _source_chain_id: Option<&str>,
            targets: Vec<crate::magician_v2::execution::actions::DelegationTargetRequest>,
            _cancel: Option<tokio_util::sync::CancellationToken>,
        ) -> Result<
            crate::magician_v2::execution::agentic::delegation_dispatch::DelegationSpawnResult,
            crate::magician_v2::execution::agentic::delegation_dispatch::DispatchError,
        > {
            let context = targets
                .first()
                .map(|t| t.context.clone())
                .unwrap_or_default();
            self.calls.lock().unwrap().push((
                source_agent_id.to_string(),
                source_execution_id.to_string(),
                targets.iter().map(|t| t.target_agent_id.clone()).collect(),
                context,
            ));
            Ok(
                crate::magician_v2::execution::agentic::delegation_dispatch::DelegationSpawnResult {
                    child_executions: Vec::new(),
                    completed_reused_execution_ids: Vec::new(),
                    admission_queue_ms: 0,
                    admission_preflight_ms: 0,
                    child_shells_ready_ms: 0,
                    resource_wait_ms: 0,
                    dispatch_total_ms: 0,
                },
            )
        }
    }

    #[tokio::test]
    async fn a_red_candidate_dispatches_repair_to_the_engineer_under_the_root_agent() {
        let tmp = tempfile::TempDir::new().expect("temp dir");
        let repo = tempfile::TempDir::new().expect("repo");
        write_repo_policy(repo.path(), "false");
        let service = Arc::new(build_test_artifact_v2_service(tmp.path()));
        service.set_verification_activation(VerificationActivation::Enforce);
        let dispatcher = Arc::new(RecordingDelegationDispatcher::default());
        service.set_delegation_dispatcher(dispatcher.clone());

        let scope =
            ScopeRef::system_internal_unauthenticated(&"alpha".to_string(), &"prod".to_string());
        let (task_id, execution_id) = seed_gated_candidate(&service, &scope, repo.path()).await;
        let root_agent = service
            .get_task(&scope, &task_id)
            .await
            .expect("task")
            .manifest
            .agent_id
            .clone();

        service
            .persist_external_execution_outcome(&scope, &task_id, &execution_id, terminal_success())
            .await
            .expect("terminal outcome");

        until("repair to be dispatched", || {
            let dispatcher = Arc::clone(&dispatcher);
            async move { !dispatcher.calls.lock().unwrap().is_empty() }
        })
        .await;

        let calls = dispatcher.calls.lock().unwrap().clone();
        assert_eq!(calls.len(), 1, "exactly one repair per red round");
        let (source, source_execution, targets, context) = &calls[0];

        assert_eq!(
            source, &root_agent,
            "the delegation source must be the root's agent -- dispatch validates \
             targets against the SOURCE's roster, so naming the engineer here is a \
             self-delegation that never reaches anyone"
        );
        assert_eq!(
            targets,
            &vec!["engineer-1".to_string()],
            "repair must go to the engineer that owns the candidate"
        );
        assert_eq!(
            source_execution, &execution_id,
            "repair is a child of the held root, which is what keeps the root \
             execution untouched"
        );
        assert!(
            !context.trim().is_empty(),
            "the engineer must receive the diagnostics, not an empty request"
        );
    }

    #[tokio::test]
    async fn the_successor_a_repair_produces_re_arms_the_gate() {
        // The other half of the round trip. A repair runs as a delegated
        // child, and a child returns ABOVE the terminal seam by design -- so
        // if the successor is not noticed on the child-terminal path, the fix
        // lands and the gate waits for it forever.
        let tmp = tempfile::TempDir::new().expect("temp dir");
        let repo = tempfile::TempDir::new().expect("repo");
        write_repo_policy(repo.path(), "false");
        let service = Arc::new(build_test_artifact_v2_service(tmp.path()));
        service.set_verification_activation(VerificationActivation::Enforce);
        service.set_delegation_dispatcher(Arc::new(RecordingDelegationDispatcher::default()));

        let scope =
            ScopeRef::system_internal_unauthenticated(&"alpha".to_string(), &"prod".to_string());
        let (task_id, execution_id) = seed_gated_candidate(&service, &scope, repo.path()).await;
        service
            .persist_external_execution_outcome(&scope, &task_id, &execution_id, terminal_success())
            .await
            .expect("terminal outcome");

        let store = VerificationStore::new(
            service
                .workspace()
                .scope_root(&scope.principal(), &scope.workspace()),
            crate::magician_v2::execution::file_edit::transaction::TransactionScope {
                principal: scope.principal().to_string(),
                workspace: scope.workspace().to_string(),
            },
        );
        let gate_id = store.gate_id_for_task(&task_id).expect("gate");
        until("the gate to enter repair", || async {
            store
                .load_gate(&gate_id)
                .map(|g| g.status == GateStatus::Repairing)
                .unwrap_or(false)
        })
        .await;
        let before = store.load_gate(&gate_id).expect("gate").current_candidate;

        // The engineer lands the fix: a newer proposal under the same task,
        // and now the checks pass.
        write_repo_policy(repo.path(), "true");
        let scope_root = service
            .workspace()
            .scope_root(&scope.principal(), &scope.workspace());
        crate::magician_v2::execution::file_edit::proposal::CodeChangeProposalStore::new(
            &scope_root,
        )
        .stage_patch_with_apply_root(
            crate::magician_v2::execution::file_edit::transaction::TransactionScope {
                principal: scope.principal().to_string(),
                workspace: scope.workspace().to_string(),
            },
            "the fix",
            "--- a/src/main.rs\n+++ b/src/main.rs\n@@ -1 +1 @@\n-fn main() { }\n+fn main() {}\n",
            "session-2",
            Vec::new(),
            Some(repo.path().to_path_buf()),
            Some(task_id.clone()),
            Some(execution_id.clone()),
        )
        .expect("stage the successor");

        // ...and the repair child terminates. `register_repaired_candidate`
        // is the half of `resume_verification_after_repair` that decides
        // anything; calling it directly keeps the assertion deterministic and
        // lets the pass below surface its own error instead of losing it in a
        // spawned task.
        let rearmed = service
            .register_repaired_candidate(&scope, &task_id)
            .await
            .expect("the successor must re-arm the gate");
        assert_eq!(rearmed, gate_id);

        let after = store.load_gate(&gate_id).expect("gate");
        assert!(
            after.current_candidate.revision > before.revision,
            "the successor must advance the candidate: {:?} -> {:?}",
            before,
            after.current_candidate
        );
        assert_eq!(
            after.status,
            GateStatus::VerificationPending,
            "a re-armed gate must be waiting for a worker again"
        );

        service
            .drive_verification_gate(&scope, &gate_id)
            .await
            .expect("verifying the repaired candidate must not error");

        let settled = store.load_gate(&gate_id).expect("gate");
        assert_eq!(
            settled.status,
            GateStatus::Verified,
            "the repaired candidate passes its checks, so the gate must go green"
        );

        until("the held completion to be released", || {
            let service = Arc::clone(&service);
            let scope = scope.clone();
            let task_id = task_id.clone();
            let execution_id = execution_id.clone();
            async move {
                service
                    .get_execution(&scope, &task_id, &execution_id)
                    .await
                    .map(|e| e.state.completed_at.is_some())
                    .unwrap_or(false)
            }
        })
        .await;

        assert_eq!(
            service.verification_state_for_task(&scope, &task_id),
            VerificationState::Verified
        );
    }

    // ---------------------------------------------------------------------
    // HITL surfacing — a pending diff approval on the card and in the ear.
    //
    // Every assertion below goes through the SAME durable state a restart
    // sees: the proposal store. There is deliberately no test that pushes an
    // event, because an event is exactly what the criterion says must not be
    // the source.
    // ---------------------------------------------------------------------

    /// Stage a `Pending` code-change proposal the way an engineer does —
    /// through the store both the card and the announcement read, not through
    /// a fixture struct written straight to disk.
    fn stage_pending_proposal(
        service: &Arc<ArtifactV2Service>,
        scope: &ScopeRef,
        task_id: &str,
    ) -> crate::magician_v2::execution::file_edit::proposal::CodeChangeProposalId {
        let scope_root = service
            .workspace()
            .scope_root(&scope.principal(), &scope.workspace());
        crate::magician_v2::execution::file_edit::proposal::CodeChangeProposalStore::new(
            &scope_root,
        )
        .stage_patch_with_apply_root(
            crate::magician_v2::execution::file_edit::transaction::TransactionScope {
                principal: scope.principal().to_string(),
                workspace: scope.workspace().to_string(),
            },
            "the change",
            "--- a/src/main.rs\n+++ b/src/main.rs\n@@ -1 +1 @@\n-fn main() {}\n+fn main() { }\n",
            "session-1",
            Vec::new(),
            None,
            Some(task_id.to_string()),
            Some("exec-1".to_string()),
        )
        .expect("stage the proposal")
        .id
    }

